-- Abremi: complete database setup. Paste this whole file into Supabase → SQL Editor → Run.
-- Safe to run again. Generated by scripts/gen-seed-sql.js; do not edit by hand.

-- ═════ 0001_community.sql ═════
-- Abremi community schema
-- Accounts, reactions, follows, reviews and Art Battles shared by everyone.
--
-- Security model
--   * Row Level Security on every table: people read and write only their own rows.
--   * A reaction's role (fan / artist / critic / collector) is stamped by the server from
--     the profile, never trusted from the client, so nobody can fake a heavier vote.
--   * Critic and Collector roles can only be granted by the service role (an admin).
--   * Battle ratings change only through cast_battle_vote(), which is rate limited.
--   * Community totals are exposed as aggregates only (community_snapshot()).

-- ——— Catalog (filled by supabase/seed.sql) ———
create table if not exists public.artists (
  id text primary key,
  name text not null,
  country text not null
);

create table if not exists public.artworks (
  id text primary key,
  artist_id text not null references public.artists (id) on delete cascade,
  title text not null,
  base_elo integer not null
);
create index if not exists artworks_artist_idx on public.artworks (artist_id);

-- ——— Roles ———
create or replace function public.role_weight(r text) returns integer
language sql immutable as $$
  select case r when 'fan' then 1 when 'artist' then 3 when 'critic' then 5 when 'collector' then 9 end
$$;

-- ——— Profiles ———
create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  name text not null default 'Collector' check (char_length(name) between 1 and 40),
  country text not null default 'US' check (country ~ '^[A-Z]{2}$'),
  role text not null default 'fan' check (role in ('fan', 'artist', 'critic', 'collector')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create or replace function public.guard_profile() returns trigger
language plpgsql as $$
begin
  if tg_op = 'UPDATE' and new.id <> old.id then
    raise exception 'Profile id cannot change' using errcode = '42501';
  end if;
  if new.role in ('critic', 'collector')
     and (tg_op = 'INSERT' or new.role is distinct from old.role)
     and coalesce(auth.role(), '') <> 'service_role'
     and current_user not in ('postgres', 'supabase_admin') then
    raise exception 'Critic and Collector roles require verification' using errcode = '42501';
  end if;
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists profiles_guard on public.profiles;
create trigger profiles_guard before insert or update on public.profiles
  for each row execute function public.guard_profile();

-- Every new account gets a profile.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, name)
  values (new.id, coalesce(nullif(left(split_part(coalesce(new.email, ''), '@', 1), 40), ''), 'Collector'))
  on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- Accounts created before this migration, and a self-healing call for the client.
insert into public.profiles (id) select id from auth.users on conflict (id) do nothing;

create or replace function public.ensure_profile() returns public.profiles
language plpgsql security definer set search_path = public as $$
declare p public.profiles;
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  insert into public.profiles (id) values (auth.uid()) on conflict (id) do nothing;
  select * into p from public.profiles where id = auth.uid();
  return p;
end $$;

-- Stamp the voter's current role onto their contribution.
create or replace function public.stamp_role() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  select role into new.role from public.profiles where id = new.user_id;
  if new.role is null then
    raise exception 'Profile missing' using errcode = '42501';
  end if;
  return new;
end $$;

-- ——— Reactions: like / save (super) / pass ———
create table if not exists public.reactions (
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  artwork_id text not null references public.artworks (id) on delete cascade,
  kind text not null check (kind in ('like', 'super', 'pass')),
  role text not null default 'fan',
  created_at timestamptz not null default now(),
  primary key (user_id, artwork_id)
);
create index if not exists reactions_artwork_idx on public.reactions (artwork_id);

drop trigger if exists reactions_stamp on public.reactions;
create trigger reactions_stamp before insert or update on public.reactions
  for each row execute function public.stamp_role();

-- ——— Follows ———
create table if not exists public.follows (
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  artist_id text not null references public.artists (id) on delete cascade,
  role text not null default 'fan',
  created_at timestamptz not null default now(),
  primary key (user_id, artist_id)
);
create index if not exists follows_artist_idx on public.follows (artist_id);

drop trigger if exists follows_stamp on public.follows;
create trigger follows_stamp before insert or update on public.follows
  for each row execute function public.stamp_role();

-- ——— Critic reviews (public) ———
create table if not exists public.reviews (
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  artwork_id text not null references public.artworks (id) on delete cascade,
  rating integer not null check (rating between 1 and 5),
  body text not null default '' check (char_length(body) <= 500),
  role text not null default 'critic',
  created_at timestamptz not null default now(),
  primary key (user_id, artwork_id)
);

drop trigger if exists reviews_stamp on public.reviews;
create trigger reviews_stamp before insert or update on public.reviews
  for each row execute function public.stamp_role();

-- ——— Art Battles ———
create table if not exists public.artwork_ratings (
  artwork_id text primary key references public.artworks (id) on delete cascade,
  rating integer not null,
  votes integer not null default 0,
  updated_at timestamptz not null default now()
);

create table if not exists public.battle_votes (
  id bigint generated always as identity primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  winner_id text not null references public.artworks (id) on delete cascade,
  loser_id text not null references public.artworks (id) on delete cascade,
  role text not null,
  gain integer not null,
  loss integer not null,
  created_at timestamptz not null default now()
);
create index if not exists battle_votes_user_idx on public.battle_votes (user_id, created_at desc);

-- Same maths as src/core/elo.js: K = 16 + 4 × role weight; the loser drops 75% of the gain.
create or replace function public.cast_battle_vote(p_winner text, p_loser text)
returns table (winner_rating integer, loser_rating integer, gain integer, loss integer, crowd integer)
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  voter_role text;
  winner_artist text;
  loser_artist text;
  wr integer;
  lr integer;
  k integer;
  expected double precision;
  g integer;
  l integer;
begin
  if uid is null then
    raise exception 'Sign in to vote' using errcode = '42501';
  end if;
  select role into voter_role from profiles where id = uid;
  if voter_role is null then
    raise exception 'Profile missing' using errcode = '42501';
  end if;
  select artist_id into winner_artist from artworks where id = p_winner;
  select artist_id into loser_artist from artworks where id = p_loser;
  if winner_artist is null or loser_artist is null or p_winner = p_loser then
    raise exception 'Unknown artworks' using errcode = '22023';
  end if;
  if winner_artist = loser_artist then
    raise exception 'Battles are between different artists' using errcode = '22023';
  end if;
  if exists (select 1 from battle_votes v where v.user_id = uid and v.created_at > now() - interval '1 second') then
    raise exception 'Slow down — one vote per second' using errcode = 'P0001';
  end if;
  if exists (
    select 1 from battle_votes v
    where v.user_id = uid and v.created_at > now() - interval '10 minutes'
      and least(v.winner_id, v.loser_id) = least(p_winner, p_loser)
      and greatest(v.winner_id, v.loser_id) = greatest(p_winner, p_loser)
  ) then
    raise exception 'You already judged this pair' using errcode = 'P0001';
  end if;

  insert into artwork_ratings (artwork_id, rating)
    select id, base_elo from artworks where id in (p_winner, p_loser)
    on conflict (artwork_id) do nothing;
  -- Lock both rows in a fixed order so concurrent votes cannot deadlock.
  perform 1 from artwork_ratings where artwork_id in (p_winner, p_loser) order by artwork_id for update;
  select rating into wr from artwork_ratings where artwork_id = p_winner;
  select rating into lr from artwork_ratings where artwork_id = p_loser;

  k := 16 + 4 * role_weight(voter_role);
  expected := 1 / (1 + power(10::double precision, (lr - wr) / 400.0));
  g := greatest(1, round((k * (1 - expected))::numeric)::integer);
  l := floor(g * 0.75)::integer;

  update artwork_ratings set rating = rating + g, votes = votes + 1, updated_at = now() where artwork_id = p_winner;
  update artwork_ratings set rating = rating - l, votes = votes + 1, updated_at = now() where artwork_id = p_loser;
  insert into battle_votes (user_id, winner_id, loser_id, role, gain, loss) values (uid, p_winner, p_loser, voter_role, g, l);

  return query select wr + g, lr - l, g, l, round((expected * 100)::numeric)::integer;
end $$;

-- ——— Community totals (aggregates only; individual rows stay private) ———
create or replace function public.community_snapshot() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'reactions', coalesce((
      select json_agg(t) from (
        select artwork_id as a, kind as k, role as r, count(*)::int as n
        from reactions where kind in ('like', 'super') group by 1, 2, 3
      ) t), '[]'::json),
    'reviews', coalesce((
      select json_agg(t) from (
        select artwork_id as a, count(*)::int as n, sum(rating)::int as s from reviews group by 1
      ) t), '[]'::json),
    'follows', coalesce((
      select json_agg(t) from (
        select artist_id as a, role as r, count(*)::int as n from follows group by 1, 2
      ) t), '[]'::json),
    'ratings', coalesce((
      select json_agg(t) from (select artwork_id as a, rating as v from artwork_ratings) t
    ), '[]'::json),
    'members', (select count(*)::int from profiles)
  )
$$;

-- ——— Row Level Security ———
alter table public.artists enable row level security;
alter table public.artworks enable row level security;
alter table public.profiles enable row level security;
alter table public.reactions enable row level security;
alter table public.follows enable row level security;
alter table public.reviews enable row level security;
alter table public.artwork_ratings enable row level security;
alter table public.battle_votes enable row level security;

drop policy if exists "catalog is public" on public.artists;
create policy "catalog is public" on public.artists for select using (true);
drop policy if exists "catalog is public" on public.artworks;
create policy "catalog is public" on public.artworks for select using (true);
drop policy if exists "ratings are public" on public.artwork_ratings;
create policy "ratings are public" on public.artwork_ratings for select using (true);

drop policy if exists "read own profile" on public.profiles;
create policy "read own profile" on public.profiles for select using (id = auth.uid());
drop policy if exists "update own profile" on public.profiles;
create policy "update own profile" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());

drop policy if exists "own reactions" on public.reactions;
create policy "own reactions" on public.reactions for all using (user_id = auth.uid()) with check (user_id = auth.uid());

drop policy if exists "own follows" on public.follows;
create policy "own follows" on public.follows for all using (user_id = auth.uid()) with check (user_id = auth.uid());

drop policy if exists "reviews are public" on public.reviews;
create policy "reviews are public" on public.reviews for select using (true);
drop policy if exists "critics write reviews" on public.reviews;
create policy "critics write reviews" on public.reviews for insert
  with check (user_id = auth.uid() and exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'critic'));
drop policy if exists "delete own reviews" on public.reviews;
create policy "delete own reviews" on public.reviews for delete using (user_id = auth.uid());

drop policy if exists "read own votes" on public.battle_votes;
create policy "read own votes" on public.battle_votes for select using (user_id = auth.uid());

-- ——— Grants ———
grant usage on schema public to anon, authenticated;
grant select on public.artists, public.artworks, public.artwork_ratings, public.reviews to anon, authenticated;
grant select, update (name, country, role) on public.profiles to authenticated;
grant select, insert, update, delete on public.reactions, public.follows to authenticated;
grant insert, delete on public.reviews to authenticated;
grant select on public.battle_votes to authenticated;
revoke insert, update, delete on public.artwork_ratings, public.battle_votes from anon, authenticated;
revoke all on function public.cast_battle_vote(text, text) from public, anon;
grant execute on function public.cast_battle_vote(text, text) to authenticated;
revoke all on function public.ensure_profile() from public, anon;
grant execute on function public.ensure_profile() to authenticated;
grant execute on function public.community_snapshot() to anon, authenticated;

-- ═════ 0002_artist_uploads.sql ═════
-- Abremi artist uploads
-- Members with the Artist role publish photos of their work. Images live in the public
-- "artworks" storage bucket; each artist can only write to a folder named after their user id.
-- Published works join the shared catalog, so they appear in feeds, rankings and Art Battles.

-- ——— Member artists ———
alter table public.artists add column if not exists owner_id uuid unique references public.profiles (id) on delete cascade;
alter table public.artists add column if not exists created_at timestamptz not null default now();

-- ——— Uploaded artworks (catalog rows keep these columns empty) ———
alter table public.artworks add column if not exists owner_id uuid references public.profiles (id) on delete cascade;
alter table public.artworks add column if not exists category text;
alter table public.artworks add column if not exists style text;
alter table public.artworks add column if not exists medium text;
alter table public.artworks add column if not exists year integer;
alter table public.artworks add column if not exists price integer;
alter table public.artworks add column if not exists image_path text;
alter table public.artworks add column if not exists thumb_path text;
alter table public.artworks add column if not exists width integer;
alter table public.artworks add column if not exists height integer;
alter table public.artworks add column if not exists created_at timestamptz not null default now();
alter table public.artworks add column if not exists hidden boolean not null default false; -- for moderation
create index if not exists artworks_owner_idx on public.artworks (owner_id, created_at desc);

alter table public.artworks drop constraint if exists artworks_upload_valid;
alter table public.artworks add constraint artworks_upload_valid check (
  owner_id is null or (
    char_length(btrim(title)) between 1 and 60
    and category in ('oil', 'illustration', 'sculpture', 'photography', 'digital', 'street', 'ai', 'nft', 'mixed')
    and style in ('Impressionism', 'Expressionism', 'Abstract', 'Minimalism', 'Pop Art', 'Realism', 'Surrealism', 'Cubism', 'Futurism', 'Vaporwave')
    and char_length(coalesce(medium, '')) <= 80
    and year between 1900 and 2100
    and price between 10 and 10000000
    and width between 1 and 10000 and height between 1 and 10000
    and split_part(image_path, '/', 1) = owner_id::text
    and split_part(thumb_path, '/', 1) = owner_id::text
  )
);

-- Moderated works disappear for everyone.
drop policy if exists "catalog is public" on public.artworks;
create policy "catalog is public" on public.artworks for select using (not hidden);

-- ——— Image storage ———
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('artworks', 'artworks', true, 5242880, array['image/webp', 'image/jpeg', 'image/png'])
on conflict (id) do update
  set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "artists upload to their own folder" on storage.objects;
create policy "artists upload to their own folder" on storage.objects for insert to authenticated
  with check (
    bucket_id = 'artworks'
    and (storage.foldername(name))[1] = auth.uid()::text
    and exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'artist')
  );

-- Deleting (and Storage's remove API) needs the rows to be readable too, so artists can see their own folder.
drop policy if exists "artists read their own files" on storage.objects;
create policy "artists read their own files" on storage.objects for select to authenticated
  using (bucket_id = 'artworks' and (storage.foldername(name))[1] = auth.uid()::text);

drop policy if exists "artists delete their own files" on storage.objects;
create policy "artists delete their own files" on storage.objects for delete to authenticated
  using (bucket_id = 'artworks' and (storage.foldername(name))[1] = auth.uid()::text);

-- ——— Publishing ———
create or replace function public.publish_artwork(
  p_title text, p_category text, p_style text, p_medium text, p_year integer, p_price integer,
  p_image_path text, p_thumb_path text, p_width integer, p_height integer
) returns public.artworks
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  me public.profiles;
  member_artist text;
  work public.artworks;
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  select * into me from profiles where id = uid;
  if me.role is distinct from 'artist' then
    raise exception 'Switch to the Artist role to publish work' using errcode = '42501';
  end if;
  if (select count(*) from artworks a where a.owner_id = uid and a.created_at > now() - interval '1 day') >= 20 then
    raise exception 'Daily limit reached: 20 new works per day' using errcode = 'P0001';
  end if;
  if (select count(*) from storage.objects o where o.bucket_id = 'artworks' and o.name in (p_image_path, p_thumb_path)
        and (storage.foldername(o.name))[1] = uid::text) < 2 then
    raise exception 'Upload the image before publishing' using errcode = '22023';
  end if;

  member_artist := 'm_' || uid::text;
  insert into artists (id, name, country, owner_id) values (member_artist, me.name, me.country, uid)
  on conflict (id) do update set name = excluded.name, country = excluded.country;

  insert into artworks (id, artist_id, title, base_elo, owner_id, category, style, medium, year, price,
                        image_path, thumb_path, width, height)
  values ('u_' || replace(gen_random_uuid()::text, '-', ''), member_artist, btrim(p_title), 1200, uid,
          p_category, p_style, nullif(btrim(coalesce(p_medium, '')), ''), p_year, p_price,
          p_image_path, p_thumb_path, p_width, p_height)
  returning * into work;
  return work;
end $$;

-- Removes the work (and its likes, saves, reviews and ratings) and returns the files to delete.
create or replace function public.delete_artwork(p_id text)
returns table (image_path text, thumb_path text)
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  return query
    delete from artworks a where a.id = p_id and a.owner_id = auth.uid()
    returning a.image_path, a.thumb_path;
  if not found then
    raise exception 'Not your artwork' using errcode = '42501';
  end if;
end $$;

-- A member's public artist name and country follow their profile.
create or replace function public.sync_member_artist() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  update artists set name = new.name, country = new.country where owner_id = new.id;
  return new;
end $$;

drop trigger if exists profiles_sync_artist on public.profiles;
create trigger profiles_sync_artist after update of name, country on public.profiles
  for each row execute function public.sync_member_artist();

-- ——— Community snapshot, now with member artists and their newest works ———
create or replace function public.community_snapshot() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'reactions', coalesce((
      select json_agg(t) from (
        select artwork_id as a, kind as k, role as r, count(*)::int as n
        from reactions where kind in ('like', 'super') group by 1, 2, 3
      ) t), '[]'::json),
    'reviews', coalesce((
      select json_agg(t) from (
        select artwork_id as a, count(*)::int as n, sum(rating)::int as s from reviews group by 1
      ) t), '[]'::json),
    'follows', coalesce((
      select json_agg(t) from (
        select artist_id as a, role as r, count(*)::int as n from follows group by 1, 2
      ) t), '[]'::json),
    'ratings', coalesce((
      select json_agg(t) from (select artwork_id as a, rating as v from artwork_ratings) t
    ), '[]'::json),
    'members', (select count(*)::int from profiles),
    'artists', coalesce((
      select json_agg(t) from (
        select id, name, country, created_at from artists where owner_id is not null
      ) t), '[]'::json),
    'uploads', coalesce((
      select json_agg(t) from (
        select id, artist_id, title, category, style, medium, year, price,
               image_path, thumb_path, width, height, created_at
        from artworks where owner_id is not null and not hidden
        order by created_at desc limit 2000
      ) t), '[]'::json)
  )
$$;

-- ——— Grants ———
revoke all on function public.publish_artwork(text, text, text, text, integer, integer, text, text, integer, integer) from public, anon;
grant execute on function public.publish_artwork(text, text, text, text, integer, integer, text, text, integer, integer) to authenticated;
revoke all on function public.delete_artwork(text) from public, anon;
grant execute on function public.delete_artwork(text) to authenticated;
grant execute on function public.community_snapshot() to anon, authenticated;

-- ═════ 0003_member_leaderboards.sql ═════
-- Abremi member leaderboards: Top Collectors, Top Critics, Top Discoverers.
-- Same maths as src/core/leaderboards.js (tests/db.test.js checks they agree).
--
-- Privacy
--   * Members choose whether they appear (profiles.public_leaderboards, on by default).
--   * New members get a neutral display name ("Member 3F2A"), never part of their email.
--   * Boards expose display name, country, score and rank only: no ids, no emails, no activity.
--   * The viewer always sees their own standing, even when they have chosen not to appear.

alter table public.profiles add column if not exists public_leaderboards boolean not null default true;
grant update (public_leaderboards) on public.profiles to authenticated;

-- New accounts: a neutral display name instead of the start of their email address.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, name)
  values (new.id, 'Member ' || upper(substr(md5(new.id::text), 1, 4)))
  on conflict (id) do nothing;
  return new;
end $$;

create or replace function public.member_leaderboards(p_country text default null, p_limit integer default 50)
returns json
language sql stable security definer set search_path = public as $$
  with
  contrib as (
    select user_id, role,
           sum(case kind when 'like' then role_weight(role) when 'super' then 2 * role_weight(role) else 0 end)::int as pts
    from reactions group by 1, 2
  ),
  review_pts as (
    select user_id, sum(2 * rating)::int as pts, count(*)::int as n from reviews group by 1
  ),
  ordered as (
    select user_id, role_weight(role) as w,
           coalesce(sum(role_weight(role)) over (partition by artwork_id order by created_at, user_id
             rows between unbounded preceding and 1 preceding), 0) as before_w,
           sum(role_weight(role)) over (partition by artwork_id) as total_w
    from reactions where kind in ('like', 'super')
  ),
  discovery as (
    select user_id, count(*)::int as n, sum(ln(1 + (total_w - before_w - w)) / (1 + before_w)) as raw
    from ordered group by 1
  ),
  eligible as (
    select p.id, p.name, p.country, p.role
    from profiles p
    where (p.public_leaderboards or p.id = auth.uid())
      and (p_country is null or p.country = p_country)
  ),
  boards as (
    select 'collectors' as board, e.id, e.name, e.country, c.pts as score, c.pts as detail
    from eligible e join contrib c on c.user_id = e.id and c.role = 'collector'
    where e.role = 'collector' and c.pts > 0
    union all
    select 'critics', e.id, e.name, e.country,
           coalesce(c.pts, 0) + coalesce(rp.pts, 0), coalesce(rp.n, 0)
    from eligible e
    left join contrib c on c.user_id = e.id and c.role = 'critic'
    left join review_pts rp on rp.user_id = e.id
    where e.role = 'critic' and coalesce(c.pts, 0) + coalesce(rp.pts, 0) > 0
    union all
    select 'discoverers', e.id, e.name, e.country, round(100 * (1 - exp(-d.raw / 8)))::int, d.n
    from eligible e join discovery d on d.user_id = e.id
    where d.n >= 3
  ),
  ranked as (
    select b.*, rank() over (partition by board order by score desc) as rnk,
           row_number() over (partition by board order by score desc, name) as pos
    from boards b
  ),
  lim as (select greatest(1, least(coalesce(p_limit, 50), 100)) as n)
  select json_build_object(
    'collectors', coalesce((select json_agg(json_build_object('rank', rnk, 'name', name, 'country', country, 'score', score, 'detail', detail, 'me', coalesce(id = auth.uid(), false)) order by pos)
                            from ranked, lim where board = 'collectors' and rnk <= lim.n), '[]'::json),
    'critics', coalesce((select json_agg(json_build_object('rank', rnk, 'name', name, 'country', country, 'score', score, 'detail', detail, 'me', coalesce(id = auth.uid(), false)) order by pos)
                         from ranked, lim where board = 'critics' and rnk <= lim.n), '[]'::json),
    'discoverers', coalesce((select json_agg(json_build_object('rank', rnk, 'name', name, 'country', country, 'score', score, 'detail', detail, 'me', coalesce(id = auth.uid(), false)) order by pos)
                             from ranked, lim where board = 'discoverers' and rnk <= lim.n), '[]'::json),
    'me', coalesce((select json_object_agg(board, json_build_object('rank', rnk, 'score', score, 'detail', detail))
                    from ranked where id = auth.uid()), '{}'::json),
    'members', (select count(*)::int from profiles where public_leaderboards)
  )
$$;

grant execute on function public.member_leaderboards(text, integer) to anon, authenticated;

-- ═════ 0004_role_applications.sql ═════
-- Abremi role applications: members apply to become a Critic (×5) or Collector (×9);
-- admins review each application and grant or decline it. Roles still can't be self-assigned.
--
-- Make yourself an admin once, in the SQL editor:
--   insert into public.admins (user_id) select id from auth.users where email = 'you@example.com';

create table if not exists public.admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table public.admins enable row level security;
-- No policies: nobody can read or change the admin list through the API.
revoke all on public.admins from anon, authenticated;

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from admins where user_id = auth.uid())
$$;

create table if not exists public.role_applications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  role text not null check (role in ('critic', 'collector')),
  statement text not null check (char_length(statement) between 40 and 1500),
  links text[] not null default '{}' check (cardinality(links) <= 5),
  status text not null default 'pending' check (status in ('pending', 'approved', 'declined', 'withdrawn')),
  decision_note text check (char_length(coalesce(decision_note, '')) <= 500),
  created_at timestamptz not null default now(),
  decided_at timestamptz,
  decided_by uuid references auth.users (id) on delete set null
);
create index if not exists role_applications_user_idx on public.role_applications (user_id, created_at desc);
create index if not exists role_applications_pending_idx on public.role_applications (created_at) where status = 'pending';
alter table public.role_applications enable row level security;

drop policy if exists "read own applications" on public.role_applications;
create policy "read own applications" on public.role_applications for select using (user_id = auth.uid());
-- Writes only through the functions below.
revoke insert, update, delete on public.role_applications from anon, authenticated;
grant select on public.role_applications to authenticated;

-- ——— Applying ———
create or replace function public.apply_for_role(p_role text, p_statement text, p_links text[] default '{}')
returns public.role_applications
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  current_role_name text;
  clean_links text[];
  app public.role_applications;
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if p_role not in ('critic', 'collector') then
    raise exception 'You can apply to be a Critic or a Collector' using errcode = '22023';
  end if;
  select role into current_role_name from profiles where id = uid;
  if current_role_name = p_role then
    raise exception 'You already have this role' using errcode = '22023';
  end if;
  if exists (select 1 from role_applications where user_id = uid and role = p_role and status = 'pending') then
    raise exception 'You already have a pending application for this role' using errcode = 'P0001';
  end if;
  if (select count(*) from role_applications where user_id = uid and created_at > now() - interval '30 days') >= 3 then
    raise exception 'You can send three applications every 30 days' using errcode = 'P0001';
  end if;
  select coalesce(array_agg(btrim(l)), '{}') into clean_links
    from unnest(coalesce(p_links, '{}')) as l where btrim(l) <> '';
  -- (Postgres regexes cap repetition counts at 255, so the length is checked separately.)
  if exists (select 1 from unnest(clean_links) as l where l !~ '^https://[^[:space:]<>"]+$' or char_length(l) not between 12 and 300) then
    raise exception 'Links must start with https://' using errcode = '22023';
  end if;
  insert into role_applications (user_id, role, statement, links)
  values (uid, p_role, btrim(p_statement), clean_links)
  returning * into app;
  return app;
end $$;

create or replace function public.withdraw_role_application(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  update role_applications set status = 'withdrawn', decided_at = now()
  where id = p_id and user_id = auth.uid() and status = 'pending';
  if not found then
    raise exception 'No pending application to withdraw' using errcode = 'P0001';
  end if;
end $$;

-- ——— Reviewing (admins only) ———
create or replace function public.admin_role_queue()
returns table (
  id uuid, role text, statement text, links text[], created_at timestamptz,
  applicant_name text, applicant_country text, applicant_role text, email text, member_since timestamptz,
  likes integer, saves integer, reviews integer, influence_added integer, follows integer, previous_declines integer
)
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return query
    select a.id, a.role, a.statement, a.links, a.created_at,
           p.name, p.country, p.role, u.email::text, p.created_at,
           (select count(*)::int from reactions r where r.user_id = a.user_id and r.kind = 'like'),
           (select count(*)::int from reactions r where r.user_id = a.user_id and r.kind = 'super'),
           (select count(*)::int from reviews v where v.user_id = a.user_id),
           (select coalesce(sum(case r.kind when 'like' then role_weight(r.role) when 'super' then 2 * role_weight(r.role) else 0 end), 0)::int
              from reactions r where r.user_id = a.user_id),
           (select count(*)::int from follows f where f.user_id = a.user_id),
           (select count(*)::int from role_applications d where d.user_id = a.user_id and d.status = 'declined')
    from role_applications a
    join profiles p on p.id = a.user_id
    left join auth.users u on u.id = a.user_id
    where a.status = 'pending'
    order by a.created_at;
end $$;

create or replace function public.decide_role_application(p_id uuid, p_approve boolean, p_note text default null)
returns public.role_applications
language plpgsql security definer set search_path = public as $$
declare
  app public.role_applications;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update role_applications
     set status = case when p_approve then 'approved' else 'declined' end,
         decision_note = nullif(btrim(coalesce(p_note, '')), ''),
         decided_at = now(),
         decided_by = auth.uid()
   where id = p_id and status = 'pending'
  returning * into app;
  if app.id is null then
    raise exception 'That application is no longer pending' using errcode = 'P0001';
  end if;
  if p_approve then
    update profiles set role = app.role where id = app.user_id;
  end if;
  return app;
end $$;

create or replace function public.admin_verified_members()
returns table (user_id uuid, name text, country text, role text, email text, approved_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return query
    select p.id, p.name, p.country, p.role, u.email::text,
           (select max(a.decided_at) from role_applications a where a.user_id = p.id and a.status = 'approved' and a.role = p.role)
    from profiles p left join auth.users u on u.id = p.id
    where p.role in ('critic', 'collector')
    order by p.role, p.name;
end $$;

-- Takes a verified role away (back to Fan). Past votes keep the weight they had when cast.
create or replace function public.revoke_role(p_user uuid, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update profiles set role = 'fan' where id = p_user and role in ('critic', 'collector');
  if not found then
    raise exception 'That member has no verified role' using errcode = 'P0001';
  end if;
  update role_applications set decision_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), decision_note)
   where user_id = p_user and status = 'approved';
end $$;

revoke all on function public.apply_for_role(text, text, text[]) from public, anon;
grant execute on function public.apply_for_role(text, text, text[]) to authenticated;
revoke all on function public.withdraw_role_application(uuid) from public, anon;
grant execute on function public.withdraw_role_application(uuid) to authenticated;
revoke all on function public.admin_role_queue() from public, anon;
grant execute on function public.admin_role_queue() to authenticated;
revoke all on function public.decide_role_application(uuid, boolean, text) from public, anon;
grant execute on function public.decide_role_application(uuid, boolean, text) to authenticated;
revoke all on function public.admin_verified_members() from public, anon;
grant execute on function public.admin_verified_members() to authenticated;
revoke all on function public.revoke_role(uuid, text) from public, anon;
grant execute on function public.revoke_role(uuid, text) to authenticated;
revoke all on function public.is_admin() from public, anon;
grant execute on function public.is_admin() to authenticated;

-- ═════ 0005_live_updates.sql ═════
-- Abremi live updates.
--
-- 1. community_pulse: one public row whose version goes up whenever likes, saves, follows,
--    reviews, battle ratings or uploads change. Apps subscribe to it with Supabase Realtime and
--    refetch community_snapshot() (totals only). No individual vote is ever broadcast.
-- 2. community_history: the public totals, kept once an hour, so every app compares the
--    current chart with the same previous hourly chart ("▲ 3 since 3 PM"). Real data only:
--    when there is no earlier chart from the last 24 hours, no movement is shown.

-- ——— 1. Pulse ———
create table if not exists public.community_pulse (
  id smallint primary key default 1 check (id = 1),
  version bigint not null default 0,
  changed_at timestamptz not null default now()
);
insert into public.community_pulse (id) values (1) on conflict (id) do nothing;
alter table public.community_pulse enable row level security;
drop policy if exists "pulse is public" on public.community_pulse;
create policy "pulse is public" on public.community_pulse for select using (true);
revoke insert, update, delete, truncate on public.community_pulse from anon, authenticated;
grant select on public.community_pulse to anon, authenticated;

-- At most one bump per second, so a burst of votes doesn't make every app refetch for each
-- one. Apps refetch 1.5 seconds after a bump, which also picks up changes the throttle skipped.
create or replace function public.bump_community_pulse() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  update community_pulse set version = version + 1, changed_at = clock_timestamp()
   where id = 1 and changed_at < clock_timestamp() - interval '1 second';
  return null;
end $$;
revoke all on function public.bump_community_pulse() from public, anon, authenticated;

do $$
declare t text;
begin
  foreach t in array array['reactions', 'reviews', 'follows', 'artwork_ratings', 'artworks', 'artists', 'profiles'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_pulse', t);
    execute format('create trigger %I after insert or update or delete on public.%I for each statement execute function public.bump_community_pulse()', t || '_pulse', t);
  end loop;
end $$;

-- Let Supabase Realtime send changes to the pulse row (it respects the select policy above).
do $$ begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime' and not puballtables)
     and not exists (select 1 from pg_publication_tables
                      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'community_pulse') then
    alter publication supabase_realtime add table public.community_pulse;
  end if;
end $$;

-- ——— 2. Hourly charts ———
create table if not exists public.community_history (
  hour timestamptz primary key,          -- the hour this chart belongs to
  taken_at timestamptz not null default now(),
  snapshot jsonb not null                -- community_snapshot() totals, without the upload list
);
alter table public.community_history enable row level security;
drop policy if exists "history is public" on public.community_history;
create policy "history is public" on public.community_history for select using (true);
revoke insert, update, delete, truncate on public.community_history from anon, authenticated;
grant select on public.community_history to anon, authenticated;

-- Keeps this hour's chart if it hasn't been kept yet, and drops charts older than 8 days.
create or replace function public.take_community_history() returns void
language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from community_history where hour = date_trunc('hour', now())) then
    return;
  end if;
  insert into community_history (hour, snapshot)
  values (date_trunc('hour', now()), community_snapshot()::jsonb - 'uploads' - 'artists')
  on conflict (hour) do nothing;
  delete from community_history where hour < now() - interval '8 days';
end $$;
revoke all on function public.take_community_history() from public, anon, authenticated;

-- The chart to compare against: the latest one from an earlier hour, at most 24 hours old.
-- Also keeps this hour's chart, so charts exist even where pg_cron isn't available.
create or replace function public.chart_baseline() returns json
language plpgsql security definer set search_path = public as $$
declare
  b public.community_history;
begin
  perform take_community_history();
  select * into b from community_history
   where hour < date_trunc('hour', now()) and hour >= date_trunc('hour', now()) - interval '24 hours'
   order by hour desc limit 1;
  if b.hour is null then
    return null;
  end if;
  return json_build_object('hour', b.hour, 'taken_at', b.taken_at, 'snapshot', b.snapshot);
end $$;
revoke all on function public.chart_baseline() from public;
grant execute on function public.chart_baseline() to anon, authenticated;

-- Keep a chart at the top of every hour when pg_cron is available (it is on Supabase).
do $$ begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.schedule('abremi-hourly-chart', '0 * * * *', 'select public.take_community_history()');
  end if;
exception when others then
  raise notice 'Hourly schedule not set up (%). Charts are kept on the first visit each hour instead.', sqlerrm;
end $$;

-- ═════ 0006_profiles_artworks_collections.sql ═════
-- Abremi Phase 1: audit trail, artist profiles, artwork details, and collections on the server.
-- Adds tables and columns only; nothing existing is removed. To undo, run
-- supabase/migrations/down/0006_down.sql (that drops what this file adds, including its data).

-- ——— 1. Audit trail ———
-- Sensitive actions (role decisions, role removals, artwork deletions) are recorded here.
-- Nobody can read or write the table through the API; moderators read it with admin_audit_log().
create table if not exists public.audit_events (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid references auth.users (id) on delete set null,
  action text not null check (char_length(action) between 1 and 60),
  target_type text not null check (char_length(target_type) between 1 and 40),
  target_id text not null,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists audit_events_target_idx on public.audit_events (target_type, target_id, created_at desc);
create index if not exists audit_events_created_idx on public.audit_events (created_at desc);
alter table public.audit_events enable row level security;
revoke all on public.audit_events from anon, authenticated;

create or replace function public.log_audit(p_action text, p_target_type text, p_target_id text, p_details jsonb default '{}'::jsonb)
returns void language sql security definer set search_path = public as $$
  insert into audit_events (actor_id, action, target_type, target_id, details)
  values (auth.uid(), p_action, p_target_type, p_target_id, coalesce(p_details, '{}'::jsonb))
$$;
revoke all on function public.log_audit(text, text, text, jsonb) from public, anon, authenticated;

create or replace function public.admin_audit_log(p_limit integer default 100)
returns table (id uuid, created_at timestamptz, action text, target_type text, target_id text, details jsonb, actor_email text)
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return query
    select e.id, e.created_at, e.action, e.target_type, e.target_id, e.details, u.email::text
    from audit_events e left join auth.users u on u.id = e.actor_id
    order by e.created_at desc
    limit least(greatest(coalesce(p_limit, 100), 1), 500);
end $$;
revoke all on function public.admin_audit_log(integer) from public, anon;
grant execute on function public.admin_audit_log(integer) to authenticated;

-- Role decisions and removals, now recorded. (Same rules as 0004.)
create or replace function public.decide_role_application(p_id uuid, p_approve boolean, p_note text default null)
returns public.role_applications
language plpgsql security definer set search_path = public as $$
declare
  app public.role_applications;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update role_applications
     set status = case when p_approve then 'approved' else 'declined' end,
         decision_note = nullif(btrim(coalesce(p_note, '')), ''),
         decided_at = now(),
         decided_by = auth.uid()
   where id = p_id and status = 'pending'
  returning * into app;
  if app.id is null then
    raise exception 'That application is no longer pending' using errcode = 'P0001';
  end if;
  if p_approve then
    update profiles set role = app.role where id = app.user_id;
  end if;
  perform log_audit(case when p_approve then 'role_application.approved' else 'role_application.declined' end,
                    'profile', app.user_id::text,
                    jsonb_build_object('application', app.id, 'role', app.role, 'note', app.decision_note));
  return app;
end $$;

-- Removing a role no longer overwrites the original decision note; the reason goes to the audit trail.
create or replace function public.revoke_role(p_user uuid, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare
  old_role text;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  select role into old_role from profiles where id = p_user and role in ('critic', 'collector') for update;
  if old_role is null then
    raise exception 'That member has no verified role' using errcode = 'P0001';
  end if;
  update profiles set role = 'fan' where id = p_user;
  perform log_audit('role.revoked', 'profile', p_user::text,
                    jsonb_build_object('role', old_role, 'note', nullif(btrim(coalesce(p_note, '')), '')));
end $$;

-- ——— 2. Artist profiles (on the existing artists table: no duplicate profile table) ———
alter table public.artists add column if not exists bio text;
alter table public.artists add column if not exists statement text;
alter table public.artists add column if not exists website text;
alter table public.artists add column if not exists instagram text;
alter table public.artists add column if not exists city text;
alter table public.artists add column if not exists avatar_path text;
alter table public.artists add column if not exists updated_at timestamptz not null default now();
alter table public.artists drop constraint if exists artists_profile_valid;
alter table public.artists add constraint artists_profile_valid check (
  char_length(coalesce(bio, '')) <= 1000
  and char_length(coalesce(statement, '')) <= 2000
  and (website is null or (website ~ '^https://[^[:space:]<>"]+$' and char_length(website) <= 200))
  and (instagram is null or instagram ~ '^[A-Za-z0-9._]{1,30}$')
  and char_length(coalesce(city, '')) <= 60
  and (avatar_path is null or (owner_id is not null and split_part(avatar_path, '/', 1) = owner_id::text))
);

-- The member's artist row, created on first use (publishing, or editing the profile).
create or replace function public.ensure_member_artist(p_uid uuid) returns text
language plpgsql security definer set search_path = public as $$
declare
  me public.profiles;
  member_artist text := 'm_' || p_uid::text;
begin
  select * into me from profiles where id = p_uid;
  insert into artists (id, name, country, owner_id) values (member_artist, me.name, me.country, p_uid)
  on conflict (id) do update set name = excluded.name, country = excluded.country;
  return member_artist;
end $$;
revoke all on function public.ensure_member_artist(uuid) from public, anon, authenticated;

create or replace function public.update_artist_profile(
  p_bio text, p_statement text, p_website text, p_instagram text, p_city text, p_avatar_path text
) returns public.artists
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  row public.artists;
  clean_avatar text := nullif(btrim(coalesce(p_avatar_path, '')), '');
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if not exists (select 1 from artists where owner_id = uid)
     and (select role from profiles where id = uid) is distinct from 'artist' then
    raise exception 'Switch to the Artist role to set up an artist profile' using errcode = '42501';
  end if;
  if clean_avatar is not null and not exists (
       select 1 from storage.objects o
        where o.bucket_id = 'artworks' and o.name = clean_avatar and (storage.foldername(o.name))[1] = uid::text) then
    raise exception 'Upload the portrait before saving' using errcode = '22023';
  end if;
  perform ensure_member_artist(uid);
  update artists set
    bio = nullif(btrim(coalesce(p_bio, '')), ''),
    statement = nullif(btrim(coalesce(p_statement, '')), ''),
    website = nullif(btrim(coalesce(p_website, '')), ''),
    instagram = nullif(ltrim(btrim(coalesce(p_instagram, '')), '@'), ''),
    city = nullif(btrim(coalesce(p_city, '')), ''),
    avatar_path = clean_avatar,
    updated_at = now()
  where owner_id = uid
  returning * into row;
  return row;
end $$;
revoke all on function public.update_artist_profile(text, text, text, text, text, text) from public, anon;
grant execute on function public.update_artist_profile(text, text, text, text, text, text) to authenticated;

-- Publishing uses the shared helper (same rules as 0002).
create or replace function public.publish_artwork(
  p_title text, p_category text, p_style text, p_medium text, p_year integer, p_price integer,
  p_image_path text, p_thumb_path text, p_width integer, p_height integer
) returns public.artworks
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  member_artist text;
  work public.artworks;
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if (select role from profiles where id = uid) is distinct from 'artist' then
    raise exception 'Switch to the Artist role to publish work' using errcode = '42501';
  end if;
  if (select count(*) from artworks a where a.owner_id = uid and a.created_at > now() - interval '1 day') >= 20 then
    raise exception 'Daily limit reached: 20 new works per day' using errcode = 'P0001';
  end if;
  if (select count(*) from storage.objects o where o.bucket_id = 'artworks' and o.name in (p_image_path, p_thumb_path)
        and (storage.foldername(o.name))[1] = uid::text) < 2 then
    raise exception 'Upload the image before publishing' using errcode = '22023';
  end if;
  member_artist := ensure_member_artist(uid);
  insert into artworks (id, artist_id, title, base_elo, owner_id, category, style, medium, year, price,
                        image_path, thumb_path, width, height)
  values ('u_' || replace(gen_random_uuid()::text, '-', ''), member_artist, btrim(p_title), 1200, uid,
          p_category, p_style, nullif(btrim(coalesce(p_medium, '')), ''), p_year, p_price,
          p_image_path, p_thumb_path, p_width, p_height)
  returning * into work;
  return work;
end $$;

-- ——— 3. Artwork details ———
alter table public.artworks add column if not exists description text;
alter table public.artworks add column if not exists dimensions text;
alter table public.artworks add column if not exists availability text;
alter table public.artworks add column if not exists updated_at timestamptz not null default now();
alter table public.artworks drop constraint if exists artworks_details_valid;
alter table public.artworks add constraint artworks_details_valid check (
  char_length(coalesce(description, '')) <= 2000
  and char_length(coalesce(dimensions, '')) <= 60
  -- 'sold' is what the artist reports; verified sales are a separate, later feature.
  and (availability is null or availability in ('available', 'sold', 'not_for_sale', 'on_request'))
  and (owner_id is not null or (description is null and dimensions is null and availability is null))
);

create or replace function public.update_artwork(
  p_id text, p_title text, p_category text, p_style text, p_medium text, p_year integer, p_price integer,
  p_description text, p_dimensions text, p_availability text
) returns public.artworks
language plpgsql security definer set search_path = public as $$
declare
  work public.artworks;
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  update artworks set
    title = btrim(p_title), category = p_category, style = p_style,
    medium = nullif(btrim(coalesce(p_medium, '')), ''), year = p_year, price = p_price,
    description = nullif(btrim(coalesce(p_description, '')), ''),
    dimensions = nullif(btrim(coalesce(p_dimensions, '')), ''),
    availability = coalesce(nullif(p_availability, ''), 'available'),
    updated_at = now()
  where id = p_id and owner_id = auth.uid()
  returning * into work;
  if work.id is null then
    raise exception 'Not your artwork' using errcode = '42501';
  end if;
  return work;
end $$;
revoke all on function public.update_artwork(text, text, text, text, text, integer, integer, text, text, text) from public, anon;
grant execute on function public.update_artwork(text, text, text, text, text, integer, integer, text, text, text) to authenticated;

-- Deleting a work is now recorded. (Same rules as 0002.)
create or replace function public.delete_artwork(p_id text)
returns table (image_path text, thumb_path text)
language plpgsql security definer set search_path = public as $$
declare
  gone public.artworks;
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  delete from artworks a where a.id = p_id and a.owner_id = auth.uid() returning a.* into gone;
  if gone.id is null then
    raise exception 'Not your artwork' using errcode = '42501';
  end if;
  perform log_audit('artwork.deleted', 'artwork', gone.id, jsonb_build_object('title', gone.title));
  image_path := gone.image_path;
  thumb_path := gone.thumb_path;
  return next;
end $$;

-- ——— 4. Collections (private by default) ———
create table if not exists public.collections (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 60),
  description text check (char_length(coalesce(description, '')) <= 500),
  is_private boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists collections_owner_idx on public.collections (owner_id, created_at);

create table if not exists public.collection_items (
  collection_id uuid not null references public.collections (id) on delete cascade,
  artwork_id text not null references public.artworks (id) on delete cascade,
  added_at timestamptz not null default now(),
  primary key (collection_id, artwork_id)
);
create index if not exists collection_items_artwork_idx on public.collection_items (artwork_id);

create or replace function public.guard_collection() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' and (select count(*) from collections where owner_id = new.owner_id) >= 100 then
    raise exception 'You can have up to 100 collections' using errcode = 'P0001';
  end if;
  if tg_op = 'UPDATE' and new.owner_id <> old.owner_id then
    raise exception 'Collections cannot change owner' using errcode = '42501';
  end if;
  new.name := btrim(new.name);
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists collections_guard on public.collections;
create trigger collections_guard before insert or update on public.collections
  for each row execute function public.guard_collection();

create or replace function public.guard_collection_item() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (select count(*) from collection_items where collection_id = new.collection_id) >= 500 then
    raise exception 'A collection can hold up to 500 works' using errcode = 'P0001';
  end if;
  update collections set updated_at = now() where id = new.collection_id;
  return new;
end $$;
drop trigger if exists collection_items_guard on public.collection_items;
create trigger collection_items_guard before insert on public.collection_items
  for each row execute function public.guard_collection_item();

alter table public.collections enable row level security;
alter table public.collection_items enable row level security;

drop policy if exists "own or public collections" on public.collections;
create policy "own or public collections" on public.collections for select
  using (owner_id = auth.uid() or not is_private);
drop policy if exists "create own collections" on public.collections;
create policy "create own collections" on public.collections for insert to authenticated
  with check (owner_id = auth.uid());
drop policy if exists "edit own collections" on public.collections;
create policy "edit own collections" on public.collections for update to authenticated
  using (owner_id = auth.uid()) with check (owner_id = auth.uid());
drop policy if exists "delete own collections" on public.collections;
create policy "delete own collections" on public.collections for delete to authenticated
  using (owner_id = auth.uid());

drop policy if exists "items of visible collections" on public.collection_items;
create policy "items of visible collections" on public.collection_items for select
  using (exists (select 1 from collections c where c.id = collection_id and (c.owner_id = auth.uid() or not c.is_private)));
drop policy if exists "add to own collections" on public.collection_items;
create policy "add to own collections" on public.collection_items for insert to authenticated
  with check (exists (select 1 from collections c where c.id = collection_id and c.owner_id = auth.uid()));
drop policy if exists "remove from own collections" on public.collection_items;
create policy "remove from own collections" on public.collection_items for delete to authenticated
  using (exists (select 1 from collections c where c.id = collection_id and c.owner_id = auth.uid()));

revoke all on public.collections, public.collection_items from anon, authenticated;
grant select on public.collections, public.collection_items to anon, authenticated;
grant insert, delete on public.collections, public.collection_items to authenticated;
grant update (name, description, is_private) on public.collections to authenticated;

-- A shared (public) collection, with the curator's display name. Private ones are never returned
-- to anyone but their owner.
create or replace function public.public_collection(p_id uuid) returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'id', c.id, 'name', c.name, 'description', c.description, 'is_private', c.is_private,
    'owner_name', p.name, 'mine', coalesce(c.owner_id = auth.uid(), false), 'updated_at', c.updated_at,
    'items', coalesce((select json_agg(i.artwork_id order by i.added_at desc)
                         from collection_items i join artworks a on a.id = i.artwork_id
                        where i.collection_id = c.id and not a.hidden), '[]'::json))
  from collections c join profiles p on p.id = c.owner_id
  where c.id = p_id and (not c.is_private or c.owner_id = auth.uid())
$$;
revoke all on function public.public_collection(uuid) from public;
grant execute on function public.public_collection(uuid) to anon, authenticated;

-- ——— 5. Community snapshot: artist profiles and artwork details too (still totals only) ———
create or replace function public.community_snapshot() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'reactions', coalesce((
      select json_agg(t) from (
        select artwork_id as a, kind as k, role as r, count(*)::int as n
        from reactions where kind in ('like', 'super') group by 1, 2, 3
      ) t), '[]'::json),
    'reviews', coalesce((
      select json_agg(t) from (
        select artwork_id as a, count(*)::int as n, sum(rating)::int as s from reviews group by 1
      ) t), '[]'::json),
    'follows', coalesce((
      select json_agg(t) from (
        select artist_id as a, role as r, count(*)::int as n from follows group by 1, 2
      ) t), '[]'::json),
    'ratings', coalesce((
      select json_agg(t) from (select artwork_id as a, rating as v from artwork_ratings) t
    ), '[]'::json),
    'members', (select count(*)::int from profiles),
    'artists', coalesce((
      select json_agg(t) from (
        select id, name, country, created_at, bio, statement, website, instagram, city, avatar_path
        from artists where owner_id is not null
      ) t), '[]'::json),
    'uploads', coalesce((
      select json_agg(t) from (
        select id, artist_id, title, category, style, medium, year, price,
               image_path, thumb_path, width, height, created_at, description, dimensions, availability
        from artworks where owner_id is not null and not hidden
        order by created_at desc limit 2000
      ) t), '[]'::json)
  )
$$;
grant execute on function public.community_snapshot() to anon, authenticated;

-- ═════ 0007_ranking_integrity.sql ═════
-- Abremi Phase 2A: ranking integrity, server-side scores and achievements.
-- Adds only; undo with supabase/migrations/down/0007_down.sql.
--
-- What counts toward rankings, leaderboards and achievements (published on the Rankings page):
--   * one like or save per member per work (already enforced), never on your own work;
--   * follows of your own artist page don't count; reviews of your own work don't count;
--   * reactions a moderator excluded after reviewing an integrity flag don't count.
-- Five separate scores, never combined and never affected by payments:
--   artwork popularity, artist reputation, critic credibility, collector interest, battle performance.

-- ——— 1. Exclusions ———
alter table public.reactions add column if not exists excluded boolean not null default false;
alter table public.reactions add column if not exists excluded_reason text;

-- Members can't set or clear the exclusion themselves (their own-row RLS allows other updates).
create or replace function public.guard_reaction_exclusion() returns trigger
language plpgsql as $$
begin
  if current_user in ('postgres', 'supabase_admin') or coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.excluded := false;
    new.excluded_reason := null;
  elsif new.excluded is distinct from old.excluded or new.excluded_reason is distinct from old.excluded_reason then
    new.excluded := old.excluded;
    new.excluded_reason := old.excluded_reason;
  end if;
  return new;
end $$;
drop trigger if exists reactions_guard_exclusion on public.reactions;
create trigger reactions_guard_exclusion before insert or update on public.reactions
  for each row execute function public.guard_reaction_exclusion();

-- The rows that count. These views read everyone's rows, so the API can't query them directly.
create or replace view public.counted_reactions as
  select r.* from public.reactions r
  join public.artworks a on a.id = r.artwork_id
  where not r.excluded and (a.owner_id is null or a.owner_id <> r.user_id);
create or replace view public.counted_follows as
  select f.* from public.follows f
  join public.artists ar on ar.id = f.artist_id
  where ar.owner_id is null or ar.owner_id <> f.user_id;
create or replace view public.counted_reviews as
  select v.* from public.reviews v
  join public.artworks a on a.id = v.artwork_id
  where a.owner_id is null or a.owner_id <> v.user_id;
revoke all on public.counted_reactions, public.counted_follows, public.counted_reviews from public, anon, authenticated;

-- ——— 2. Rate limits ———
create or replace function public.rate_limit_activity() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  recent integer;
  cap integer := case tg_table_name when 'reactions' then 600 when 'follows' then 200 else 1000 end;
begin
  execute format('select count(*) from public.%I where user_id = $1 and created_at > now() - interval ''1 hour''', tg_table_name)
    into recent using new.user_id;
  if recent >= cap then
    raise exception 'Slow down: you can add % % an hour', cap, case tg_table_name when 'reactions' then 'likes and saves' else 'follows' end
      using errcode = 'P0001';
  end if;
  return new;
end $$;
drop trigger if exists reactions_rate_limit on public.reactions;
create trigger reactions_rate_limit before insert on public.reactions
  for each row execute function public.rate_limit_activity();
drop trigger if exists follows_rate_limit on public.follows;
create trigger follows_rate_limit before insert on public.follows
  for each row execute function public.rate_limit_activity();

-- You can't vote your own work up in Art Battles.
create or replace function public.guard_battle_vote() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from artworks where id = new.winner_id and owner_id = new.user_id) then
    raise exception 'You can’t vote for your own work' using errcode = '42501';
  end if;
  return new;
end $$;
drop trigger if exists battle_votes_guard on public.battle_votes;
create trigger battle_votes_guard before insert on public.battle_votes
  for each row execute function public.guard_battle_vote();

-- ——— 3. Server-side scores ———
-- Artwork popularity (all time): Σ role weight × (1 for a like, 2 for a save) + 2 × stars of each critic review.
-- Trending: the same likes and saves, each halved for every 7 days of age.
-- Collector interest: the collector share of popularity. Critic credibility: critic review points and count.
create or replace function public.artwork_scores()
returns table (artwork_id text, popularity integer, trending numeric, collector integer, critic integer, reviews integer)
language sql stable security definer set search_path = public as $$
  with r as (
    select artwork_id,
           sum(case kind when 'like' then role_weight(role) when 'super' then 2 * role_weight(role) else 0 end) as pts,
           sum(case kind when 'like' then role_weight(role) when 'super' then 2 * role_weight(role) else 0 end
               * power(0.5, extract(epoch from (now() - created_at)) / 604800.0)) as trend,
           sum(case when role = 'collector' then case kind when 'like' then 9 when 'super' then 18 else 0 end else 0 end) as coll
    from counted_reactions where kind in ('like', 'super') group by 1
  ),
  v as (select artwork_id, sum(2 * rating) as pts, count(*) as n from counted_reviews group by 1)
  select coalesce(r.artwork_id, v.artwork_id),
         round(coalesce(r.pts, 0) + coalesce(v.pts, 0))::int,
         round(coalesce(r.trend, 0)::numeric, 2),
         coalesce(r.coll, 0)::int,
         coalesce(v.pts, 0)::int,
         coalesce(v.n, 0)::int
  from r full join v on v.artwork_id = r.artwork_id
$$;
revoke all on function public.artwork_scores() from public, anon, authenticated;

-- Artist reputation: the popularity of their works plus Σ role weight of their followers.
create or replace function public.artist_scores()
returns table (artist_id text, country text, reputation integer, created_at timestamptz)
language sql stable security definer set search_path = public as $$
  with works as (
    select a.artist_id, sum(s.popularity) as pts from artwork_scores() s join artworks a on a.id = s.artwork_id group by 1
  ),
  fol as (select artist_id, sum(role_weight(role)) as pts from counted_follows group by 1)
  select ar.id, ar.country, (coalesce(w.pts, 0) + coalesce(f.pts, 0))::int, ar.created_at
  from artists ar left join works w on w.artist_id = ar.id left join fol f on f.artist_id = ar.id
  where coalesce(w.pts, 0) + coalesce(f.pts, 0) > 0
$$;
revoke all on function public.artist_scores() from public, anon, authenticated;

-- ——— 4. Community snapshot: counted rows only, plus the server's scores ———
create or replace function public.community_snapshot() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'reactions', coalesce((
      select json_agg(t) from (
        select artwork_id as a, kind as k, role as r, count(*)::int as n
        from counted_reactions where kind in ('like', 'super') group by 1, 2, 3
      ) t), '[]'::json),
    'reviews', coalesce((
      select json_agg(t) from (
        select artwork_id as a, count(*)::int as n, sum(rating)::int as s from counted_reviews group by 1
      ) t), '[]'::json),
    'follows', coalesce((
      select json_agg(t) from (
        select artist_id as a, role as r, count(*)::int as n from counted_follows group by 1, 2
      ) t), '[]'::json),
    'ratings', coalesce((
      select json_agg(t) from (select artwork_id as a, rating as v, votes as n from artwork_ratings) t
    ), '[]'::json),
    'scores', coalesce((
      select json_agg(x) from (
        select artwork_id as a, popularity as p, trending as t, collector as c, critic as cr from artwork_scores()
      ) x), '[]'::json),
    'artist_scores', coalesce((
      select json_agg(t) from (select artist_id as a, reputation as s from artist_scores()) t
    ), '[]'::json),
    'members', (select count(*)::int from profiles),
    'artists', coalesce((
      select json_agg(t) from (
        select id, name, country, created_at, bio, statement, website, instagram, city, avatar_path
        from artists where owner_id is not null
      ) t), '[]'::json),
    'uploads', coalesce((
      select json_agg(t) from (
        select id, artist_id, title, category, style, medium, year, price,
               image_path, thumb_path, width, height, created_at, description, dimensions, availability
        from artworks where owner_id is not null and not hidden
        order by created_at desc limit 2000
      ) t), '[]'::json)
  )
$$;
grant execute on function public.community_snapshot() to anon, authenticated;

-- Member leaderboards count the same rows (same rules as 0003 otherwise).
create or replace function public.member_leaderboards(p_country text default null, p_limit integer default 50)
returns json
language sql stable security definer set search_path = public as $$
  with
  contrib as (
    select user_id, role,
           sum(case kind when 'like' then role_weight(role) when 'super' then 2 * role_weight(role) else 0 end)::int as pts
    from counted_reactions group by 1, 2
  ),
  review_pts as (
    select user_id, sum(2 * rating)::int as pts, count(*)::int as n from counted_reviews group by 1
  ),
  ordered as (
    select user_id, role_weight(role) as w,
           coalesce(sum(role_weight(role)) over (partition by artwork_id order by created_at, user_id
             rows between unbounded preceding and 1 preceding), 0) as before_w,
           sum(role_weight(role)) over (partition by artwork_id) as total_w
    from counted_reactions where kind in ('like', 'super')
  ),
  discovery as (
    select user_id, count(*)::int as n, sum(ln(1 + (total_w - before_w - w)) / (1 + before_w)) as raw
    from ordered group by 1
  ),
  eligible as (
    select p.id, p.name, p.country, p.role
    from profiles p
    where (p.public_leaderboards or p.id = auth.uid())
      and (p_country is null or p.country = p_country)
  ),
  boards as (
    select 'collectors' as board, e.id, e.name, e.country, c.pts as score, c.pts as detail
    from eligible e join contrib c on c.user_id = e.id and c.role = 'collector'
    where e.role = 'collector' and c.pts > 0
    union all
    select 'critics', e.id, e.name, e.country,
           coalesce(c.pts, 0) + coalesce(rp.pts, 0), coalesce(rp.n, 0)
    from eligible e
    left join contrib c on c.user_id = e.id and c.role = 'critic'
    left join review_pts rp on rp.user_id = e.id
    where e.role = 'critic' and coalesce(c.pts, 0) + coalesce(rp.pts, 0) > 0
    union all
    select 'discoverers', e.id, e.name, e.country, round(100 * (1 - exp(-d.raw / 8)))::int, d.n
    from eligible e join discovery d on d.user_id = e.id
    where d.n >= 3
  ),
  ranked as (
    select b.*, rank() over (partition by board order by score desc) as rnk,
           row_number() over (partition by board order by score desc, name) as pos
    from boards b
  ),
  lim as (select greatest(1, least(coalesce(p_limit, 50), 100)) as n)
  select json_build_object(
    'collectors', coalesce((select json_agg(json_build_object('rank', rnk, 'name', name, 'country', country, 'score', score, 'detail', detail, 'me', coalesce(id = auth.uid(), false)) order by pos)
                            from ranked, lim where board = 'collectors' and rnk <= lim.n), '[]'::json),
    'critics', coalesce((select json_agg(json_build_object('rank', rnk, 'name', name, 'country', country, 'score', score, 'detail', detail, 'me', coalesce(id = auth.uid(), false)) order by pos)
                         from ranked, lim where board = 'critics' and rnk <= lim.n), '[]'::json),
    'discoverers', coalesce((select json_agg(json_build_object('rank', rnk, 'name', name, 'country', country, 'score', score, 'detail', detail, 'me', coalesce(id = auth.uid(), false)) order by pos)
                             from ranked, lim where board = 'discoverers' and rnk <= lim.n), '[]'::json),
    'me', coalesce((select json_object_agg(board, json_build_object('rank', rnk, 'score', score, 'detail', detail))
                    from ranked where id = auth.uid()), '{}'::json),
    'members', (select count(*)::int from profiles where public_leaderboards)
  )
$$;

-- ——— 5. Integrity flags (reviewed by moderators; nothing is removed silently) ———
create table if not exists public.integrity_flags (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('new_account_burst')),
  target_type text not null,
  target_id text not null,
  details jsonb not null default '{}'::jsonb,
  status text not null default 'open' check (status in ('open', 'dismissed', 'confirmed')),
  created_at timestamptz not null default now(),
  reviewed_by uuid references auth.users (id) on delete set null,
  reviewed_at timestamptz,
  note text check (char_length(coalesce(note, '')) <= 500)
);
create index if not exists integrity_flags_open_idx on public.integrity_flags (created_at) where status = 'open';
alter table public.integrity_flags enable row level security;
revoke all on public.integrity_flags from anon, authenticated;

-- A work that got 10+ likes or saves in the last hour, at least 60% of them from accounts under 3 days old.
create or replace function public.detect_suspicious_activity() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  with burst as (
    select r.artwork_id, count(*) as total,
           count(*) filter (where p.created_at > r.created_at - interval '72 hours') as fresh,
           min(r.created_at) as since, max(r.created_at) as until
    from counted_reactions r join profiles p on p.id = r.user_id
    where r.kind in ('like', 'super') and r.created_at > now() - interval '1 hour'
    group by 1
  )
  insert into integrity_flags (kind, target_type, target_id, details)
  select 'new_account_burst', 'artwork', b.artwork_id,
         jsonb_build_object('total', b.total, 'new_accounts', b.fresh, 'since', b.since, 'until', b.until)
  from burst b
  where b.total >= 10 and b.fresh::numeric / b.total >= 0.6
    and not exists (select 1 from integrity_flags f where f.target_type = 'artwork' and f.target_id = b.artwork_id
                      and (f.status = 'open' or f.created_at > now() - interval '24 hours'));
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function public.detect_suspicious_activity() from public, anon, authenticated;

create or replace function public.admin_integrity_queue()
returns table (id uuid, kind text, target_type text, target_id text, title text, details jsonb, status text, created_at timestamptz)
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  perform detect_suspicious_activity();
  return query
    select f.id, f.kind, f.target_type, f.target_id, a.title, f.details, f.status, f.created_at
    from integrity_flags f left join artworks a on a.id = f.target_id
    where f.status = 'open' order by f.created_at;
end $$;
revoke all on function public.admin_integrity_queue() from public, anon;
grant execute on function public.admin_integrity_queue() to authenticated;

-- Confirming excludes the flagged window's likes and saves from accounts that were under 3 days old.
create or replace function public.resolve_integrity_flag(p_id uuid, p_exclude boolean, p_note text default null)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  f public.integrity_flags;
  n integer := 0;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update integrity_flags
     set status = case when p_exclude then 'confirmed' else 'dismissed' end,
         reviewed_by = auth.uid(), reviewed_at = now(), note = nullif(btrim(coalesce(p_note, '')), '')
   where id = p_id and status = 'open'
  returning * into f;
  if f.id is null then
    raise exception 'That flag is no longer open' using errcode = 'P0001';
  end if;
  if p_exclude then
    update reactions r set excluded = true, excluded_reason = 'integrity_flag:' || f.id
      from profiles p
     where p.id = r.user_id and r.artwork_id = f.target_id and r.kind in ('like', 'super') and not r.excluded
       and r.created_at between (f.details->>'since')::timestamptz and (f.details->>'until')::timestamptz
       and p.created_at > r.created_at - interval '72 hours';
    get diagnostics n = row_count;
  end if;
  perform log_audit(case when p_exclude then 'integrity_flag.confirmed' else 'integrity_flag.dismissed' end,
                    f.target_type, f.target_id, jsonb_build_object('flag', f.id, 'excluded', n, 'note', f.note));
  return n;
end $$;
revoke all on function public.resolve_integrity_flag(uuid, boolean, text) from public, anon;
grant execute on function public.resolve_integrity_flag(uuid, boolean, text) to authenticated;

-- ——— 6. Achievements, earned on the server with their evidence ———
