revoke all on public.member_achievements from anon, authenticated;
grant select on public.member_achievements to authenticated;

-- Awards what has been earned (achievements are kept once earned). Returns how many were new.
create or replace function public.award_achievements() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  with likes as (
    select r.*, count(*) over (partition by r.artwork_id order by r.created_at, r.user_id
                               rows between unbounded preceding and 1 preceding) as before_n,
           count(*) over (partition by r.artwork_id) as total_n
    from counted_reactions r where r.kind in ('like', 'super')
  ),
  follows_ranked as (
    select f.*, count(*) over (partition by f.artist_id order by f.created_at, f.user_id
                               rows between unbounded preceding and 1 preceding) as before_n,
           count(*) over (partition by f.artist_id) as total_n
    from counted_follows f
  ),
  reps as (
    select s.*, rank() over (order by s.reputation desc) as global_rank,
           rank() over (partition by s.country order by s.reputation desc) as country_rank
    from artist_scores() s
  ),
  battles as (
    select ar.artwork_id, ar.rating, ar.votes, rank() over (order by ar.rating desc) as rnk
    from artwork_ratings ar where ar.votes >= 20
  ),
  earned (user_id, code, evidence) as (
    select user_id, 'first_discovery', jsonb_build_object('artwork', (array_agg(artwork_id order by created_at))[1])
      from likes group by user_id
    union all
    (select distinct on (user_id) user_id, 'early_supporter', jsonb_build_object('artwork', artwork_id, 'likes_before', before_n, 'likes_now', total_n)
      from likes where before_n < 10 and total_n >= 50 order by user_id, created_at)
    union all
    select c.owner_id, 'master_curator', jsonb_build_object('collections', count(*))
      from collections c where (select count(*) from collection_items i where i.collection_id = c.id) >= 5
      group by c.owner_id having count(*) >= 3
    union all
    select r.user_id, 'collector_elite', jsonb_build_object('saves', count(*))
      from counted_reactions r join profiles p on p.id = r.user_id
      where r.kind = 'super' and r.role = 'collector' and p.role = 'collector'
      group by r.user_id having count(*) >= 10
    union all
    select v.user_id, 'master_critic', jsonb_build_object('reviews', count(*))
      from counted_reviews v join profiles p on p.id = v.user_id
      where p.role = 'critic' group by v.user_id having count(*) >= 10
    union all
    (select distinct on (f.user_id, m.code) f.user_id, m.code, jsonb_build_object('artist', f.artist_id, 'followers_before', f.before_n, 'followers_now', f.total_n)
      from follows_ranked f
      join (values (1000, 'early_believer_1k'), (10000, 'early_believer_10k'), (100000, 'early_believer_100k')) m(n, code)
        on f.before_n < m.n and f.total_n >= m.n
      order by f.user_id, m.code, f.created_at)
    union all
    select owner_id, 'first_work', jsonb_build_object('artwork', (array_agg(id order by created_at))[1])
      from artworks where owner_id is not null group by owner_id
    union all
    select ar.owner_id, 'top_100_global', jsonb_build_object('rank', r.global_rank, 'reputation', r.reputation)
      from reps r join artists ar on ar.id = r.artist_id where ar.owner_id is not null and r.global_rank <= 100
    union all
    select ar.owner_id, 'top_100_country', jsonb_build_object('rank', r.country_rank, 'country', r.country, 'reputation', r.reputation)
      from reps r join artists ar on ar.id = r.artist_id where ar.owner_id is not null and r.country_rank <= 100
    union all
    select ar.owner_id, 'rising_artist', jsonb_build_object('rank', r.country_rank, 'country', r.country, 'joined', ar.created_at)
      from reps r join artists ar on ar.id = r.artist_id
      where ar.owner_id is not null and r.country_rank <= 25 and ar.created_at > now() - interval '2 years'
    union all
    (select distinct on (a.owner_id) a.owner_id, 'battle_champion', jsonb_build_object('artwork', b.artwork_id, 'rank', b.rnk, 'rating', b.rating, 'battles', b.votes)
      from battles b join artworks a on a.id = b.artwork_id
      where a.owner_id is not null and b.rnk <= 10 order by a.owner_id, b.rnk)
  )
  insert into member_achievements (user_id, code, evidence)
  select user_id, code, evidence from earned
  on conflict (user_id, code) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function public.award_achievements() from public, anon, authenticated;

-- Your own achievements (awarding anything newly earned first), with their criteria and evidence.
create or replace function public.my_achievements()
returns table (code text, audience text, label text, criteria text, awarded_at timestamptz, evidence jsonb)
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  perform award_achievements();
  return query
    select d.code, d.audience, d.label, d.criteria, m.awarded_at, m.evidence
    from member_achievements m join achievement_definitions d on d.code = m.code
    where m.user_id = auth.uid() order by d.sort;
end $$;
revoke all on function public.my_achievements() from public, anon;
grant execute on function public.my_achievements() to authenticated;

-- An artist's public achievements (artist achievements only; member activity stays private).
create or replace function public.artist_achievements(p_artist_id text)
returns table (code text, label text, criteria text, awarded_at timestamptz)
language sql stable security definer set search_path = public as $$
  select d.code, d.label, d.criteria, m.awarded_at
  from artists ar
  join member_achievements m on m.user_id = ar.owner_id
  join achievement_definitions d on d.code = m.code and d.audience = 'artist'
  where ar.id = p_artist_id
  order by d.sort
$$;
revoke all on function public.artist_achievements(text) from public;
grant execute on function public.artist_achievements(text) to anon, authenticated;

-- Every 10 minutes where pg_cron is available: award achievements and look for suspicious bursts.
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('abremi-integrity', '*/10 * * * *', 'select public.detect_suspicious_activity(); select public.award_achievements();');
  end if;
exception when others then
  raise notice 'Schedule not set up (%). Achievements are awarded when members open them instead.', sqlerrm;
end $$;

-- ═════ 0008_competitions.sql ═════
-- Abremi Phase 2B: Artist Arena and Creative Challenges, one competition system.
-- Adds only; undo with supabase/migrations/down/0008_down.sql.
--
-- How a competition runs (all enforced here, not in the app):
--   entries open → artists submit one of their own published works (one entry each)
--   voting → each eligible member has one vote (all roles equal), changeable until voting closes;
--            no voting for your own entry; accounts must be 3+ days old with 5+ likes;
--            vote totals stay hidden until voting closes
--   closed → the server records places (ties share a place), awards achievements, and notifies
--            entrants and the winners' followers.

-- ——— Tables ———
create table if not exists public.competitions (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('daily', 'weekly', 'category', 'country', 'emerging', 'challenge')),
  title text not null check (char_length(btrim(title)) between 3 and 80),
  brief text not null default '' check (char_length(brief) <= 1000),
  rules text not null default '' check (char_length(rules) <= 2000),
  category text check (category is null or category in ('oil', 'illustration', 'sculpture', 'photography', 'digital', 'street', 'ai', 'nft', 'mixed')),
  country text check (country is null or country ~ '^[A-Z]{2}$'),
  entries_open_at timestamptz not null,
  voting_opens_at timestamptz not null,
  voting_closes_at timestamptz not null,
  cancelled_at timestamptz,
  closed_at timestamptz,
  results jsonb,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  constraint competitions_schedule check (entries_open_at < voting_opens_at and voting_opens_at < voting_closes_at),
  constraint competitions_scope check ((kind = 'category') = (category is not null) and (kind = 'country') = (country is not null))
);
create index if not exists competitions_closes_idx on public.competitions (voting_closes_at) where closed_at is null and cancelled_at is null;

create table if not exists public.competition_entries (
  id uuid primary key default gen_random_uuid(),
  competition_id uuid not null references public.competitions (id) on delete cascade,
  artwork_id text not null references public.artworks (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (competition_id, user_id),
  unique (competition_id, artwork_id)
);
create index if not exists competition_entries_user_idx on public.competition_entries (user_id);

create table if not exists public.competition_votes (
  competition_id uuid not null references public.competitions (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  entry_id uuid not null references public.competition_entries (id) on delete cascade,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (competition_id, user_id)
);
create index if not exists competition_votes_entry_idx on public.competition_votes (entry_id);

-- Notifications from the server (results, wins). Members read and mark only their own.
create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null,
  title text not null,
  link text,
  created_at timestamptz not null default now(),
  read_at timestamptz
);
create index if not exists notifications_user_idx on public.notifications (user_id, created_at desc);

alter table public.competitions enable row level security;
alter table public.competition_entries enable row level security;
alter table public.competition_votes enable row level security;
alter table public.notifications enable row level security;

drop policy if exists "competitions are public" on public.competitions;
create policy "competitions are public" on public.competitions for select using (true);
drop policy if exists "entries are public" on public.competition_entries;
create policy "entries are public" on public.competition_entries for select using (true);
drop policy if exists "read own votes" on public.competition_votes;
create policy "read own votes" on public.competition_votes for select using (user_id = auth.uid());
drop policy if exists "read own notifications" on public.notifications;
create policy "read own notifications" on public.notifications for select using (user_id = auth.uid());

revoke all on public.competitions, public.competition_entries, public.competition_votes, public.notifications from anon, authenticated;
grant select on public.competitions, public.competition_entries to anon, authenticated;
grant select on public.competition_votes, public.notifications to authenticated;

-- ——— Achievements for competitions ———
insert into public.achievement_definitions (code, audience, label, criteria, sort) values
  ('first_entry', 'artist', 'First Entry', 'Entered a first Arena competition or Creative Challenge.', 150),
  ('podium_finish', 'artist', 'Podium Finish', 'Placed in the top 3 of an Arena competition or Creative Challenge.', 160),
  ('competition_winner', 'artist', 'Competition Winner', 'Won an Arena competition or Creative Challenge (1st place, ties included).', 170)
on conflict (code) do update set audience = excluded.audience, label = excluded.label, criteria = excluded.criteria, sort = excluded.sort;

-- ——— Phases ———
create or replace function public.competition_phase(c public.competitions) returns text
language sql stable as $$
  select case
    when c.cancelled_at is not null then 'cancelled'
    when now() < c.entries_open_at then 'upcoming'
    when now() < c.voting_opens_at then 'entries'
    when now() < c.voting_closes_at then 'voting'
    else 'closed'
  end
$$;

-- Whether a member may vote (shown in the app, enforced in cast_competition_vote).
create or replace function public.voting_eligibility(p_user uuid) returns text
language sql stable security definer set search_path = public as $$
  select case
    when p_user is null then 'Sign in to vote'
    when (select created_at from profiles where id = p_user) > now() - interval '3 days' then 'New accounts can vote after 3 days'
    when (select count(*) from counted_reactions where user_id = p_user and kind in ('like', 'super')) < 5 then 'Like at least 5 works to vote'
    else null
  end
$$;
revoke all on function public.voting_eligibility(uuid) from public, anon, authenticated;

-- ——— Moderators: create and cancel ———
create or replace function public.create_competition(
  p_kind text, p_title text, p_brief text, p_rules text, p_category text, p_country text,
  p_entries_open_at timestamptz, p_voting_opens_at timestamptz, p_voting_closes_at timestamptz
) returns public.competitions
language plpgsql security definer set search_path = public as $$
declare c public.competitions;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  if p_voting_closes_at > now() + interval '90 days' then
    raise exception 'Competitions can run for up to 90 days' using errcode = '22023';
  end if;
  insert into competitions (kind, title, brief, rules, category, country, entries_open_at, voting_opens_at, voting_closes_at, created_by)
  values (p_kind, btrim(p_title), btrim(coalesce(p_brief, '')), btrim(coalesce(p_rules, '')),
          nullif(p_category, ''), nullif(upper(coalesce(p_country, '')), ''),
          p_entries_open_at, p_voting_opens_at, p_voting_closes_at, auth.uid())
  returning * into c;
  perform log_audit('competition.created', 'competition', c.id::text, jsonb_build_object('title', c.title, 'kind', c.kind));
  return c;
end $$;

create or replace function public.cancel_competition(p_id uuid, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare c public.competitions;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update competitions set cancelled_at = now() where id = p_id and cancelled_at is null and closed_at is null returning * into c;
  if c.id is null then
    raise exception 'That competition has already ended' using errcode = 'P0001';
  end if;
  perform log_audit('competition.cancelled', 'competition', c.id::text, jsonb_build_object('title', c.title, 'note', nullif(btrim(coalesce(p_note, '')), '')));
end $$;

-- ——— Artists: enter and withdraw ———
create or replace function public.enter_competition(p_competition uuid, p_artwork text) returns public.competition_entries
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  c public.competitions;
  w public.artworks;
  ar public.artists;
  e public.competition_entries;
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  select * into c from competitions where id = p_competition;
  if c.id is null then
    raise exception 'Competition not found' using errcode = 'P0002';
  end if;
  if competition_phase(c) <> 'entries' then
    raise exception 'Entries are not open' using errcode = 'P0001';
  end if;
  select * into w from artworks where id = p_artwork;
  if w.id is null or w.owner_id is distinct from uid or w.hidden then
    raise exception 'You can only enter your own published work' using errcode = '42501';
  end if;
  select * into ar from artists where id = w.artist_id;
  if c.kind = 'category' and w.category is distinct from c.category then
    raise exception 'This competition is for a different medium' using errcode = '22023';
  end if;
  if c.kind = 'country' and ar.country is distinct from c.country then
    raise exception 'This competition is for artists from another country' using errcode = '22023';
  end if;
  if c.kind = 'emerging' and ar.created_at < now() - interval '12 months' then
    raise exception 'Emerging competitions are for artists who joined in the last 12 months' using errcode = '22023';
  end if;
  insert into competition_entries (competition_id, artwork_id, user_id) values (c.id, w.id, uid) returning * into e;
  insert into member_achievements (user_id, code, evidence)
  values (uid, 'first_entry', jsonb_build_object('competition', c.id, 'artwork', w.id))
  on conflict (user_id, code) do nothing;
  return e;
exception when unique_violation then
  raise exception 'You already have an entry in this competition' using errcode = 'P0001';
end $$;

create or replace function public.withdraw_entry(p_competition uuid) returns void
language plpgsql security definer set search_path = public as $$
declare c public.competitions;
begin
  select * into c from competitions where id = p_competition;
  if c.id is null or competition_phase(c) <> 'entries' then
    raise exception 'Entries can be withdrawn only while entries are open' using errcode = 'P0001';
  end if;
  delete from competition_entries where competition_id = p_competition and user_id = auth.uid();
  if not found then
    raise exception 'You have no entry in this competition' using errcode = 'P0001';
  end if;
end $$;

-- ——— Members: one vote each ———
create or replace function public.cast_competition_vote(p_competition uuid, p_entry uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  c public.competitions;
  e public.competition_entries;
  why text;
begin
  select * into c from competitions where id = p_competition;
  if c.id is null or competition_phase(c) <> 'voting' then
    raise exception 'Voting is not open' using errcode = 'P0001';
  end if;
  why := voting_eligibility(uid);
  if why is not null then
    raise exception '%', why using errcode = '42501';
  end if;
  select * into e from competition_entries where id = p_entry and competition_id = p_competition;
  if e.id is null then
    raise exception 'That entry is not in this competition' using errcode = '22023';
  end if;
  if e.user_id = uid then
    raise exception 'You can’t vote for your own entry' using errcode = '42501';
  end if;
  insert into competition_votes (competition_id, user_id, entry_id) values (c.id, uid, e.id)
  on conflict (competition_id, user_id) do update set entry_id = excluded.entry_id, updated_at = now();
end $$;

-- ——— Closing: places, achievements, notifications ———
create or replace function public.finalize_competition(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  c public.competitions;
  res jsonb;
begin
  select * into c from competitions where id = p_id for update;
  if c.id is null or c.closed_at is not null or c.cancelled_at is not null or now() < c.voting_closes_at then
    return;
  end if;
  with tally as (
    select e.id, e.artwork_id, e.user_id, e.created_at, count(v.user_id)::int as votes
    from competition_entries e left join competition_votes v on v.entry_id = e.id
    where e.competition_id = c.id group by e.id
  ),
  placed as (
    select t.*, case when t.votes > 0 then rank() over (order by t.votes desc)::int end as place from tally t
  )
  select coalesce(jsonb_agg(jsonb_build_object('entry', id, 'artwork', artwork_id, 'votes', votes, 'place', place)
                            order by place nulls last, created_at), '[]'::jsonb)
    into res from placed;
  update competitions set closed_at = now(), results = jsonb_build_object('entries', res, 'voters', (select count(*) from competition_votes where competition_id = c.id))
   where id = c.id;

  insert into member_achievements (user_id, code, evidence)
  select e.user_id, x.code, jsonb_build_object('competition', c.id, 'title', c.title, 'place', (r->>'place')::int, 'artwork', r->>'artwork')
  from jsonb_array_elements(res) r
  join competition_entries e on e.id = (r->>'entry')::uuid
  join (values ('competition_winner', 1), ('podium_finish', 3)) x(code, max_place) on (r->>'place')::int <= x.max_place
  on conflict (user_id, code) do nothing;

  -- Entrants hear how they did; followers of the winners hear about the win.
  insert into notifications (user_id, kind, title, link)
  select e.user_id, 'competition_result',
         case when (r->>'place') is null then 'Results are in for “' || c.title || '”'
              else 'Your entry placed ' || (r->>'place') || case (r->>'place')::int when 1 then 'st' when 2 then 'nd' when 3 then 'rd' else 'th' end || ' in “' || c.title || '”' end,
         'competition/' || c.id
  from jsonb_array_elements(res) r join competition_entries e on e.id = (r->>'entry')::uuid;
  insert into notifications (user_id, kind, title, link)
  select distinct f.user_id, 'competition_win', ar.name || ' won “' || c.title || '”', 'competition/' || c.id
  from jsonb_array_elements(res) r
  join artworks w on w.id = r->>'artwork'
  join artists ar on ar.id = w.artist_id
  join counted_follows f on f.artist_id = ar.id
  where (r->>'place')::int = 1;
end $$;
revoke all on function public.finalize_competition(uuid) from public, anon, authenticated;

create or replace function public.close_due_competitions() returns integer
language plpgsql security definer set search_path = public as $$
declare
  c record;
  n integer := 0;
begin
  for c in select id from competitions where closed_at is null and cancelled_at is null and voting_closes_at <= now() loop
    perform finalize_competition(c.id);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.close_due_competitions() from public, anon, authenticated;

-- ——— Reading ———
-- The Arena: every competition with its phase, entry count, and your entry and vote.
create or replace function public.arena() returns json
language plpgsql security definer set search_path = public as $$
begin
  perform close_due_competitions(); -- results appear on time even where pg_cron isn't available
  return coalesce((
    select json_agg(json_build_object(
      'id', c.id, 'kind', c.kind, 'title', c.title, 'brief', c.brief, 'category', c.category, 'country', c.country,
      'entries_open_at', c.entries_open_at, 'voting_opens_at', c.voting_opens_at, 'voting_closes_at', c.voting_closes_at,
      'phase', competition_phase(c),
      'entries', (select count(*) from competition_entries e where e.competition_id = c.id),
      'my_entry', (select e.artwork_id from competition_entries e where e.competition_id = c.id and e.user_id = auth.uid()),
      'winner', (select r->>'artwork' from jsonb_array_elements(c.results->'entries') r where (r->>'place')::int = 1 limit 1)
    ) order by c.voting_closes_at desc)
    from competitions c
    where c.cancelled_at is null or c.cancelled_at > now() - interval '7 days'
  ), '[]'::json);
end $$;
revoke all on function public.arena() from public;
grant execute on function public.arena() to anon, authenticated;

-- One competition: rules, entries, your vote and whether you can vote; vote totals only once closed.
create or replace function public.competition_detail(p_id uuid) returns json
language plpgsql security definer set search_path = public as $$
declare c public.competitions;
begin
  perform finalize_competition(p_id);
  select * into c from competitions where id = p_id;
  if c.id is null then
    return null;
  end if;
  return json_build_object(
    'id', c.id, 'kind', c.kind, 'title', c.title, 'brief', c.brief, 'rules', c.rules, 'category', c.category, 'country', c.country,
    'entries_open_at', c.entries_open_at, 'voting_opens_at', c.voting_opens_at, 'voting_closes_at', c.voting_closes_at,
    'phase', competition_phase(c), 'results', c.results,
    'entries', coalesce((select json_agg(json_build_object('id', e.id, 'artwork', e.artwork_id, 'mine', e.user_id = auth.uid()) order by e.created_at)
                         from competition_entries e join artworks w on w.id = e.artwork_id
                         where e.competition_id = c.id and not w.hidden), '[]'::json),
    'my_vote', (select v.entry_id from competition_votes v where v.competition_id = c.id and v.user_id = auth.uid()),
    'can_vote', voting_eligibility(auth.uid()) is null,
    'vote_blocker', voting_eligibility(auth.uid())
  );
end $$;
revoke all on function public.competition_detail(uuid) from public;
grant execute on function public.competition_detail(uuid) to anon, authenticated;

create or replace function public.mark_notifications_read() returns void
language sql security definer set search_path = public as $$
  update notifications set read_at = now() where user_id = auth.uid() and read_at is null
$$;

-- Grants for the member and moderator functions.
revoke all on function public.create_competition(text, text, text, text, text, text, timestamptz, timestamptz, timestamptz) from public, anon;
grant execute on function public.create_competition(text, text, text, text, text, text, timestamptz, timestamptz, timestamptz) to authenticated;
revoke all on function public.cancel_competition(uuid, text) from public, anon;
grant execute on function public.cancel_competition(uuid, text) to authenticated;
revoke all on function public.enter_competition(uuid, text) from public, anon;
grant execute on function public.enter_competition(uuid, text) to authenticated;
revoke all on function public.withdraw_entry(uuid) from public, anon;
grant execute on function public.withdraw_entry(uuid) to authenticated;
revoke all on function public.cast_competition_vote(uuid, uuid) from public, anon;
grant execute on function public.cast_competition_vote(uuid, uuid) to authenticated;
revoke all on function public.mark_notifications_read() from public, anon;
grant execute on function public.mark_notifications_read() to authenticated;

-- Close competitions on time where pg_cron is available (every 10 minutes).
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('abremi-competitions', '*/10 * * * *', 'select public.close_due_competitions();');
  end if;
exception when others then
  raise notice 'Schedule not set up (%). Competitions close when someone opens the Arena instead.', sqlerrm;
end $$;

-- ═════ 0009_analytics.sql ═════
-- Abremi Phase 3: Artist Studio analytics and weekly reports.
-- Adds only; undo with supabase/migrations/down/0009_down.sql.
--
-- Only metrics backed by recorded events are shown:
--   impressions (a work shown in a feed), artwork views, profile visits: recorded here;
--   likes, saves, follows: the existing rows (counted_* rules from 0007).
-- Each viewer counts once per work or page per day; artists' own views never count; members and
-- guests are counted separately (guests by an anonymous device key, so their numbers are approximate).
-- Artists only ever see totals for their own work, never who; countries with fewer than 3 people
-- are grouped as "Other". Analytics never affect rankings.

-- ——— Events ———
create table if not exists public.analytics_events (
  id bigint generated always as identity primary key,
  kind text not null check (kind in ('impression', 'artwork_view', 'profile_visit')),
  target_id text not null,
  artist_id text not null references public.artists (id) on delete cascade,
  artwork_id text references public.artworks (id) on delete cascade,
  viewer_id uuid references public.profiles (id) on delete set null,
  guest_key text check (guest_key is null or guest_key ~ '^[A-Za-z0-9-]{16,64}$'),
  viewer_role text,
  viewer_country text,
  day date not null default current_date,
  created_at timestamptz not null default now(),
  check (viewer_id is not null or guest_key is not null)
);
-- Once per viewer, target and day.
create unique index if not exists analytics_events_once_idx
  on public.analytics_events (kind, target_id, (coalesce(viewer_id::text, 'g:' || guest_key)), day);
create index if not exists analytics_events_artist_idx on public.analytics_events (artist_id, day);
create index if not exists analytics_events_viewer_idx on public.analytics_events (viewer_id, created_at) where viewer_id is not null;
create index if not exists analytics_events_guest_idx on public.analytics_events (guest_key, created_at) where guest_key is not null;
alter table public.analytics_events enable row level security;
revoke all on public.analytics_events from anon, authenticated;

-- Records a batch of up to 100 events: [{ "k": "impression" | "artwork_view" | "profile_visit", "t": target id }].
-- Signed-in members are identified by their account; guests by p_guest_key. Returns how many were new.
create or replace function public.record_events(p_events jsonb, p_guest_key text default null) returns integer
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  me public.profiles;
  recent integer;
  n integer;
begin
  if jsonb_typeof(p_events) <> 'array' or jsonb_array_length(p_events) > 100 then
    raise exception 'Send up to 100 events at a time' using errcode = '22023';
  end if;
  if uid is null and (p_guest_key is null or p_guest_key !~ '^[A-Za-z0-9-]{16,64}$') then
    return 0;
  end if;
  if uid is not null then
    select * into me from profiles where id = uid;
  end if;
  -- At most 2,000 events an hour per viewer; anything beyond is ignored.
  select count(*) into recent from analytics_events
   where created_at > now() - interval '1 hour'
     and (case when uid is not null then viewer_id = uid else viewer_id is null and guest_key = p_guest_key end);
  if recent >= 2000 then
    return 0;
  end if;
  with ev as (
    select distinct e->>'k' as kind, e->>'t' as target
    from jsonb_array_elements(p_events) e
    where e->>'k' in ('impression', 'artwork_view', 'profile_visit') and coalesce(e->>'t', '') <> ''
  ),
  resolved as (
    select ev.kind, ev.target, w.id as artwork_id, ar.id as artist_id, ar.owner_id
    from ev
    left join artworks w on ev.kind in ('impression', 'artwork_view') and w.id = ev.target and not w.hidden
    join artists ar on ar.id = case when ev.kind = 'profile_visit' then ev.target else w.artist_id end
  )
  insert into analytics_events (kind, target_id, artist_id, artwork_id, viewer_id, guest_key, viewer_role, viewer_country)
  select r.kind, r.target, r.artist_id, r.artwork_id, uid, case when uid is null then p_guest_key end, me.role, me.country
  from resolved r
  where r.owner_id is not null                -- only member artists have someone to report to
    and r.owner_id is distinct from uid       -- your own views never count
  limit greatest(0, 2000 - recent)
  on conflict do nothing;
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function public.record_events(jsonb, text) from public;
grant execute on function public.record_events(jsonb, text) to anon, authenticated;

-- ——— Summaries ———
-- One artist's totals for a period (internal: called only for the caller's own artist, or by the scheduler).
create or replace function public.artist_summary(p_artist text, p_from timestamptz, p_to timestamptz) returns jsonb
language sql stable security definer set search_path = public as $$
  with ev as (
    select kind, viewer_id is not null as member from analytics_events
    where artist_id = p_artist and created_at >= p_from and created_at < p_to
  ),
  re as (
    select r.kind from counted_reactions r join artworks w on w.id = r.artwork_id
    where w.artist_id = p_artist and r.kind in ('like', 'super') and r.created_at >= p_from and r.created_at < p_to
  )
  select jsonb_build_object(
    'impressions', jsonb_build_object('members', count(*) filter (where kind = 'impression' and member), 'guests', count(*) filter (where kind = 'impression' and not member)),
    'views', jsonb_build_object('members', count(*) filter (where kind = 'artwork_view' and member), 'guests', count(*) filter (where kind = 'artwork_view' and not member)),
    'visits', jsonb_build_object('members', count(*) filter (where kind = 'profile_visit' and member), 'guests', count(*) filter (where kind = 'profile_visit' and not member)),
    'likes', (select count(*) from re where kind = 'like'),
    'saves', (select count(*) from re where kind = 'super'),
    'followers', (select count(*) from counted_follows f where f.artist_id = p_artist and f.created_at >= p_from and f.created_at < p_to)
  ) from ev
$$;
revoke all on function public.artist_summary(text, timestamptz, timestamptz) from public, anon, authenticated;

-- The caller's Studio for the last p_days (7, 30 or 90): totals vs the previous period, daily series,
-- per-work figures, and audience by role and country (members only; small countries grouped).
create or replace function public.studio_analytics(p_days integer default 30) returns json
language plpgsql stable security definer set search_path = public as $$
declare
  me_artist text;
  days integer := case when p_days in (7, 30, 90) then p_days else 30 end;
  t_to timestamptz := date_trunc('day', now()) + interval '1 day';
  t_from timestamptz := date_trunc('day', now()) + interval '1 day' - make_interval(days => days);
  t_prev timestamptz := date_trunc('day', now()) + interval '1 day' - make_interval(days => 2 * days);
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  select id into me_artist from artists where owner_id = auth.uid();
  if me_artist is null then
    return null;
  end if;
  return json_build_object(
    'artist', me_artist, 'days', days, 'from', t_from, 'to', t_to,
    'current', artist_summary(me_artist, t_from, t_to),
    'previous', artist_summary(me_artist, t_prev, t_from),
    'followers_total', (select count(*) from counted_follows where artist_id = me_artist),
    'daily', (
      select json_agg(json_build_object(
        'day', d::date,
        'impressions', (select count(*) from analytics_events e where e.artist_id = me_artist and e.kind = 'impression' and e.day = d::date),
        'views', (select count(*) from analytics_events e where e.artist_id = me_artist and e.kind = 'artwork_view' and e.day = d::date),
        'visits', (select count(*) from analytics_events e where e.artist_id = me_artist and e.kind = 'profile_visit' and e.day = d::date),
        'likes', (select count(*) from counted_reactions r join artworks w on w.id = r.artwork_id
                   where w.artist_id = me_artist and r.kind in ('like', 'super') and r.created_at >= d and r.created_at < d + interval '1 day'),
        'followers', (select count(*) from counted_follows f where f.artist_id = me_artist and f.created_at < d + interval '1 day')
      ) order by d)
      from generate_series(t_from, t_to - interval '1 day', interval '1 day') d
    ),
    'works', coalesce((
      select json_agg(x order by x.views desc, x.likes desc) from (
        select w.id, w.title,
          (select count(*) from analytics_events e where e.artwork_id = w.id and e.kind = 'impression' and e.created_at >= t_from)::int as impressions,
          (select count(*) from analytics_events e where e.artwork_id = w.id and e.kind = 'artwork_view' and e.created_at >= t_from)::int as views,
          (select count(*) from counted_reactions r where r.artwork_id = w.id and r.kind = 'like' and r.created_at >= t_from)::int as likes,
          (select count(*) from counted_reactions r where r.artwork_id = w.id and r.kind = 'super' and r.created_at >= t_from)::int as saves
        from artworks w where w.artist_id = me_artist
      ) x), '[]'::json),
    'roles', coalesce((
      select json_object_agg(role, n) from (
        select role, count(distinct user_id) as n from (
          select r.user_id, r.role from counted_reactions r join artworks w on w.id = r.artwork_id
            where w.artist_id = me_artist and r.kind in ('like', 'super') and r.created_at >= t_from
          union all
          select f.user_id, f.role from counted_follows f where f.artist_id = me_artist and f.created_at >= t_from
        ) a group by role
      ) g), '{}'::json),
    'countries', coalesce((
      select json_agg(json_build_object('country', country, 'people', people) order by people desc, country) from (
        select case when n >= 3 then country else 'Other' end as country, sum(n)::int as people from (
          select p.country, count(*) as n from profiles p
          where p.id in (
            select r.user_id from counted_reactions r join artworks w on w.id = r.artwork_id
              where w.artist_id = me_artist and r.kind in ('like', 'super') and r.created_at >= t_from
            union select f.user_id from counted_follows f where f.artist_id = me_artist and f.created_at >= t_from
            union select e.viewer_id from analytics_events e where e.artist_id = me_artist and e.viewer_id is not null and e.created_at >= t_from)
          group by p.country
        ) c group by 1
      ) g), '[]'::json)
  );
end $$;
revoke all on function public.studio_analytics(integer) from public, anon;
grant execute on function public.studio_analytics(integer) to authenticated;

-- ——— Weekly reports ———
create table if not exists public.weekly_reports (
  user_id uuid not null references public.profiles (id) on delete cascade,
  week_start date not null,
  artist_id text not null references public.artists (id) on delete cascade,
  current jsonb not null,
  previous jsonb not null,
  created_at timestamptz not null default now(),
  primary key (user_id, week_start)
);
alter table public.weekly_reports enable row level security;
drop policy if exists "read own reports" on public.weekly_reports;
create policy "read own reports" on public.weekly_reports for select using (user_id = auth.uid());
revoke all on public.weekly_reports from anon, authenticated;
grant select on public.weekly_reports to authenticated;

-- Last week's report (Monday to Sunday, UTC) for every member artist who doesn't have it yet,
-- with an in-app notification. Also drops analytics events older than 400 days.
create or replace function public.generate_weekly_reports(p_user uuid default null) returns integer
language plpgsql security definer set search_path = public as $$
declare
  wk date := (date_trunc('week', now()) - interval '7 days')::date;
  n integer;
begin
  with made as (
    insert into weekly_reports (user_id, week_start, artist_id, current, previous)
    select ar.owner_id, wk, ar.id,
           artist_summary(ar.id, wk::timestamptz, (wk + 7)::timestamptz),
           artist_summary(ar.id, (wk - 7)::timestamptz, wk::timestamptz)
    from artists ar
    where ar.owner_id is not null and (p_user is null or ar.owner_id = p_user)
      and exists (select 1 from artworks w where w.artist_id = ar.id and w.created_at < (wk + 7)::timestamptz)
    on conflict (user_id, week_start) do nothing
    returning user_id
  )
  insert into notifications (user_id, kind, title, link)
  select user_id, 'weekly_report', 'Your weekly Studio report for ' || to_char(wk, 'Mon FMDD') || ' is ready', 'studio'
  from made;
  get diagnostics n = row_count;
  if p_user is null then
    delete from analytics_events where created_at < now() - interval '400 days';
  end if;
  return n;
end $$;
revoke all on function public.generate_weekly_reports(uuid) from public, anon, authenticated;

-- The caller's reports, newest first (making last week's first if the schedule hasn't yet).
create or replace function public.my_weekly_reports() returns setof public.weekly_reports
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  perform generate_weekly_reports(auth.uid());
  return query select * from weekly_reports where user_id = auth.uid() order by week_start desc limit 26;
end $$;
revoke all on function public.my_weekly_reports() from public, anon;
grant execute on function public.my_weekly_reports() to authenticated;

-- Mondays at 06:17 UTC where pg_cron is available.
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('abremi-weekly-reports', '17 6 * * 1', 'select public.generate_weekly_reports();');
  end if;
exception when others then
  raise notice 'Schedule not set up (%). Reports are prepared when artists open their Studio instead.', sqlerrm;
end $$;

-- ═════ 0010_radar_drops.sql ═════
-- Abremi Phase 4: Collector Radar (real inquiries between members and artists) and Drops
-- (scheduled releases). Adds only; undo with supabase/migrations/down/0010_down.sql.
--
-- Inquiries: in-app conversations only; each side sees the other's display name, nothing else.
-- Only the two participants can read a conversation; moderators see one only if it is reported.
-- Drops: an artist schedules works for release; they stay hidden until the release time.

-- ——— 1. Collector Radar ———
create table if not exists public.inquiries (
  id uuid primary key default gen_random_uuid(),
  artwork_id text references public.artworks (id) on delete cascade,      -- null: about the artist (commission, sponsorship)
  artist_id text not null references public.artists (id) on delete cascade,
  artist_user uuid not null references public.profiles (id) on delete cascade,
  sender_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('purchase', 'commission', 'question', 'sponsorship')),
  status text not null default 'open' check (status in ('open', 'closed', 'declined')),
  artist_unread boolean not null default true,
  sender_unread boolean not null default false,
  created_at timestamptz not null default now(),
  last_message_at timestamptz not null default now(),
  check (artist_user <> sender_id)
);
create index if not exists inquiries_artist_idx on public.inquiries (artist_user, last_message_at desc);
create index if not exists inquiries_sender_idx on public.inquiries (sender_id, last_message_at desc);
create index if not exists inquiries_artwork_idx on public.inquiries (artwork_id);

create table if not exists public.inquiry_messages (
  id uuid primary key default gen_random_uuid(),
  inquiry_id uuid not null references public.inquiries (id) on delete cascade,
  sender_id uuid not null references public.profiles (id) on delete cascade,
  body text not null check (char_length(btrim(body)) between 1 and 2000),
  created_at timestamptz not null default now()
);
create index if not exists inquiry_messages_thread_idx on public.inquiry_messages (inquiry_id, created_at);
create index if not exists inquiry_messages_sender_idx on public.inquiry_messages (sender_id, created_at);

create table if not exists public.member_blocks (
  user_id uuid not null references public.profiles (id) on delete cascade,
  blocked_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, blocked_id),
  check (user_id <> blocked_id)
);

create table if not exists public.inquiry_reports (
  id uuid primary key default gen_random_uuid(),
  inquiry_id uuid not null references public.inquiries (id) on delete cascade,
  reporter_id uuid not null references public.profiles (id) on delete cascade,
  reason text not null check (char_length(btrim(reason)) between 3 and 500),
  status text not null default 'open' check (status in ('open', 'dismissed', 'closed')),
  created_at timestamptz not null default now(),
  unique (inquiry_id, reporter_id)
);

alter table public.inquiries enable row level security;
alter table public.inquiry_messages enable row level security;
alter table public.member_blocks enable row level security;
alter table public.inquiry_reports enable row level security;
drop policy if exists "participants read inquiries" on public.inquiries;
create policy "participants read inquiries" on public.inquiries for select using (auth.uid() in (artist_user, sender_id));
drop policy if exists "participants read messages" on public.inquiry_messages;
create policy "participants read messages" on public.inquiry_messages for select
  using (exists (select 1 from public.inquiries i where i.id = inquiry_id and auth.uid() in (i.artist_user, i.sender_id)));
drop policy if exists "read own blocks" on public.member_blocks;
create policy "read own blocks" on public.member_blocks for select using (user_id = auth.uid());
revoke all on public.inquiries, public.inquiry_messages, public.member_blocks, public.inquiry_reports from anon, authenticated;
grant select on public.inquiries, public.inquiry_messages, public.member_blocks to authenticated;

create or replace function public.is_blocked_between(a uuid, b uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from member_blocks where (user_id = a and blocked_id = b) or (user_id = b and blocked_id = a))
$$;
revoke all on function public.is_blocked_between(uuid, uuid) from public, anon, authenticated;

-- Start a conversation about a work (or, with p_artwork null, about an artist: commission, sponsorship, question).
create or replace function public.send_inquiry(p_artwork text, p_artist text, p_kind text, p_message text) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  w public.artworks;
  ar public.artists;
  q public.inquiries;
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if (select created_at from profiles where id = uid) > now() - interval '3 days' then
    raise exception 'New accounts can send inquiries after 3 days' using errcode = '42501';
  end if;
  if p_kind not in ('purchase', 'commission', 'question', 'sponsorship') then
    raise exception 'Unknown inquiry type' using errcode = '22023';
  end if;
  if p_artwork is not null then
    select * into w from artworks where id = p_artwork;
    if w.id is null or w.hidden or (w.release_at is not null and w.release_at > now()) then
      raise exception 'Artwork not found' using errcode = 'P0002';
    end if;
    select * into ar from artists where id = w.artist_id;
    if p_kind = 'purchase' and coalesce(w.availability, 'available') not in ('available', 'on_request') then
      raise exception 'This work isn’t available' using errcode = '22023';
    end if;
  else
    select * into ar from artists where id = p_artist;
    if p_kind = 'purchase' then
      raise exception 'Choose a work to ask about buying it' using errcode = '22023';
    end if;
  end if;
  if ar.id is null or ar.owner_id is null then
    raise exception 'Sample artists can’t be contacted' using errcode = '22023';
  end if;
  if ar.owner_id = uid then
    raise exception 'That’s your own work' using errcode = '22023';
  end if;
  if is_blocked_between(uid, ar.owner_id) then
    raise exception 'You can’t contact this member' using errcode = '42501';
  end if;
  if (select count(*) from inquiries where sender_id = uid and created_at > now() - interval '1 day') >= 10 then
    raise exception 'You can start 10 conversations a day' using errcode = 'P0001';
  end if;
  if exists (select 1 from inquiries where sender_id = uid and artist_id = ar.id and status = 'open'
               and artwork_id is not distinct from w.id) then
    raise exception 'You already have an open conversation about this' using errcode = 'P0001';
  end if;
  if char_length(btrim(coalesce(p_message, ''))) < 10 then
    raise exception 'Write a little more (at least 10 characters)' using errcode = '22023';
  end if;
  insert into inquiries (artwork_id, artist_id, artist_user, sender_id, kind)
  values (w.id, ar.id, ar.owner_id, uid, p_kind) returning * into q;
  insert into inquiry_messages (inquiry_id, sender_id, body) values (q.id, uid, btrim(p_message));
  insert into notifications (user_id, kind, title, link)
  values (ar.owner_id, 'inquiry', (select name from profiles where id = uid) || ' sent you ' ||
          case p_kind when 'purchase' then 'a purchase inquiry' when 'commission' then 'a commission request'
                      when 'sponsorship' then 'a sponsorship request' else 'a question' end ||
          coalesce(' about “' || w.title || '”', ''), 'inquiry/' || q.id);
  return q.id;
end $$;

create or replace function public.reply_inquiry(p_id uuid, p_body text) returns void
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  q public.inquiries;
  other uuid;
begin
  select * into q from inquiries where id = p_id and uid in (artist_user, sender_id);
  if q.id is null then
    raise exception 'Conversation not found' using errcode = 'P0002';
  end if;
  if q.status <> 'open' then
    raise exception 'This conversation is closed' using errcode = 'P0001';
  end if;
  other := case when uid = q.artist_user then q.sender_id else q.artist_user end;
  if is_blocked_between(uid, other) then
    raise exception 'You can’t message this member' using errcode = '42501';
  end if;
  if (select count(*) from inquiry_messages where sender_id = uid and created_at > now() - interval '1 day') >= 100 then
    raise exception 'You can send 100 messages a day' using errcode = 'P0001';
  end if;
  insert into inquiry_messages (inquiry_id, sender_id, body) values (q.id, uid, btrim(coalesce(p_body, '')));
  -- One notification per unread stretch, not one per message.
  if (uid = q.artist_user and not q.sender_unread) or (uid = q.sender_id and not q.artist_unread) then
    insert into notifications (user_id, kind, title, link)
    values (other, 'inquiry_reply', (select name from profiles where id = uid) || ' replied to your conversation', 'inquiry/' || q.id);
  end if;
  update inquiries set last_message_at = now(),
         artist_unread = artist_unread or uid = sender_id,
         sender_unread = sender_unread or uid = artist_user
   where id = q.id;
end $$;

-- The artist can decline or close; the sender can close.
create or replace function public.set_inquiry_status(p_id uuid, p_status text) returns void
language plpgsql security definer set search_path = public as $$
declare q public.inquiries;
begin
  select * into q from inquiries where id = p_id and auth.uid() in (artist_user, sender_id);
  if q.id is null then
    raise exception 'Conversation not found' using errcode = 'P0002';
  end if;
  if p_status not in ('closed', 'declined') or (p_status = 'declined' and auth.uid() <> q.artist_user) then
    raise exception 'Only the artist can decline; either of you can close' using errcode = '42501';
  end if;
  update inquiries set status = p_status where id = q.id;
end $$;

create or replace function public.mark_inquiry_read(p_id uuid) returns void
language sql security definer set search_path = public as $$
  update inquiries set artist_unread = case when auth.uid() = artist_user then false else artist_unread end,
                       sender_unread = case when auth.uid() = sender_id then false else sender_unread end
   where id = p_id and auth.uid() in (artist_user, sender_id)
$$;

-- Your conversations, newest first, with the other member's display name and role only.
create or replace function public.my_inquiries() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_agg(json_build_object(
    'id', q.id, 'kind', q.kind, 'status', q.status, 'artwork', q.artwork_id, 'artist', q.artist_id,
    'side', case when q.artist_user = auth.uid() then 'artist' else 'sender' end,
    'other_name', p.name, 'other_role', p.role,
    'unread', case when q.artist_user = auth.uid() then q.artist_unread else q.sender_unread end,
    'last_message', (select left(m.body, 140) from inquiry_messages m where m.inquiry_id = q.id order by m.created_at desc limit 1),
    'last_message_at', q.last_message_at
  ) order by q.last_message_at desc), '[]'::json)
  from inquiries q
  join profiles p on p.id = case when q.artist_user = auth.uid() then q.sender_id else q.artist_user end
  where auth.uid() in (q.artist_user, q.sender_id)
$$;

create or replace function public.inquiry_thread(p_id uuid) returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'id', q.id, 'kind', q.kind, 'status', q.status, 'artwork', q.artwork_id, 'artist', q.artist_id,
    'side', case when q.artist_user = auth.uid() then 'artist' else 'sender' end,
    'other_id', case when q.artist_user = auth.uid() then q.sender_id else q.artist_user end,
    'other_name', p.name, 'other_role', p.role,
    'blocked', exists (select 1 from member_blocks b where b.user_id = auth.uid() and b.blocked_id = p.id),
    'messages', coalesce((select json_agg(json_build_object('mine', m.sender_id = auth.uid(), 'body', m.body, 'at', m.created_at) order by m.created_at)
                          from inquiry_messages m where m.inquiry_id = q.id), '[]'::json))
  from inquiries q
  join profiles p on p.id = case when q.artist_user = auth.uid() then q.sender_id else q.artist_user end
  where q.id = p_id and auth.uid() in (q.artist_user, q.sender_id)
$$;

-- Block or unblock the other member of a conversation (blocking also closes open conversations between you).
create or replace function public.set_block(p_inquiry uuid, p_block boolean) returns void
language plpgsql security definer set search_path = public as $$
declare
  q public.inquiries;
  other uuid;
begin
  select * into q from inquiries where id = p_inquiry and auth.uid() in (artist_user, sender_id);
  if q.id is null then
    raise exception 'Conversation not found' using errcode = 'P0002';
  end if;
  other := case when auth.uid() = q.artist_user then q.sender_id else q.artist_user end;
  if p_block then
    insert into member_blocks (user_id, blocked_id) values (auth.uid(), other) on conflict do nothing;
    update inquiries set status = 'closed' where status = 'open'
      and ((artist_user = auth.uid() and sender_id = other) or (artist_user = other and sender_id = auth.uid()));
  else
    delete from member_blocks where user_id = auth.uid() and blocked_id = other;
  end if;
end $$;

create or replace function public.report_inquiry(p_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from inquiries where id = p_id and auth.uid() in (artist_user, sender_id)) then
    raise exception 'Conversation not found' using errcode = 'P0002';
  end if;
  insert into inquiry_reports (inquiry_id, reporter_id, reason) values (p_id, auth.uid(), btrim(coalesce(p_reason, '')))
  on conflict (inquiry_id, reporter_id) do update set reason = excluded.reason, status = 'open', created_at = now();
end $$;

-- Moderators see a conversation only once it has been reported; opening it is recorded.
create or replace function public.admin_inquiry_reports() returns json
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return coalesce((select json_agg(json_build_object(
    'id', r.id, 'inquiry', r.inquiry_id, 'reason', r.reason, 'created_at', r.created_at,
    'reporter', rp.name, 'artist', ap.name, 'sender', sp.name, 'status', q.status,
    'messages', (select json_agg(json_build_object('from', mp.name, 'body', m.body, 'at', m.created_at) order by m.created_at)
                 from inquiry_messages m join profiles mp on mp.id = m.sender_id where m.inquiry_id = q.id)
  ) order by r.created_at)
  from inquiry_reports r join inquiries q on q.id = r.inquiry_id
  join profiles rp on rp.id = r.reporter_id join profiles ap on ap.id = q.artist_user join profiles sp on sp.id = q.sender_id
  where r.status = 'open'), '[]'::json);
end $$;

create or replace function public.resolve_inquiry_report(p_id uuid, p_close boolean, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare r public.inquiry_reports;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update inquiry_reports set status = case when p_close then 'closed' else 'dismissed' end where id = p_id and status = 'open' returning * into r;
  if r.id is null then
    raise exception 'That report is no longer open' using errcode = 'P0001';
  end if;
  if p_close then
    update inquiries set status = 'closed' where id = r.inquiry_id;
  end if;
  perform log_audit(case when p_close then 'inquiry_report.closed' else 'inquiry_report.dismissed' end, 'inquiry', r.inquiry_id::text,
                    jsonb_build_object('report', r.id, 'note', nullif(btrim(coalesce(p_note, '')), '')));
end $$;

-- Collector interest for the caller's works: inquiries, and how many verified collectors saved each (counts only).
create or replace function public.collector_interest() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_agg(json_build_object(
    'artwork', w.id,
    'inquiries', (select count(*) from inquiries q where q.artwork_id = w.id),
    'open_inquiries', (select count(*) from inquiries q where q.artwork_id = w.id and q.status = 'open'),
    'collector_saves', (select count(*) from counted_reactions r where r.artwork_id = w.id and r.kind = 'super' and r.role = 'collector')
  )), '[]'::json)
  from artworks w join artists ar on ar.id = w.artist_id
  where ar.owner_id = auth.uid()
$$;

-- ——— 2. Drops ———
create table if not exists public.drops (
  id uuid primary key default gen_random_uuid(),
  artist_id text not null references public.artists (id) on delete cascade,
  owner_id uuid not null references public.profiles (id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 3 and 80),
  description text not null default '' check (char_length(description) <= 1000),
  release_at timestamptz not null,
  teaser_artwork text references public.artworks (id) on delete set null,
  created_at timestamptz not null default now(),
  released_at timestamptz,
  cancelled_at timestamptz
);
create index if not exists drops_release_idx on public.drops (release_at) where released_at is null and cancelled_at is null;

create table if not exists public.drop_subscriptions (
  drop_id uuid not null references public.drops (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (drop_id, user_id)
);

alter table public.artworks add column if not exists drop_id uuid references public.drops (id) on delete set null;
alter table public.artworks add column if not exists release_at timestamptz;   -- hidden from everyone else until then

alter table public.drops enable row level security;
alter table public.drop_subscriptions enable row level security;
drop policy if exists "drops are public" on public.drops;
create policy "drops are public" on public.drops for select using (true);
drop policy if exists "read own drop subscriptions" on public.drop_subscriptions;
create policy "read own drop subscriptions" on public.drop_subscriptions for select using (user_id = auth.uid());
revoke all on public.drops, public.drop_subscriptions from anon, authenticated;
grant select on public.drops to anon, authenticated;
grant select on public.drop_subscriptions to authenticated;

-- Unreleased works are invisible to everyone but their artist.
drop policy if exists "catalog is public" on public.artworks;
create policy "catalog is public" on public.artworks for select
  using (not hidden and (release_at is null or release_at <= now() or owner_id = auth.uid()));

-- …and can't be liked, saved or voted on early (by guessing their id).
create or replace function public.guard_unreleased() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from artworks where id = new.artwork_id and release_at > now()) then
    raise exception 'This work hasn’t been released yet' using errcode = 'P0001';
  end if;
  return new;
end $$;
drop trigger if exists reactions_unreleased on public.reactions;
create trigger reactions_unreleased before insert or update on public.reactions for each row execute function public.guard_unreleased();
drop trigger if exists reviews_unreleased on public.reviews;
create trigger reviews_unreleased before insert on public.reviews for each row execute function public.guard_unreleased();

create or replace function public.create_drop(p_title text, p_description text, p_release_at timestamptz, p_artworks text[], p_teaser text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  ar public.artists;
  d public.drops;
begin
  select * into ar from artists where owner_id = uid;
  if uid is null or ar.id is null then
    raise exception 'Publish a work first' using errcode = '42501';
  end if;
  if p_release_at < now() + interval '10 minutes' or p_release_at > now() + interval '60 days' then
    raise exception 'Release between 10 minutes and 60 days from now' using errcode = '22023';
  end if;
  if coalesce(cardinality(p_artworks), 0) not between 1 and 12 then
    raise exception 'A drop has 1 to 12 works' using errcode = '22023';
  end if;
  if (select count(*) from artworks where id = any (p_artworks) and owner_id = uid and not hidden
        and (drop_id is null or drop_id in (select id from drops where released_at is not null or cancelled_at is not null))) <> cardinality(p_artworks) then
    raise exception 'A drop can include only your own works that aren’t in another upcoming drop' using errcode = '42501';
  end if;
  if p_teaser is not null and not (p_teaser = any (p_artworks)) then
    raise exception 'The preview must be one of the drop’s works' using errcode = '22023';
  end if;
  if (select count(*) from drops where owner_id = uid and released_at is null and cancelled_at is null) >= 3 then
    raise exception 'You can have 3 upcoming drops at a time' using errcode = 'P0001';
  end if;
  insert into drops (artist_id, owner_id, title, description, release_at, teaser_artwork)
  values (ar.id, uid, btrim(p_title), btrim(coalesce(p_description, '')), p_release_at, coalesce(p_teaser, p_artworks[1]))
  returning * into d;
  update artworks set drop_id = d.id, release_at = d.release_at where id = any (p_artworks);
  insert into notifications (user_id, kind, title, link)
  select f.user_id, 'drop_announced', ar.name || ' announced a drop: “' || d.title || '”', 'drop/' || d.id
  from counted_follows f where f.artist_id = ar.id;
  return d.id;
end $$;

-- Cancelling (by the artist, or a moderator, recorded) makes the works visible again without a release.
create or replace function public.cancel_drop(p_id uuid, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare d public.drops;
begin
  select * into d from drops where id = p_id and released_at is null and cancelled_at is null;
  if d.id is null then
    raise exception 'That drop has already been released or cancelled' using errcode = 'P0001';
  end if;
  if d.owner_id <> auth.uid() and not is_admin() then
    raise exception 'Only the artist or a moderator can cancel a drop' using errcode = '42501';
  end if;
  update drops set cancelled_at = now() where id = d.id;
  update artworks set release_at = null where drop_id = d.id;
  if d.owner_id <> auth.uid() then
    perform log_audit('drop.cancelled', 'drop', d.id::text, jsonb_build_object('title', d.title, 'note', nullif(btrim(coalesce(p_note, '')), '')));
  end if;
end $$;

create or replace function public.subscribe_drop(p_id uuid, p_on boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if p_on then
    insert into drop_subscriptions (drop_id, user_id)
    select id, auth.uid() from drops where id = p_id and released_at is null and cancelled_at is null
    on conflict do nothing;
  else
    delete from drop_subscriptions where drop_id = p_id and user_id = auth.uid();
  end if;
end $$;

-- Releases due drops: notifies followers and subscribers once. (Visibility follows release_at by itself.)
create or replace function public.release_due_drops() returns integer
language plpgsql security definer set search_path = public as $$
declare
  d record;
  n integer := 0;
begin
  for d in select dr.*, ar.name as artist_name from drops dr join artists ar on ar.id = dr.artist_id
            where dr.released_at is null and dr.cancelled_at is null and dr.release_at <= now() for update of dr loop
    update drops set released_at = now() where id = d.id;
    insert into notifications (user_id, kind, title, link)
    select u, 'drop_released', d.artist_name || '’s drop “' || d.title || '” is live', 'drop/' || d.id
    from (select f.user_id as u from counted_follows f where f.artist_id = d.artist_id
          union select s.user_id from drop_subscriptions s where s.drop_id = d.id) x
    where u <> d.owner_id;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.release_due_drops() from public, anon, authenticated;

-- Upcoming and recent drops, with a teaser (one work's thumbnail, shown blurred until release).
create or replace function public.drops_overview() returns json
language plpgsql security definer set search_path = public as $$
begin
  perform release_due_drops();
  return coalesce((select json_agg(x order by x.sort, x.release_at) from (
    select d.id, d.title, d.description, d.release_at, d.artist_id, ar.name as artist_name,
           case when d.cancelled_at is not null then 'cancelled' when d.release_at > now() then 'upcoming' else 'released' end as phase,
           (select w.thumb_path from artworks w where w.id = d.teaser_artwork) as teaser_thumb,
           (select count(*) from artworks w where w.drop_id = d.id)::int as works,
           exists (select 1 from drop_subscriptions s where s.drop_id = d.id and s.user_id = auth.uid()) as subscribed,
           d.owner_id = auth.uid() as mine,
           case when d.release_at > now() then 0 else 1 end as sort
    from drops d join artists ar on ar.id = d.artist_id
    where d.cancelled_at is null and (d.release_at > now() or d.release_at > now() - interval '14 days')
  ) x), '[]'::json);
end $$;

create or replace function public.drop_detail(p_id uuid) returns json
language plpgsql security definer set search_path = public as $$
begin
  perform release_due_drops();
  return (select json_build_object(
    'id', d.id, 'title', d.title, 'description', d.description, 'release_at', d.release_at,
    'artist_id', d.artist_id, 'artist_name', ar.name,
    'phase', case when d.cancelled_at is not null then 'cancelled' when d.release_at > now() then 'upcoming' else 'released' end,
    'teaser_thumb', (select w.thumb_path from artworks w where w.id = d.teaser_artwork),
    'works', case when d.release_at <= now() or d.owner_id = auth.uid() or d.cancelled_at is not null
                  then coalesce((select json_agg(w.id order by w.created_at) from artworks w where w.drop_id = d.id and not w.hidden), '[]'::json)
                  else '[]'::json end,
    'work_count', (select count(*) from artworks w where w.drop_id = d.id),
    'subscribed', exists (select 1 from drop_subscriptions s where s.drop_id = d.id and s.user_id = auth.uid()),
    'mine', d.owner_id = auth.uid())
  from drops d join artists ar on ar.id = d.artist_id where d.id = p_id);
end $$;

-- The caller's own unreleased works (hidden from the public snapshot until release).
create or replace function public.my_scheduled_works() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_agg(json_build_object('id', id, 'title', title, 'drop_id', drop_id, 'release_at', release_at,
                                             'thumb_path', thumb_path, 'image_path', image_path) order by release_at), '[]'::json)
  from artworks where owner_id = auth.uid() and release_at > now()
$$;

-- ——— 3. The public snapshot leaves out unreleased works ———
create or replace function public.community_snapshot() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'reactions', coalesce((
      select json_agg(t) from (
        select artwork_id as a, kind as k, role as r, count(*)::int as n
        from counted_reactions where kind in ('like', 'super') group by 1, 2, 3
      ) t), '[]'::json),
    'reviews', coalesce((
      select json_agg(t) from (
        select artwork_id as a, count(*)::int as n, sum(rating)::int as s from counted_reviews group by 1
      ) t), '[]'::json),
    'follows', coalesce((
      select json_agg(t) from (
        select artist_id as a, role as r, count(*)::int as n from counted_follows group by 1, 2
      ) t), '[]'::json),
    'ratings', coalesce((
      select json_agg(t) from (select artwork_id as a, rating as v, votes as n from artwork_ratings) t
    ), '[]'::json),
    'scores', coalesce((
      select json_agg(x) from (
        select artwork_id as a, popularity as p, trending as t, collector as c, critic as cr from artwork_scores()
      ) x), '[]'::json),
    'artist_scores', coalesce((
      select json_agg(t) from (select artist_id as a, reputation as s from artist_scores()) t
    ), '[]'::json),
    'members', (select count(*)::int from profiles),
    'artists', coalesce((
      select json_agg(t) from (
        select id, name, country, created_at, bio, statement, website, instagram, city, avatar_path
        from artists where owner_id is not null
      ) t), '[]'::json),
    'uploads', coalesce((
      select json_agg(t) from (
        select id, artist_id, title, category, style, medium, year, price,
               image_path, thumb_path, width, height, created_at, description, dimensions, availability
        from artworks where owner_id is not null and not hidden and (release_at is null or release_at <= now())
        order by created_at desc limit 2000
      ) t), '[]'::json)
  )
$$;
grant execute on function public.community_snapshot() to anon, authenticated;

-- ——— Grants ———
do $$
declare f text;
begin
  foreach f in array array[
    'send_inquiry(text, text, text, text)', 'reply_inquiry(uuid, text)', 'set_inquiry_status(uuid, text)', 'mark_inquiry_read(uuid)',
    'my_inquiries()', 'inquiry_thread(uuid)', 'set_block(uuid, boolean)', 'report_inquiry(uuid, text)',
    'admin_inquiry_reports()', 'resolve_inquiry_report(uuid, boolean, text)', 'collector_interest()',
    'create_drop(text, text, timestamptz, text[], text)', 'cancel_drop(uuid, text)', 'subscribe_drop(uuid, boolean)', 'my_scheduled_works()'
  ] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['drops_overview()', 'drop_detail(uuid)'] loop
    execute format('revoke all on function public.%s from public', f);
    execute format('grant execute on function public.%s to anon, authenticated', f);
  end loop;
end $$;

-- Release drops on time where pg_cron is available (every 5 minutes).
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('abremi-drops', '*/5 * * * *', 'select public.release_due_drops();');
  end if;
exception when others then
  raise notice 'Schedule not set up (%). Drops are announced as released when someone opens them instead.', sqlerrm;
end $$;

-- ═════ 0011_coach_passport_opportunities.sql ═════
-- Abremi Phase 5: AI Career Coach (quota and grounded context), Artist Passport (verified
-- exhibitions, competition history, milestones) and Gallery Opportunities.
-- Adds only; undo with supabase/migrations/down/0011_down.sql.

-- ——— 1. Artist Passport ———
create table if not exists public.exhibitions (
  id uuid primary key default gen_random_uuid(),
  artist_id text not null references public.artists (id) on delete cascade,
  owner_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('solo', 'group', 'fair', 'online', 'residency')),
  title text not null check (char_length(btrim(title)) between 3 and 120),
  venue text not null check (char_length(btrim(venue)) between 2 and 120),
  city text check (char_length(coalesce(city, '')) <= 60),
  country text check (country is null or country ~ '^[A-Z]{2}$'),
  start_date date not null,
  end_date date,
  link text not null check (link ~ '^https://[^[:space:]<>"]+$' and char_length(link) <= 300),
  status text not null default 'pending' check (status in ('pending', 'verified', 'rejected')),
  review_note text check (char_length(coalesce(review_note, '')) <= 500),
  created_at timestamptz not null default now(),
  reviewed_by uuid references auth.users (id) on delete set null,
  reviewed_at timestamptz,
  check (end_date is null or end_date >= start_date)
);
create index if not exists exhibitions_artist_idx on public.exhibitions (artist_id, start_date desc);
alter table public.exhibitions enable row level security;
drop policy if exists "verified exhibitions are public; artists see their own" on public.exhibitions;
create policy "verified exhibitions are public; artists see their own" on public.exhibitions for select
  using (status = 'verified' or owner_id = auth.uid());
revoke all on public.exhibitions from anon, authenticated;
grant select on public.exhibitions to anon, authenticated;

create or replace function public.submit_exhibition(p_kind text, p_title text, p_venue text, p_city text, p_country text,
                                                    p_start date, p_end date, p_link text) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  ar public.artists;
  new_id uuid;
begin
  select * into ar from artists where owner_id = auth.uid();
  if auth.uid() is null or ar.id is null then
    raise exception 'Publish a work first' using errcode = '42501';
  end if;
  if (select count(*) from exhibitions where owner_id = auth.uid() and status = 'pending') >= 10 then
    raise exception 'You have 10 exhibitions waiting for review' using errcode = 'P0001';
  end if;
  if p_start > now() + interval '2 years' then
    raise exception 'Add exhibitions that have been confirmed, within the next 2 years' using errcode = '22023';
  end if;
  insert into exhibitions (artist_id, owner_id, kind, title, venue, city, country, start_date, end_date, link)
  values (ar.id, auth.uid(), p_kind, btrim(p_title), btrim(p_venue), nullif(btrim(coalesce(p_city, '')), ''), nullif(upper(coalesce(p_country, '')), ''),
          p_start, p_end, btrim(p_link))
  returning exhibitions.id into new_id;
  return new_id;
end $$;

create or replace function public.delete_exhibition(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from exhibitions where id = p_id and owner_id = auth.uid();
  if not found then
    raise exception 'Not your exhibition' using errcode = '42501';
  end if;
end $$;

create or replace function public.admin_exhibition_queue() returns json
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return coalesce((select json_agg(json_build_object('id', e.id, 'artist', ar.name, 'artist_id', ar.id, 'kind', e.kind, 'title', e.title,
                                    'venue', e.venue, 'city', e.city, 'country', e.country, 'start_date', e.start_date, 'end_date', e.end_date,
                                    'link', e.link, 'created_at', e.created_at) order by e.created_at)
                   from exhibitions e join artists ar on ar.id = e.artist_id where e.status = 'pending'), '[]'::json);
end $$;

create or replace function public.review_exhibition(p_id uuid, p_verify boolean, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare e public.exhibitions;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update exhibitions set status = case when p_verify then 'verified' else 'rejected' end, review_note = nullif(btrim(coalesce(p_note, '')), ''),
         reviewed_by = auth.uid(), reviewed_at = now()
   where id = p_id and status = 'pending' returning * into e;
  if e.id is null then
    raise exception 'That exhibition is no longer pending' using errcode = 'P0001';
  end if;
  perform log_audit(case when p_verify then 'exhibition.verified' else 'exhibition.rejected' end, 'exhibition', e.id::text,
                    jsonb_build_object('title', e.title, 'venue', e.venue, 'note', e.review_note));
  insert into notifications (user_id, kind, title, link)
  values (e.owner_id, 'exhibition_review', case when p_verify then '“' || e.title || '” is verified on your Passport'
                                                else '“' || e.title || '” couldn’t be verified' || coalesce(': ' || e.review_note, '') end, 'artist/' || e.artist_id);
end $$;

-- An artist's public Passport: every entry comes from a server record and says where it came from.
create or replace function public.artist_passport(p_artist text) returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'achievements', coalesce((select json_agg(json_build_object('label', d.label, 'criteria', d.criteria, 'at', m.awarded_at) order by m.awarded_at)
                              from member_achievements m join achievement_definitions d on d.code = m.code and d.audience = 'artist'
                              where m.user_id = ar.owner_id), '[]'::json),
    'competitions', coalesce((select json_agg(json_build_object('id', c.id, 'title', c.title, 'kind', c.kind, 'closed_at', c.closed_at,
                                               'place', (r->>'place')::int, 'votes', (r->>'votes')::int, 'artwork', r->>'artwork') order by c.closed_at desc)
                              from competitions c, jsonb_array_elements(c.results->'entries') r
                              join competition_entries e on e.id = (r->>'entry')::uuid
                              where e.user_id = ar.owner_id and c.closed_at is not null), '[]'::json),
    'exhibitions', coalesce((select json_agg(json_build_object('kind', e.kind, 'title', e.title, 'venue', e.venue, 'city', e.city, 'country', e.country,
                                              'start_date', e.start_date, 'end_date', e.end_date, 'link', e.link) order by e.start_date desc)
                             from exhibitions e where e.artist_id = ar.id and e.status = 'verified'), '[]'::json),
    'milestones', json_build_object(
      'joined', ar.created_at,
      'first_work', (select min(created_at) from artworks where artist_id = ar.id and (release_at is null or release_at <= now())),
      'first_drop', (select min(released_at) from drops where artist_id = ar.id),
      'first_inquiry', (select min(created_at) from inquiries where artist_id = ar.id))
  )
  from artists ar where ar.id = p_artist and ar.owner_id is not null
$$;

-- ——— 2. Gallery Opportunities ———
create table if not exists public.opportunities (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('open_call', 'exhibition', 'residency', 'prize')),
  title text not null check (char_length(btrim(title)) between 3 and 120),
  organizer text not null check (char_length(btrim(organizer)) between 2 and 120),
  location text not null check (char_length(btrim(location)) between 2 and 120),
  deadline date not null,
  eligibility text not null default '' check (char_length(eligibility) <= 1000),
  description text not null default '' check (char_length(description) <= 2000),
  fee numeric(10, 2) not null default 0 check (fee >= 0 and fee <= 10000),
  fee_currency text not null default 'USD' check (fee_currency ~ '^[A-Z]{3}$'),
  link text not null check (link ~ '^https://[^[:space:]<>"]+$' and char_length(link) <= 300),
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  submitted_by uuid references public.profiles (id) on delete set null,
  review_note text check (char_length(coalesce(review_note, '')) <= 500),
  created_at timestamptz not null default now(),
  reviewed_by uuid references auth.users (id) on delete set null,
  reviewed_at timestamptz
);
create index if not exists opportunities_deadline_idx on public.opportunities (deadline) where status = 'approved';
alter table public.opportunities enable row level security;
drop policy if exists "approved opportunities are public" on public.opportunities;
create policy "approved opportunities are public" on public.opportunities for select
  using (status = 'approved' or submitted_by = auth.uid());
revoke all on public.opportunities from anon, authenticated;
grant select on public.opportunities to anon, authenticated;

create table if not exists public.saved_opportunities (
  user_id uuid not null references public.profiles (id) on delete cascade,
  opportunity_id uuid not null references public.opportunities (id) on delete cascade,
  reminded_at timestamptz,
  created_at timestamptz not null default now(),
  primary key (user_id, opportunity_id)
);
alter table public.saved_opportunities enable row level security;
drop policy if exists "read own saved opportunities" on public.saved_opportunities;
create policy "read own saved opportunities" on public.saved_opportunities for select using (user_id = auth.uid());
revoke all on public.saved_opportunities from anon, authenticated;
grant select on public.saved_opportunities to authenticated;

-- Members (accounts 3+ days old, 5 a day) suggest; moderators post directly or approve. Both audited.
create or replace function public.suggest_opportunity(p_kind text, p_title text, p_organizer text, p_location text, p_deadline date,
                                                      p_eligibility text, p_description text, p_fee numeric, p_fee_currency text, p_link text)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  admin boolean := is_admin();
  new_id uuid;
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if not admin and (select created_at from profiles where id = uid) > now() - interval '3 days' then
    raise exception 'New accounts can suggest opportunities after 3 days' using errcode = '42501';
  end if;
  if not admin and (select count(*) from opportunities where submitted_by = uid and created_at > now() - interval '1 day') >= 5 then
    raise exception 'You can suggest 5 opportunities a day' using errcode = 'P0001';
  end if;
  if p_deadline < current_date then
    raise exception 'The deadline has passed' using errcode = '22023';
  end if;
  insert into opportunities (kind, title, organizer, location, deadline, eligibility, description, fee, fee_currency, link, status, submitted_by,
                             reviewed_by, reviewed_at)
  values (p_kind, btrim(p_title), btrim(p_organizer), btrim(p_location), p_deadline, btrim(coalesce(p_eligibility, '')), btrim(coalesce(p_description, '')),
          coalesce(p_fee, 0), upper(coalesce(nullif(p_fee_currency, ''), 'USD')), btrim(p_link),
          case when admin then 'approved' else 'pending' end, uid, case when admin then uid end, case when admin then now() end)
  returning opportunities.id into new_id;
  if admin then
    perform log_audit('opportunity.published', 'opportunity', new_id::text, jsonb_build_object('title', p_title));
  end if;
  return new_id;
end $$;

create or replace function public.admin_opportunity_queue() returns json
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return coalesce((select json_agg(row_to_json(o) order by o.created_at) from opportunities o where o.status = 'pending'), '[]'::json);
end $$;

create or replace function public.review_opportunity(p_id uuid, p_approve boolean, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare o public.opportunities;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update opportunities set status = case when p_approve then 'approved' else 'rejected' end, review_note = nullif(btrim(coalesce(p_note, '')), ''),
         reviewed_by = auth.uid(), reviewed_at = now()
   where id = p_id and status = 'pending' returning * into o;
  if o.id is null then
    raise exception 'That listing is no longer pending' using errcode = 'P0001';
  end if;
  perform log_audit(case when p_approve then 'opportunity.approved' else 'opportunity.rejected' end, 'opportunity', o.id::text,
                    jsonb_build_object('title', o.title, 'note', o.review_note));
end $$;

create or replace function public.save_opportunity(p_id uuid, p_on boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if p_on then
    insert into saved_opportunities (user_id, opportunity_id)
    select auth.uid(), id from opportunities where id = p_id and status = 'approved'
    on conflict do nothing;
  else
    delete from saved_opportunities where user_id = auth.uid() and opportunity_id = p_id;
  end if;
end $$;

-- Listings open now (deadline today or later), with whether you saved each.
create or replace function public.opportunities_list() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_agg(json_build_object(
    'id', o.id, 'kind', o.kind, 'title', o.title, 'organizer', o.organizer, 'location', o.location, 'deadline', o.deadline,
    'eligibility', o.eligibility, 'description', o.description, 'fee', o.fee, 'fee_currency', o.fee_currency, 'link', o.link,
    'saved', exists (select 1 from saved_opportunities s where s.opportunity_id = o.id and s.user_id = auth.uid())
  ) order by o.deadline, o.title), '[]'::json)
  from opportunities o where o.status = 'approved' and o.deadline >= current_date
$$;

-- A reminder 3 days before the deadline of each saved opportunity, once.
create or replace function public.send_deadline_reminders() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  with due as (
    update saved_opportunities s set reminded_at = now()
      from opportunities o
     where o.id = s.opportunity_id and o.status = 'approved' and s.reminded_at is null
       and o.deadline between current_date and current_date + 3
    returning s.user_id, o.id, o.title, o.deadline
  )
  insert into notifications (user_id, kind, title, link)
  select user_id, 'opportunity_deadline', '“' || title || '” closes ' || to_char(deadline, 'Mon FMDD'), 'opportunities'
  from due;
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function public.send_deadline_reminders() from public, anon, authenticated;

-- ——— 3. Career Coach ———
-- The AI itself runs in a server function (api/coach.js) that holds the API key. It calls
-- begin_coach_request() with the artist's own session, so the database decides who may use the
-- Coach, enforces the limits, and hands over only that artist's own data as context.
create table if not exists public.coach_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  tool text not null check (tool in ('bio', 'statement', 'description', 'engagement', 'social', 'application')),
  status text not null default 'pending' check (status in ('pending', 'done', 'failed')),
  created_at timestamptz not null default now()
);
create index if not exists coach_requests_user_idx on public.coach_requests (user_id, created_at desc);
create index if not exists coach_requests_day_idx on public.coach_requests (created_at);
alter table public.coach_requests enable row level security;
drop policy if exists "read own coach requests" on public.coach_requests;
create policy "read own coach requests" on public.coach_requests for select using (user_id = auth.uid());
revoke all on public.coach_requests from anon, authenticated;
grant select on public.coach_requests to authenticated;

create or replace function public.coach_usage() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'used', (select count(*) from coach_requests where user_id = auth.uid() and status <> 'failed' and created_at >= date_trunc('month', now())),
    'limit', 20,
    'resets_at', date_trunc('month', now()) + interval '1 month')
$$;

-- Starts a Coach request: checks the limits (20 a month per artist, 400 a day overall) and returns the
-- grounding context. Failed requests (finish_coach_request(id, false)) don't count.
create or replace function public.begin_coach_request(p_tool text, p_artwork text default null, p_opportunity uuid default null) returns json
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  ar public.artists;
  w public.artworks;
  o public.opportunities;
  req uuid;
  since timestamptz := now() - interval '30 days';
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  select * into ar from artists where owner_id = uid;
  if ar.id is null then
    raise exception 'The Coach is for artists: publish a work first' using errcode = '42501';
  end if;
  if p_tool not in ('bio', 'statement', 'description', 'engagement', 'social', 'application') then
    raise exception 'Unknown Coach tool' using errcode = '22023';
  end if;
  if (select count(*) from coach_requests where user_id = uid and status <> 'failed' and created_at >= date_trunc('month', now())) >= 20 then
    raise exception 'You’ve used this month’s 20 Coach requests. They reset on the 1st.' using errcode = 'P0001';
  end if;
  if (select count(*) from coach_requests where status <> 'failed' and created_at > now() - interval '1 day') >= 400 then
    raise exception 'The Coach is busy today. Please try again tomorrow.' using errcode = 'P0001';
  end if;
  if p_tool in ('description', 'social') then
    select * into w from artworks where id = p_artwork and owner_id = uid;
    if w.id is null then
      raise exception 'Choose one of your own works' using errcode = '22023';
    end if;
  end if;
  if p_tool = 'application' then
    select * into o from opportunities where id = p_opportunity and status = 'approved';
    if o.id is null then
      raise exception 'Choose a listed opportunity' using errcode = '22023';
    end if;
  end if;
  insert into coach_requests (user_id, tool) values (uid, p_tool) returning id into req;
  return json_build_object(
    'request_id', req,
    'artist', json_build_object('name', ar.name, 'country', ar.country, 'city', ar.city, 'bio', ar.bio, 'statement', ar.statement,
                                'website', ar.website, 'joined', ar.created_at::date),
    'works', coalesce((select json_agg(json_build_object('id', x.id, 'title', x.title, 'medium', coalesce(x.medium, x.category), 'style', x.style,
                                       'year', x.year, 'dimensions', x.dimensions, 'availability', x.availability, 'description', x.description) order by x.created_at desc)
                       from (select * from artworks where owner_id = uid and not hidden order by created_at desc limit 30) x), '[]'::json),
    'artwork', case when w.id is not null then json_build_object('id', w.id, 'title', w.title, 'medium', coalesce(w.medium, w.category), 'style', w.style,
                    'year', w.year, 'dimensions', w.dimensions, 'description', w.description, 'thumb_path', w.thumb_path) end,
    'stats', case when p_tool = 'engagement' then json_build_object(
                    'last_30_days', artist_summary(ar.id, since, now()),
                    'previous_30_days', artist_summary(ar.id, since - interval '30 days', since),
                    'followers_total', (select count(*) from counted_follows where artist_id = ar.id)) end,
    'opportunity', case when o.id is not null then json_build_object('title', o.title, 'kind', o.kind, 'organizer', o.organizer, 'location', o.location,
                        'deadline', o.deadline, 'eligibility', o.eligibility, 'description', o.description) end,
    'achievements', coalesce((select json_agg(d.label) from member_achievements m join achievement_definitions d on d.code = m.code
                              where m.user_id = uid and d.audience = 'artist'), '[]'::json),
    'exhibitions', coalesce((select json_agg(json_build_object('title', e.title, 'venue', e.venue, 'year', extract(year from e.start_date)::int) order by e.start_date desc)
                             from exhibitions e where e.owner_id = uid and e.status = 'verified'), '[]'::json)
  );
end $$;

create or replace function public.finish_coach_request(p_id uuid, p_ok boolean) returns void
language sql security definer set search_path = public as $$
  update coach_requests set status = case when p_ok then 'done' else 'failed' end
   where id = p_id and user_id = auth.uid() and status = 'pending'
$$;

-- ——— Grants ———
do $$
declare f text;
begin
  foreach f in array array[
    'coach_usage()', 'begin_coach_request(text, text, uuid)', 'finish_coach_request(uuid, boolean)',
    'submit_exhibition(text, text, text, text, text, date, date, text)', 'delete_exhibition(uuid)', 'admin_exhibition_queue()',
    'review_exhibition(uuid, boolean, text)', 'suggest_opportunity(text, text, text, text, date, text, text, numeric, text, text)',
    'admin_opportunity_queue()', 'review_opportunity(uuid, boolean, text)', 'save_opportunity(uuid, boolean)'
  ] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['artist_passport(text)', 'opportunities_list()'] loop
    execute format('revoke all on function public.%s from public', f);
    execute format('grant execute on function public.%s to anon, authenticated', f);
  end loop;
end $$;

-- Deadline reminders daily at 07:23 UTC where pg_cron is available.
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('abremi-deadline-reminders', '23 7 * * *', 'select public.send_deadline_reminders();');
  end if;
exception when others then
  raise notice 'Schedule not set up (%). Deadline reminders need pg_cron.', sqlerrm;
end $$;

-- ═════ 0012_plans_galleries_beta.sql ═════
-- Abremi Phase 6: subscription readiness, gallery accounts, beta tools.
--
--   1. Plans and entitlements. Artist Free, Pro, Elite and Gallery are defined here; the database
--      decides what each account gets (never the app). Payments stay OFF (app_settings) until the
--      product requirements, provider, taxes and refund policy are reviewed. Until then moderators
--      can grant a plan for a fixed period (audited), e.g. to beta testers.
--      Plans NEVER touch rankings: artwork_scores(), artist_scores(), the snapshot and the
--      leaderboards don't read them (tests/db.test.js checks this).
--   2. Plan-dependent limits: Coach requests, analytics range, upcoming drops, priority review.
--   3. Gallery accounts: members apply, moderators verify; verified galleries get a public page and,
--      on the Gallery plan, post Opportunities without review.
--   4. Beta: invite codes (optionally required for new sign-ups), in-app feedback, app error log.
--   5. Billing hooks for a future payment provider (service role only; inactive while payments are off).

-- ——— 0. Settings ———
create table if not exists public.app_settings (
  id boolean primary key default true check (id),
  invite_required boolean not null default false,
  payments_enabled boolean not null default false, -- switched on only in the SQL editor, after review
  updated_at timestamptz not null default now()
);
insert into public.app_settings (id) values (true) on conflict (id) do nothing;
alter table public.app_settings enable row level security;
revoke all on public.app_settings from anon, authenticated;

create or replace function public.app_flags() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object('invite_required', invite_required, 'payments_enabled', payments_enabled) from app_settings
$$;

-- ——— 1. Plans and entitlements ———
create table if not exists public.plans (
  code text primary key check (code in ('free', 'pro', 'elite', 'gallery')),
  name text not null,
  audience text not null check (audience in ('artist', 'gallery')),
  coach_monthly integer not null check (coach_monthly between 0 and 1000),
  analytics_days integer not null check (analytics_days in (90, 365)),
  max_upcoming_drops integer not null check (max_upcoming_drops between 0 and 20),
  priority_review boolean not null default false,
  direct_opportunities boolean not null default false,
  badge text check (badge in ('Pro', 'Elite')),
  sort integer not null
);
-- Same values as src/core/plans.js (tests/db.test.js checks they agree). No prices: those are set
-- when payments are switched on.
insert into public.plans (code, name, audience, coach_monthly, analytics_days, max_upcoming_drops, priority_review, direct_opportunities, badge, sort) values
  ('free', 'Artist Free', 'artist', 20, 90, 1, false, false, null, 1),
  ('pro', 'Artist Pro', 'artist', 60, 365, 3, false, false, 'Pro', 2),
  ('elite', 'Artist Elite', 'artist', 150, 365, 3, true, false, 'Elite', 3),
  ('gallery', 'Gallery', 'gallery', 100, 90, 1, false, true, null, 4)
on conflict (code) do update set name = excluded.name, audience = excluded.audience, coach_monthly = excluded.coach_monthly,
  analytics_days = excluded.analytics_days, max_upcoming_drops = excluded.max_upcoming_drops, priority_review = excluded.priority_review,
  direct_opportunities = excluded.direct_opportunities, badge = excluded.badge, sort = excluded.sort;
alter table public.plans enable row level security;
drop policy if exists "plans are public" on public.plans;
create policy "plans are public" on public.plans for select using (true);
revoke all on public.plans from anon, authenticated;
grant select on public.plans to anon, authenticated;

-- One row per member: their current paid or granted plan. No row = Artist Free.
create table if not exists public.subscriptions (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  plan text not null references public.plans (code),
  status text not null check (status in ('active', 'trialing', 'past_due', 'canceled')),
  source text not null check (source in ('grant', 'billing')),
  current_period_end timestamptz,
  granted_by uuid references auth.users (id) on delete set null,
  note text check (char_length(coalesce(note, '')) <= 300),
  billing_customer text check (char_length(coalesce(billing_customer, '')) <= 100),
  billing_subscription text check (char_length(coalesce(billing_subscription, '')) <= 100),
  updated_at timestamptz not null default now(),
  check (source = 'billing' or current_period_end is not null) -- grants always end
);
alter table public.subscriptions enable row level security;
drop policy if exists "read own subscription" on public.subscriptions;
create policy "read own subscription" on public.subscriptions for select using (user_id = auth.uid());
revoke all on public.subscriptions from anon, authenticated;
grant select on public.subscriptions to authenticated;

-- The plan in force for a member right now (server-side only; never trusts the app).
create or replace function public.current_plan(p_user uuid) returns public.plans
language sql stable security definer set search_path = public as $$
  select p.* from plans p
  where p.code = coalesce((select s.plan from subscriptions s
                            where s.user_id = p_user and s.status in ('active', 'trialing', 'past_due')
                              and (s.current_period_end is null or s.current_period_end > now())), 'free')
$$;
revoke all on function public.current_plan(uuid) from public, anon, authenticated;

create or replace function public.my_plan() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'plan', row_to_json(p),
    'status', s.status, 'source', s.source, 'ends_at', s.current_period_end,
    'manage', s.source = 'billing' and s.billing_customer is not null)
  from current_plan(auth.uid()) p
  left join subscriptions s on s.user_id = auth.uid() and s.plan = p.code
  where auth.uid() is not null
$$;

-- Public badges (Pro, Elite) by artist id: display only, never used in any ranking.
create or replace function public.plan_badges() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_object_agg(ar.id, (current_plan(ar.owner_id)).badge), '{}'::json)
  from artists ar
  join subscriptions s on s.user_id = ar.owner_id
  where (current_plan(ar.owner_id)).badge is not null
$$;

-- Moderators find members by display name to grant a plan (no emails).
create or replace function public.admin_find_members(p_query text) returns json
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return coalesce((select json_agg(x) from (
    select p.id, p.name, p.country, p.role, ar.id as artist_id, (current_plan(p.id)).code as plan,
           exists (select 1 from galleries g where g.owner_id = p.id and g.status = 'verified') as verified_gallery
    from profiles p left join artists ar on ar.owner_id = p.id
    where char_length(btrim(coalesce(p_query, ''))) >= 2
      and (p.name ilike '%' || btrim(p_query) || '%' or ar.name ilike '%' || btrim(p_query) || '%')
    order by p.name limit 20) x), '[]'::json);
end $$;

-- ——— 3. Gallery accounts (defined before the plan grants, which check them) ———
create table if not exists public.galleries (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null unique references public.profiles (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 2 and 120),
  city text not null check (char_length(btrim(city)) between 2 and 80),
  country text not null check (country ~ '^[A-Z]{2}$'),
  website text not null check (website ~ '^https://[^[:space:]<>"]+$' and char_length(website) <= 300),
  bio text not null default '' check (char_length(bio) <= 1000),
  status text not null default 'pending' check (status in ('pending', 'verified', 'rejected')),
  review_note text check (char_length(coalesce(review_note, '')) <= 500),
  created_at timestamptz not null default now(),
  reviewed_by uuid references auth.users (id) on delete set null,
  reviewed_at timestamptz
);
alter table public.galleries enable row level security;
drop policy if exists "verified galleries are public" on public.galleries;
create policy "verified galleries are public" on public.galleries for select using (status = 'verified' or owner_id = auth.uid());
revoke all on public.galleries from anon, authenticated;
grant select on public.galleries to anon, authenticated;

alter table public.opportunities add column if not exists gallery_id uuid references public.galleries (id) on delete set null;

-- Apply (accounts 3+ days old), or re-apply after a decline. Editing a verified gallery keeps it
-- verified unless the name changes, which sends it back for review.
create or replace function public.apply_gallery(p_name text, p_city text, p_country text, p_website text, p_bio text) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  g public.galleries;
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if (select created_at from profiles where id = uid) > now() - interval '3 days' then
    raise exception 'New accounts can apply for a gallery account after 3 days' using errcode = '42501';
  end if;
  select * into g from galleries where owner_id = uid;
  if g.id is null then
    insert into galleries (owner_id, name, city, country, website, bio)
    values (uid, btrim(p_name), btrim(p_city), upper(btrim(p_country)), btrim(p_website), btrim(coalesce(p_bio, '')))
    returning * into g;
  else
    update galleries set name = btrim(p_name), city = btrim(p_city), country = upper(btrim(p_country)), website = btrim(p_website),
           bio = btrim(coalesce(p_bio, '')),
           status = case when g.status = 'verified' and btrim(p_name) = g.name then 'verified' else 'pending' end,
           review_note = case when g.status = 'verified' and btrim(p_name) = g.name then g.review_note end
     where id = g.id returning * into g;
  end if;
  return g.id;
end $$;

create or replace function public.admin_gallery_queue() returns json
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return coalesce((select json_agg(json_build_object('id', g.id, 'name', g.name, 'city', g.city, 'country', g.country, 'website', g.website,
                                    'bio', g.bio, 'created_at', g.created_at, 'member', p.name, 'member_since', p.created_at) order by g.created_at)
                   from galleries g join profiles p on p.id = g.owner_id where g.status = 'pending'), '[]'::json);
end $$;

create or replace function public.review_gallery(p_id uuid, p_verify boolean, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare g public.galleries;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update galleries set status = case when p_verify then 'verified' else 'rejected' end, review_note = nullif(btrim(coalesce(p_note, '')), ''),
         reviewed_by = auth.uid(), reviewed_at = now()
   where id = p_id and status = 'pending' returning * into g;
  if g.id is null then
    raise exception 'That gallery is no longer pending' using errcode = 'P0001';
  end if;
  perform log_audit(case when p_verify then 'gallery.verified' else 'gallery.rejected' end, 'gallery', g.id::text,
                    jsonb_build_object('name', g.name, 'note', g.review_note));
  insert into notifications (user_id, kind, title, link)
  values (g.owner_id, 'gallery_review', case when p_verify then g.name || ' is now a verified gallery on Abremi'
                                             else g.name || ' couldn’t be verified' || coalesce(': ' || g.review_note, '') end,
          case when p_verify then 'gallery/' || g.id else 'profile' end);
end $$;

create or replace function public.gallery_page(p_id uuid) returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'id', g.id, 'name', g.name, 'city', g.city, 'country', g.country, 'website', g.website, 'bio', g.bio, 'verified_at', g.reviewed_at,
    'opportunities', coalesce((select json_agg(json_build_object('id', o.id, 'kind', o.kind, 'title', o.title, 'location', o.location,
                                               'deadline', o.deadline, 'fee', o.fee, 'fee_currency', o.fee_currency, 'link', o.link) order by o.deadline)
                               from opportunities o where o.gallery_id = g.id and o.status = 'approved' and o.deadline >= current_date), '[]'::json))
  from galleries g where g.id = p_id and g.status = 'verified'
$$;

create or replace function public.my_gallery() returns json
language sql stable security definer set search_path = public as $$
  select row_to_json(g) from galleries g where g.owner_id = auth.uid()
$$;

-- Plan grants: moderators only, always with an end date, audited, and never over a paid plan.
create or replace function public.admin_grant_plan(p_user uuid, p_plan text, p_until date, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare cur public.subscriptions;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  if p_plan not in ('pro', 'elite', 'gallery') then
    raise exception 'Choose Pro, Elite or Gallery' using errcode = '22023';
  end if;
  if p_until is null or p_until <= current_date or p_until > current_date + 366 then
    raise exception 'A grant ends between tomorrow and a year from now' using errcode = '22023';
  end if;
  if not exists (select 1 from profiles where id = p_user) then
    raise exception 'Member not found' using errcode = 'P0002';
  end if;
  if p_plan = 'gallery' and not exists (select 1 from galleries where owner_id = p_user and status = 'verified') then
    raise exception 'The Gallery plan is for verified galleries' using errcode = '22023';
  end if;
  select * into cur from subscriptions where user_id = p_user;
  if cur.source = 'billing' and cur.status in ('active', 'trialing', 'past_due') then
    raise exception 'This member has a paid subscription' using errcode = 'P0001';
  end if;
  insert into subscriptions (user_id, plan, status, source, current_period_end, granted_by, note, updated_at)
  values (p_user, p_plan, 'active', 'grant', p_until::timestamptz + interval '1 day', auth.uid(), nullif(btrim(coalesce(p_note, '')), ''), now())
  on conflict (user_id) do update set plan = excluded.plan, status = 'active', source = 'grant', current_period_end = excluded.current_period_end,
    granted_by = excluded.granted_by, note = excluded.note, billing_customer = null, billing_subscription = null, updated_at = now();
  perform log_audit('plan.granted', 'member', p_user::text, jsonb_build_object('plan', p_plan, 'until', p_until, 'note', p_note));
  insert into notifications (user_id, kind, title, link)
  values (p_user, 'plan_granted', 'You have ' || (select name from plans where code = p_plan) || ' until ' || to_char(p_until, 'Mon FMDD, YYYY'), 'plans');
end $$;

create or replace function public.admin_revoke_plan(p_user uuid, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  delete from subscriptions where user_id = p_user and source = 'grant';
  if not found then
    raise exception 'No granted plan to remove' using errcode = 'P0001';
  end if;
  perform log_audit('plan.revoked', 'member', p_user::text, jsonb_build_object('note', p_note));
end $$;

create or replace function public.admin_plan_holders() returns json
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return coalesce((select json_agg(json_build_object('user_id', s.user_id, 'name', p.name, 'plan', s.plan, 'status', s.status, 'source', s.source,
                                    'ends_at', s.current_period_end, 'note', s.note) order by s.current_period_end nulls last)
                   from subscriptions s join profiles p on p.id = s.user_id
                   where s.current_period_end is null or s.current_period_end > now()), '[]'::json);
end $$;

-- ——— 2. Plan-dependent limits (replacing the 0009–0011 versions) ———
create or replace function public.coach_usage() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'used', (select count(*) from coach_requests where user_id = auth.uid() and status <> 'failed' and created_at >= date_trunc('month', now())),
    'limit', (current_plan(auth.uid())).coach_monthly,
    'plan', (current_plan(auth.uid())).name,
    'resets_at', date_trunc('month', now()) + interval '1 month')
$$;

-- Starts a Coach request: checks the limits (the plan's monthly requests, 400 a day overall) and
-- returns the grounding context. Failed requests (finish_coach_request(id, false)) don't count.
create or replace function public.begin_coach_request(p_tool text, p_artwork text default null, p_opportunity uuid default null) returns json
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  ar public.artists;
  w public.artworks;
  o public.opportunities;
  req uuid;
  since timestamptz := now() - interval '30 days';
  monthly integer;
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  select * into ar from artists where owner_id = uid;
  if ar.id is null then
    raise exception 'The Coach is for artists: publish a work first' using errcode = '42501';
  end if;
  if p_tool not in ('bio', 'statement', 'description', 'engagement', 'social', 'application') then
    raise exception 'Unknown Coach tool' using errcode = '22023';
  end if;
  monthly := (current_plan(uid)).coach_monthly;
  if (select count(*) from coach_requests where user_id = uid and status <> 'failed' and created_at >= date_trunc('month', now())) >= monthly then
    raise exception 'You’ve used this month’s % Coach requests. They reset on the 1st.', monthly using errcode = 'P0001';
  end if;
  if (select count(*) from coach_requests where status <> 'failed' and created_at > now() - interval '1 day') >= 400 then
    raise exception 'The Coach is busy today. Please try again tomorrow.' using errcode = 'P0001';
  end if;
  if p_tool in ('description', 'social') then
    select * into w from artworks where id = p_artwork and owner_id = uid;
    if w.id is null then
      raise exception 'Choose one of your own works' using errcode = '22023';
    end if;
  end if;
  if p_tool = 'application' then
    select * into o from opportunities where id = p_opportunity and status = 'approved';
    if o.id is null then
      raise exception 'Choose a listed opportunity' using errcode = '22023';
    end if;
  end if;
  insert into coach_requests (user_id, tool) values (uid, p_tool) returning id into req;
  return json_build_object(
    'request_id', req,
    'artist', json_build_object('name', ar.name, 'country', ar.country, 'city', ar.city, 'bio', ar.bio, 'statement', ar.statement,
                                'website', ar.website, 'joined', ar.created_at::date),
    'works', coalesce((select json_agg(json_build_object('id', x.id, 'title', x.title, 'medium', coalesce(x.medium, x.category), 'style', x.style,
                                       'year', x.year, 'dimensions', x.dimensions, 'availability', x.availability, 'description', x.description) order by x.created_at desc)
                       from (select * from artworks where owner_id = uid and not hidden order by created_at desc limit 30) x), '[]'::json),
    'artwork', case when w.id is not null then json_build_object('id', w.id, 'title', w.title, 'medium', coalesce(w.medium, w.category), 'style', w.style,
                    'year', w.year, 'dimensions', w.dimensions, 'description', w.description, 'thumb_path', w.thumb_path) end,
    'stats', case when p_tool = 'engagement' then json_build_object(
                    'last_30_days', artist_summary(ar.id, since, now()),
                    'previous_30_days', artist_summary(ar.id, since - interval '30 days', since),
                    'followers_total', (select count(*) from counted_follows where artist_id = ar.id)) end,
    'opportunity', case when o.id is not null then json_build_object('title', o.title, 'kind', o.kind, 'organizer', o.organizer, 'location', o.location,
                        'deadline', o.deadline, 'eligibility', o.eligibility, 'description', o.description) end,
    'achievements', coalesce((select json_agg(d.label) from member_achievements m join achievement_definitions d on d.code = m.code
                              where m.user_id = uid and d.audience = 'artist'), '[]'::json),
    'exhibitions', coalesce((select json_agg(json_build_object('title', e.title, 'venue', e.venue, 'year', extract(year from e.start_date)::int) order by e.start_date desc)
                             from exhibitions e where e.owner_id = uid and e.status = 'verified'), '[]'::json)
  );
end $$;

-- The caller's Studio for the last p_days: 7, 30 or 90 on every plan; 365 on plans that include it.
create or replace function public.studio_analytics(p_days integer default 30) returns json
language plpgsql stable security definer set search_path = public as $$
declare
  me_artist text;
  max_days integer := (current_plan(auth.uid())).analytics_days;
  days integer := case when p_days in (7, 30, 90, 365) then p_days else 30 end;
  t_to timestamptz;
  t_from timestamptz;
  t_prev timestamptz;
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if days > max_days then
    raise exception 'A year of analytics comes with Artist Pro and Elite' using errcode = '42501';
  end if;
  t_to := date_trunc('day', now()) + interval '1 day';
  t_from := t_to - make_interval(days => days);
  t_prev := t_to - make_interval(days => 2 * days);
  select id into me_artist from artists where owner_id = auth.uid();
  if me_artist is null then
    return null;
  end if;
  return json_build_object(
    'artist', me_artist, 'days', days, 'max_days', max_days, 'from', t_from, 'to', t_to,
    'current', artist_summary(me_artist, t_from, t_to),
    'previous', artist_summary(me_artist, t_prev, t_from),
    'followers_total', (select count(*) from counted_follows where artist_id = me_artist),
    'daily', (
      select json_agg(json_build_object(
        'day', d::date,
        'impressions', (select count(*) from analytics_events e where e.artist_id = me_artist and e.kind = 'impression' and e.day = d::date),
        'views', (select count(*) from analytics_events e where e.artist_id = me_artist and e.kind = 'artwork_view' and e.day = d::date),
        'visits', (select count(*) from analytics_events e where e.artist_id = me_artist and e.kind = 'profile_visit' and e.day = d::date),
        'likes', (select count(*) from counted_reactions r join artworks w on w.id = r.artwork_id
                   where w.artist_id = me_artist and r.kind in ('like', 'super') and r.created_at >= d and r.created_at < d + interval '1 day'),
        'followers', (select count(*) from counted_follows f where f.artist_id = me_artist and f.created_at < d + interval '1 day')
      ) order by d)
      from generate_series(t_from, t_to - interval '1 day', interval '1 day') d
    ),
    'works', coalesce((
      select json_agg(x order by x.views desc, x.likes desc) from (
        select w.id, w.title,
          (select count(*) from analytics_events e where e.artwork_id = w.id and e.kind = 'impression' and e.created_at >= t_from)::int as impressions,
          (select count(*) from analytics_events e where e.artwork_id = w.id and e.kind = 'artwork_view' and e.created_at >= t_from)::int as views,
          (select count(*) from counted_reactions r where r.artwork_id = w.id and r.kind = 'like' and r.created_at >= t_from)::int as likes,
          (select count(*) from counted_reactions r where r.artwork_id = w.id and r.kind = 'super' and r.created_at >= t_from)::int as saves
        from artworks w where w.artist_id = me_artist
      ) x), '[]'::json),
    'roles', coalesce((
      select json_object_agg(role, n) from (
        select role, count(distinct user_id) as n from (
          select r.user_id, r.role from counted_reactions r join artworks w on w.id = r.artwork_id
            where w.artist_id = me_artist and r.kind in ('like', 'super') and r.created_at >= t_from
          union all
          select f.user_id, f.role from counted_follows f where f.artist_id = me_artist and f.created_at >= t_from
        ) a group by role
      ) g), '{}'::json),
    'countries', coalesce((
      select json_agg(json_build_object('country', country, 'people', people) order by people desc, country) from (
        select case when n >= 3 then country else 'Other' end as country, sum(n)::int as people from (
          select p.country, count(*) as n from profiles p
          where p.id in (
            select r.user_id from counted_reactions r join artworks w on w.id = r.artwork_id
              where w.artist_id = me_artist and r.kind in ('like', 'super') and r.created_at >= t_from
            union select f.user_id from counted_follows f where f.artist_id = me_artist and f.created_at >= t_from
            union select e.viewer_id from analytics_events e where e.artist_id = me_artist and e.viewer_id is not null and e.created_at >= t_from)
          group by p.country
        ) c group by 1
      ) g), '[]'::json)
  );
end $$;

create or replace function public.create_drop(p_title text, p_description text, p_release_at timestamptz, p_artworks text[], p_teaser text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  ar public.artists;
  d public.drops;
  max_upcoming integer;
begin
  select * into ar from artists where owner_id = uid;
  if uid is null or ar.id is null then
    raise exception 'Publish a work first' using errcode = '42501';
  end if;
  if p_release_at < now() + interval '10 minutes' or p_release_at > now() + interval '60 days' then
    raise exception 'Release between 10 minutes and 60 days from now' using errcode = '22023';
  end if;
  if coalesce(cardinality(p_artworks), 0) not between 1 and 12 then
    raise exception 'A drop has 1 to 12 works' using errcode = '22023';
  end if;
  if (select count(*) from artworks where id = any (p_artworks) and owner_id = uid and not hidden
        and (drop_id is null or drop_id in (select id from drops where released_at is not null or cancelled_at is not null))) <> cardinality(p_artworks) then
    raise exception 'A drop can include only your own works that aren’t in another upcoming drop' using errcode = '42501';
  end if;
  if p_teaser is not null and not (p_teaser = any (p_artworks)) then
    raise exception 'The preview must be one of the drop’s works' using errcode = '22023';
  end if;
  max_upcoming := (current_plan(uid)).max_upcoming_drops;
  if (select count(*) from drops where owner_id = uid and released_at is null and cancelled_at is null) >= max_upcoming then
    raise exception 'Your plan allows % upcoming drop% at a time', max_upcoming, case when max_upcoming = 1 then '' else 's' end using errcode = 'P0001';
  end if;
  insert into drops (artist_id, owner_id, title, description, release_at, teaser_artwork)
  values (ar.id, uid, btrim(p_title), btrim(coalesce(p_description, '')), p_release_at, coalesce(p_teaser, p_artworks[1]))
  returning * into d;
  update artworks set drop_id = d.id, release_at = d.release_at where id = any (p_artworks);
  insert into notifications (user_id, kind, title, link)
  select f.user_id, 'drop_announced', ar.name || ' announced a drop: “' || d.title || '”', 'drop/' || d.id
  from counted_follows f where f.artist_id = ar.id;
  return d.id;
end $$;

-- Elite artists' exhibitions are reviewed first (order only; the checks are the same).
create or replace function public.admin_exhibition_queue() returns json
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return coalesce((select json_agg(json_build_object('id', x.id, 'artist', x.artist, 'artist_id', x.artist_id, 'kind', x.kind, 'title', x.title,
                                    'venue', x.venue, 'city', x.city, 'country', x.country, 'start_date', x.start_date, 'end_date', x.end_date,
                                    'link', x.link, 'created_at', x.created_at, 'priority', x.priority) order by x.priority desc, x.created_at)
                   from (select e.*, ar.name as artist, (current_plan(e.owner_id)).priority_review as priority
                         from exhibitions e join artists ar on ar.id = e.artist_id where e.status = 'pending') x), '[]'::json);
end $$;

-- Opportunities: moderators publish directly; verified galleries on the Gallery plan publish directly
-- (10 a day, audited); everyone else's suggestion waits for review (accounts 3+ days old, 5 a day).
create or replace function public.suggest_opportunity(p_kind text, p_title text, p_organizer text, p_location text, p_deadline date,
                                                      p_eligibility text, p_description text, p_fee numeric, p_fee_currency text, p_link text)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  admin boolean := is_admin();
  gal public.galleries;
  direct boolean;
  daily integer;
  new_id uuid;
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  select * into gal from galleries where owner_id = uid and status = 'verified';
  direct := admin or (gal.id is not null and (current_plan(uid)).direct_opportunities);
  if not admin and gal.id is null and (select created_at from profiles where id = uid) > now() - interval '3 days' then
    raise exception 'New accounts can suggest opportunities after 3 days' using errcode = '42501';
  end if;
  daily := case when direct then 10 else 5 end;
  if not admin and (select count(*) from opportunities where submitted_by = uid and created_at > now() - interval '1 day') >= daily then
    raise exception 'You can post % opportunities a day', daily using errcode = 'P0001';
  end if;
  if p_deadline < current_date then
    raise exception 'The deadline has passed' using errcode = '22023';
  end if;
  insert into opportunities (kind, title, organizer, location, deadline, eligibility, description, fee, fee_currency, link, status, submitted_by,
                             reviewed_by, reviewed_at, gallery_id)
  values (p_kind, btrim(p_title), case when gal.id is not null then gal.name else btrim(p_organizer) end, btrim(p_location), p_deadline,
          btrim(coalesce(p_eligibility, '')), btrim(coalesce(p_description, '')),
          coalesce(p_fee, 0), upper(coalesce(nullif(p_fee_currency, ''), 'USD')), btrim(p_link),
          case when direct then 'approved' else 'pending' end, uid, case when direct then uid end, case when direct then now() end, gal.id)
  returning opportunities.id into new_id;
  if direct then
    perform log_audit(case when admin then 'opportunity.published' else 'opportunity.published_by_gallery' end, 'opportunity', new_id::text,
                      jsonb_build_object('title', p_title, 'gallery', gal.name));
  end if;
  return new_id;
end $$;

create or replace function public.opportunities_list() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_agg(json_build_object(
    'id', o.id, 'kind', o.kind, 'title', o.title, 'organizer', o.organizer, 'location', o.location, 'deadline', o.deadline,
    'eligibility', o.eligibility, 'description', o.description, 'fee', o.fee, 'fee_currency', o.fee_currency, 'link', o.link,
    'gallery_id', g.id,
    'saved', exists (select 1 from saved_opportunities s where s.opportunity_id = o.id and s.user_id = auth.uid())
  ) order by o.deadline, o.title), '[]'::json)
  from opportunities o left join galleries g on g.id = o.gallery_id and g.status = 'verified'
  where o.status = 'approved' and o.deadline >= current_date
$$;

-- ——— 4. Beta: invite codes, feedback, app errors ———
create table if not exists public.invite_codes (
  code text primary key check (code ~ '^[A-Z0-9]{10}$'),
  created_by uuid references auth.users (id) on delete set null,
  max_uses integer not null check (max_uses between 1 and 500),
  uses integer not null default 0 check (uses >= 0),
  expires_at timestamptz,
  note text check (char_length(coalesce(note, '')) <= 200),
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);
alter table public.invite_codes enable row level security;
revoke all on public.invite_codes from anon, authenticated;

create table if not exists public.invite_redemptions (
  code text not null references public.invite_codes (code) on delete cascade,
  user_id uuid not null,
  created_at timestamptz not null default now(),
  primary key (code, user_id)
);
alter table public.invite_redemptions enable row level security;
revoke all on public.invite_redemptions from anon, authenticated;

-- While invites are required, a new account needs a valid code in its sign-up metadata
-- (signInWithOtp options.data.invite). Existing members sign in as usual.
create or replace function public.guard_invite() returns trigger
language plpgsql security definer set search_path = public as $$
declare c text := upper(btrim(coalesce(new.raw_user_meta_data->>'invite', '')));
begin
  if not coalesce((select invite_required from app_settings), false) then
    return new;
  end if;
  update invite_codes set uses = uses + 1
   where code = c and revoked_at is null and uses < max_uses and (expires_at is null or expires_at > now());
  if not found then
    raise exception 'Abremi is invite-only right now: a valid invite code is needed to join' using errcode = '42501';
  end if;
  insert into invite_redemptions (code, user_id) values (c, new.id) on conflict do nothing;
  return new;
end $$;
revoke all on function public.guard_invite() from public, anon, authenticated;
drop trigger if exists abremi_guard_invite on auth.users;
create trigger abremi_guard_invite before insert on auth.users for each row execute function public.guard_invite();

-- Lets the sign-in form say whether a code works before an email is sent. Reveals only yes/no.
create or replace function public.check_invite(p_code text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from invite_codes where code = upper(btrim(coalesce(p_code, ''))) and revoked_at is null
                 and uses < max_uses and (expires_at is null or expires_at > now()))
$$;

create or replace function public.admin_create_invite(p_max_uses integer, p_days integer default 30, p_note text default null) returns text
language plpgsql security definer set search_path = public as $$
declare c text;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  if p_days is not null and p_days not between 1 and 365 then
    raise exception 'Codes last 1 to 365 days' using errcode = '22023';
  end if;
  -- 10 characters from an alphabet without look-alikes (no 0/O, 1/I/L), each from a fresh random UUID.
  select string_agg(substr('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + get_byte(decode(md5(gen_random_uuid()::text), 'hex'), 0) % 31, 1), '')
    into c from generate_series(1, 10);
  insert into invite_codes (code, created_by, max_uses, expires_at, note)
  values (c, auth.uid(), p_max_uses, case when p_days is not null then now() + make_interval(days => p_days) end, nullif(btrim(coalesce(p_note, '')), ''));
  perform log_audit('invite.created', 'invite', c, jsonb_build_object('max_uses', p_max_uses, 'days', p_days, 'note', p_note));
  return c;
end $$;

create or replace function public.admin_invites() returns json
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return json_build_object(
    'invite_required', (select invite_required from app_settings),
    'codes', coalesce((select json_agg(json_build_object('code', code, 'max_uses', max_uses, 'uses', uses, 'expires_at', expires_at, 'note', note,
                                        'revoked', revoked_at is not null, 'created_at', created_at) order by created_at desc)
                       from invite_codes), '[]'::json));
end $$;

create or replace function public.admin_revoke_invite(p_code text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update invite_codes set revoked_at = now() where code = p_code and revoked_at is null;
  if found then
    perform log_audit('invite.revoked', 'invite', p_code, '{}'::jsonb);
  end if;
end $$;

create or replace function public.admin_set_invite_required(p_on boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update app_settings set invite_required = p_on, updated_at = now();
  perform log_audit(case when p_on then 'beta.invites_required' else 'beta.invites_optional' end, 'settings', 'invite_required', '{}'::jsonb);
end $$;

create table if not exists public.feedback (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references public.profiles (id) on delete set null,
  kind text not null check (kind in ('bug', 'idea', 'other')),
  message text not null check (char_length(btrim(message)) between 5 and 2000),
  page text check (char_length(coalesce(page, '')) <= 200),
  user_agent text check (char_length(coalesce(user_agent, '')) <= 300),
  status text not null default 'open' check (status in ('open', 'resolved')),
  note text check (char_length(coalesce(note, '')) <= 500),
  created_at timestamptz not null default now(),
  resolved_by uuid references auth.users (id) on delete set null,
  resolved_at timestamptz
);
alter table public.feedback enable row level security;
drop policy if exists "read own feedback" on public.feedback;
create policy "read own feedback" on public.feedback for select using (user_id = auth.uid());
revoke all on public.feedback from anon, authenticated;
grant select on public.feedback to authenticated;

create or replace function public.submit_feedback(p_kind text, p_message text, p_page text default null, p_user_agent text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare new_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if (select count(*) from feedback where user_id = auth.uid() and created_at > now() - interval '1 day') >= 10 then
    raise exception 'You can send 10 notes a day. Thank you!' using errcode = 'P0001';
  end if;
  insert into feedback (user_id, kind, message, page, user_agent)
  values (auth.uid(), p_kind, btrim(p_message), left(p_page, 200), left(p_user_agent, 300))
  returning id into new_id;
  return new_id;
end $$;

create or replace function public.admin_feedback(p_status text default 'open') returns json
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return coalesce((select json_agg(json_build_object('id', f.id, 'kind', f.kind, 'message', f.message, 'page', f.page, 'user_agent', f.user_agent,
                                    'member', p.name, 'created_at', f.created_at, 'status', f.status, 'note', f.note) order by f.created_at desc)
                   from (select * from feedback where status = coalesce(p_status, 'open') order by created_at desc limit 200) f
                   left join profiles p on p.id = f.user_id), '[]'::json);
end $$;

create or replace function public.resolve_feedback(p_id uuid, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  update feedback set status = 'resolved', note = nullif(btrim(coalesce(p_note, '')), ''), resolved_by = auth.uid(), resolved_at = now()
   where id = p_id and status = 'open';
  if not found then
    raise exception 'That note is already resolved' using errcode = 'P0001';
  end if;
end $$;

-- App errors: what broke and where, with no account, IP or personal data. Capped so it can't be flooded.
create table if not exists public.client_errors (
  id bigint generated always as identity primary key,
  message text not null,
  source text,
  page text,
  release text,
  user_agent text,
  signed_in boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists client_errors_time_idx on public.client_errors (created_at);
alter table public.client_errors enable row level security;
revoke all on public.client_errors from anon, authenticated;

create or replace function public.log_client_error(p_message text, p_source text default null, p_page text default null,
                                                   p_release text default null, p_user_agent text default null) returns void
language plpgsql security definer set search_path = public as $$
begin
  if coalesce(btrim(p_message), '') = '' then
    return;
  end if;
  if (select count(*) from client_errors where created_at > now() - interval '1 hour') >= 500 then
    return; -- quietly drop the excess
  end if;
  insert into client_errors (message, source, page, release, user_agent, signed_in)
  values (left(btrim(p_message), 500), left(p_source, 300), left(regexp_replace(coalesce(p_page, ''), '[?].*$', ''), 200), left(p_release, 40),
          left(p_user_agent, 300), auth.uid() is not null);
end $$;

create or replace function public.admin_client_errors(p_days integer default 7) returns json
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return coalesce((select json_agg(x order by x.last_seen desc) from (
    select message, source, count(*)::int as count, max(created_at) as last_seen, min(created_at) as first_seen,
           array_agg(distinct release) filter (where release is not null) as releases,
           array_agg(distinct page) filter (where page is not null and page <> '') as pages
    from client_errors where created_at > now() - make_interval(days => least(greatest(coalesce(p_days, 7), 1), 30))
    group by message, source order by max(created_at) desc limit 100) x), '[]'::json);
end $$;

create or replace function public.prune_client_errors() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  delete from client_errors where created_at < now() - interval '30 days';
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function public.prune_client_errors() from public, anon, authenticated;

-- ——— 5. Billing hooks (inactive while payments are off) ———
-- The billing server function (api/stripe-webhook.js) calls apply_billing_event() with the service
-- role. Events are applied once (by id), and only while payments are switched on.
create table if not exists public.billing_events (
  id text primary key check (char_length(id) <= 100),
  user_id uuid,
  kind text,
  created_at timestamptz not null default now()
);
alter table public.billing_events enable row level security;
revoke all on public.billing_events from anon, authenticated;

create or replace function public.apply_billing_event(p_event_id text, p_kind text, p_user uuid, p_plan text, p_status text,
                                                      p_period_end timestamptz, p_customer text, p_subscription text) returns text
language plpgsql security definer set search_path = public as $$
begin
  if not (select payments_enabled from app_settings) then
    raise exception 'Payments are switched off' using errcode = '42501';
  end if;
  insert into billing_events (id, user_id, kind) values (p_event_id, p_user, p_kind) on conflict (id) do nothing;
  if not found then
    return 'duplicate';
  end if;
  if not exists (select 1 from profiles where id = p_user) then
    return 'unknown member';
  end if;
  if p_plan not in ('pro', 'elite', 'gallery') or p_status not in ('active', 'trialing', 'past_due', 'canceled') then
    raise exception 'Unknown plan or status' using errcode = '22023';
  end if;
  if p_plan = 'gallery' and not exists (select 1 from galleries where owner_id = p_user and status = 'verified') then
    return 'not a verified gallery';
  end if;
  insert into subscriptions (user_id, plan, status, source, current_period_end, billing_customer, billing_subscription, updated_at)
  values (p_user, p_plan, p_status, 'billing', p_period_end, p_customer, p_subscription, now())
  on conflict (user_id) do update set plan = excluded.plan, status = excluded.status, source = 'billing',
    current_period_end = excluded.current_period_end, billing_customer = coalesce(excluded.billing_customer, subscriptions.billing_customer),
    billing_subscription = coalesce(excluded.billing_subscription, subscriptions.billing_subscription), granted_by = null, note = null, updated_at = now()
  where subscriptions.source = 'grant' or subscriptions.billing_subscription is null or subscriptions.billing_subscription = excluded.billing_subscription;
  perform log_audit('plan.billing_' || p_status, 'member', p_user::text, jsonb_build_object('plan', p_plan, 'event', p_event_id));
  return 'applied';
end $$;
revoke all on function public.apply_billing_event(text, text, uuid, text, text, timestamptz, text, text) from public, anon, authenticated;
grant execute on function public.apply_billing_event(text, text, uuid, text, text, timestamptz, text, text) to service_role;

-- ——— Grants ———
do $$
declare f text;
begin
  foreach f in array array[
    'my_plan()', 'admin_find_members(text)', 'apply_gallery(text, text, text, text, text)', 'admin_gallery_queue()',
    'review_gallery(uuid, boolean, text)', 'my_gallery()', 'admin_grant_plan(uuid, text, date, text)', 'admin_revoke_plan(uuid, text)',
    'admin_plan_holders()', 'coach_usage()', 'begin_coach_request(text, text, uuid)', 'studio_analytics(integer)',
    'create_drop(text, text, timestamptz, text[], text)', 'admin_exhibition_queue()',
    'suggest_opportunity(text, text, text, text, date, text, text, numeric, text, text)',
    'admin_create_invite(integer, integer, text)', 'admin_invites()', 'admin_revoke_invite(text)', 'admin_set_invite_required(boolean)',
    'submit_feedback(text, text, text, text)', 'admin_feedback(text)', 'resolve_feedback(uuid, text)', 'admin_client_errors(integer)'
  ] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['app_flags()', 'plan_badges()', 'gallery_page(uuid)', 'opportunities_list()', 'check_invite(text)',
                           'log_client_error(text, text, text, text, text)'] loop
    execute format('revoke all on function public.%s from public', f);
    execute format('grant execute on function public.%s to anon, authenticated', f);
  end loop;
end $$;

-- App errors older than 30 days are deleted daily where pg_cron is available.
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('abremi-prune-client-errors', '41 3 * * *', 'select public.prune_client_errors();');
  end if;
exception when others then
  raise notice 'Schedule not set up (%). Old app errors need pg_cron to be pruned.', sqlerrm;
end $$;

-- ═════ 0013_assistant.sql ═════
-- Abremi Phase 7: the Abremi Guide, one assistant with three modes (discovery, artists, collectors).
--
-- The AI runs in a Vercel server function (api/assistant.js) that holds the API key. It calls
-- begin_assistant_request() with the member's own session, so the database decides who may ask, applies
-- the limits, and hands over only public catalog data plus the member's OWN data. Conversations are
-- never stored: assistant_requests keeps the mode, time and outcome; assistant_events keeps counts of
-- what people did with the suggestions. Plans set the daily allowance only; nothing here reads plans
-- when choosing what to show (tests/db.test.js checks this).

-- ——— 0. The Career Coach becomes a Pro, Elite and Gallery feature (to keep AI costs in check) ———
update public.plans set coach_monthly = 0 where code = 'free';

-- Same as 0012, with a clear message when the plan includes no Coach requests.
create or replace function public.begin_coach_request(p_tool text, p_artwork text default null, p_opportunity uuid default null) returns json
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  ar public.artists;
  w public.artworks;
  o public.opportunities;
  req uuid;
  since timestamptz := now() - interval '30 days';
  monthly integer;
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  select * into ar from artists where owner_id = uid;
  if ar.id is null then
    raise exception 'The Coach is for artists: publish a work first' using errcode = '42501';
  end if;
  if p_tool not in ('bio', 'statement', 'description', 'engagement', 'social', 'application') then
    raise exception 'Unknown Coach tool' using errcode = '22023';
  end if;
  monthly := (current_plan(uid)).coach_monthly;
  if monthly = 0 then
    raise exception 'The Career Coach comes with Artist Pro and Elite' using errcode = '42501';
  end if;
  if (select count(*) from coach_requests where user_id = uid and status <> 'failed' and created_at >= date_trunc('month', now())) >= monthly then
    raise exception 'You’ve used this month’s % Coach requests. They reset on the 1st.', monthly using errcode = 'P0001';
  end if;
  if (select count(*) from coach_requests where status <> 'failed' and created_at > now() - interval '1 day') >= 400 then
    raise exception 'The Coach is busy today. Please try again tomorrow.' using errcode = 'P0001';
  end if;
  if p_tool in ('description', 'social') then
    select * into w from artworks where id = p_artwork and owner_id = uid;
    if w.id is null then
      raise exception 'Choose one of your own works' using errcode = '22023';
    end if;
  end if;
  if p_tool = 'application' then
    select * into o from opportunities where id = p_opportunity and status = 'approved';
    if o.id is null then
      raise exception 'Choose a listed opportunity' using errcode = '22023';
    end if;
  end if;
  insert into coach_requests (user_id, tool) values (uid, p_tool) returning id into req;
  return json_build_object(
    'request_id', req,
    'artist', json_build_object('name', ar.name, 'country', ar.country, 'city', ar.city, 'bio', ar.bio, 'statement', ar.statement,
                                'website', ar.website, 'joined', ar.created_at::date),
    'works', coalesce((select json_agg(json_build_object('id', x.id, 'title', x.title, 'medium', coalesce(x.medium, x.category), 'style', x.style,
                                       'year', x.year, 'dimensions', x.dimensions, 'availability', x.availability, 'description', x.description) order by x.created_at desc)
                       from (select * from artworks where owner_id = uid and not hidden order by created_at desc limit 30) x), '[]'::json),
    'artwork', case when w.id is not null then json_build_object('id', w.id, 'title', w.title, 'medium', coalesce(w.medium, w.category), 'style', w.style,
                    'year', w.year, 'dimensions', w.dimensions, 'description', w.description, 'thumb_path', w.thumb_path) end,
    'stats', case when p_tool = 'engagement' then json_build_object(
                    'last_30_days', artist_summary(ar.id, since, now()),
                    'previous_30_days', artist_summary(ar.id, since - interval '30 days', since),
                    'followers_total', (select count(*) from counted_follows where artist_id = ar.id)) end,
    'opportunity', case when o.id is not null then json_build_object('title', o.title, 'kind', o.kind, 'organizer', o.organizer, 'location', o.location,
                        'deadline', o.deadline, 'eligibility', o.eligibility, 'description', o.description) end,
    'achievements', coalesce((select json_agg(d.label) from member_achievements m join achievement_definitions d on d.code = m.code
                              where m.user_id = uid and d.audience = 'artist'), '[]'::json),
    'exhibitions', coalesce((select json_agg(json_build_object('title', e.title, 'venue', e.venue, 'year', extract(year from e.start_date)::int) order by e.start_date desc)
                             from exhibitions e where e.owner_id = uid and e.status = 'verified'), '[]'::json)
  );
end $$;

-- ——— 1. Allowance per plan (messages a day) ———
alter table public.plans add column if not exists assistant_daily integer not null default 30 check (assistant_daily between 0 and 1000);
update public.plans set assistant_daily = case code when 'free' then 30 when 'pro' then 60 when 'elite' then 100 when 'gallery' then 60 end;

-- ——— 2. Personalization preferences (the member's own; private) ———
alter table public.profiles add column if not exists assistant_personalize boolean not null default true;
alter table public.profiles add column if not exists assistant_interests text not null default '' check (char_length(assistant_interests) <= 300);

create or replace function public.assistant_preferences() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object('personalize', assistant_personalize, 'interests', assistant_interests) from profiles where id = auth.uid()
$$;

create or replace function public.set_assistant_preferences(p_personalize boolean, p_interests text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  update profiles set assistant_personalize = coalesce(p_personalize, true), assistant_interests = left(btrim(coalesce(p_interests, '')), 300)
   where id = auth.uid();
end $$;

-- Reset: forget stated interests and what the member did with suggestions. Follows, likes and saves
-- are the member's own features and stay; switch personalization off to stop the Guide using them.
create or replace function public.reset_assistant_personalization() returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  update profiles set assistant_interests = '', assistant_personalize = true where id = auth.uid();
  delete from assistant_events where user_id = auth.uid();
end $$;

-- ——— 3. Requests (limits and repeat use; never the conversation) ———
create table if not exists public.assistant_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  mode text not null check (mode in ('visitor', 'artist', 'collector')),
  status text not null default 'pending' check (status in ('pending', 'done', 'failed')),
  created_at timestamptz not null default now()
);
create index if not exists assistant_requests_user_idx on public.assistant_requests (user_id, created_at desc);
create index if not exists assistant_requests_day_idx on public.assistant_requests (created_at);
alter table public.assistant_requests enable row level security;
drop policy if exists "read own assistant requests" on public.assistant_requests;
create policy "read own assistant requests" on public.assistant_requests for select using (user_id = auth.uid());
revoke all on public.assistant_requests from anon, authenticated;
grant select on public.assistant_requests to authenticated;

create or replace function public.assistant_usage() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'used', (select count(*) from assistant_requests where user_id = auth.uid() and status <> 'failed' and created_at >= date_trunc('day', now())),
    'limit', (current_plan(auth.uid())).assistant_daily,
    'resets_at', date_trunc('day', now()) + interval '1 day')
  where auth.uid() is not null
$$;

-- What the Guide may know about the page being viewed: public data only (and the member's own).
create or replace function public.assistant_page_context(p_type text, p_id text) returns json
language plpgsql stable security definer set search_path = public as $$
declare
  w public.artworks;
  ar public.artists;
  pair text[];
begin
  if p_type = 'artwork' then
    select * into w from artworks where id = p_id and not hidden and (release_at is null or release_at <= now() or owner_id = auth.uid());
    if w.id is null then return null; end if;
    select * into ar from artists where id = w.artist_id;
    return json_build_object('type', 'artwork',
      'artwork', json_build_object('id', w.id, 'title', w.title, 'artist_id', w.artist_id, 'artist', ar.name, 'category', w.category, 'style', w.style,
                                   'medium', w.medium, 'year', w.year, 'description', w.description, 'dimensions', w.dimensions,
                                   'availability', case when w.owner_id is null then 'sample' else w.availability end, 'sample', w.owner_id is null,
                                   'thumb_path', case when w.owner_id is not null then w.thumb_path end),
      'signals', json_build_object(
        'likes', (select count(*) from counted_reactions where artwork_id = w.id and kind = 'like'),
        'saves', (select count(*) from counted_reactions where artwork_id = w.id and kind = 'super'),
        'reviews', (select count(*) from counted_reviews where artwork_id = w.id),
        'battle_rating', (select rating from artwork_ratings where artwork_id = w.id),
        'battle_votes', (select votes from artwork_ratings where artwork_id = w.id)));
  elsif p_type = 'artist' then
    select * into ar from artists where id = p_id;
    if ar.id is null then return null; end if;
    return json_build_object('type', 'artist',
      'artist', json_build_object('id', ar.id, 'name', ar.name, 'country', ar.country, 'city', ar.city, 'sample', ar.owner_id is null,
                                  'bio', left(ar.bio, 600), 'statement', left(ar.statement, 600), 'joined', ar.created_at::date),
      'followers', (select count(*) from counted_follows where artist_id = ar.id),
      'works', coalesce((select json_agg(a.id order by a.created_at desc) from (
        select id, created_at from artworks where artist_id = ar.id and not hidden and (release_at is null or release_at <= now()) order by created_at desc limit 24) a), '[]'::json),
      'achievements', coalesce((select json_agg(d.label) from member_achievements m join achievement_definitions d on d.code = m.code and d.audience = 'artist'
                                where m.user_id = ar.owner_id), '[]'::json));
  elsif p_type = 'collection' then
    -- Shared collections by link, or the member's own; never the owner's name unless it's the member.
    return (select json_build_object('type', 'collection', 'name', c.name, 'description', c.description, 'mine', c.owner_id = auth.uid(),
              'items', coalesce((select json_agg(i.artwork_id order by i.added_at desc) from collection_items i join artworks a on a.id = i.artwork_id
                                 where i.collection_id = c.id and not a.hidden), '[]'::json))
            from collections c where c.id::text = p_id and (not c.is_private or c.owner_id = auth.uid()));
  elsif p_type = 'ranking' then
    return json_build_object('type', 'ranking', 'view', left(p_id, 40),
      'top_artworks', coalesce((select json_agg(x.artwork_id order by x.popularity desc, x.artwork_id) from (
        select s.artwork_id, s.popularity from artwork_scores() s join artworks a on a.id = s.artwork_id
        where not a.hidden and (a.release_at is null or a.release_at <= now()) order by s.popularity desc, s.artwork_id limit 15) x), '[]'::json),
      'trending', coalesce((select json_agg(x.artwork_id order by x.trending desc, x.artwork_id) from (
        select s.artwork_id, s.trending from artwork_scores() s join artworks a on a.id = s.artwork_id
        where not a.hidden and (a.release_at is null or a.release_at <= now()) and s.trending > 0 order by s.trending desc, s.artwork_id limit 10) x), '[]'::json),
      'top_artists', coalesce((select json_agg(x.artist_id order by x.reputation desc, x.artist_id) from (
        select artist_id, reputation from artist_scores() order by reputation desc, artist_id limit 10) x), '[]'::json));
  elsif p_type = 'battle' then
    pair := string_to_array(p_id, ',');
    return json_build_object('type', 'battle', 'pair', coalesce((select json_agg(json_build_object('id', a.id, 'rating', r.rating, 'votes', r.votes))
      from artworks a left join artwork_ratings r on r.artwork_id = a.id
      where a.id = any (pair[1:2]) and not a.hidden and (a.release_at is null or a.release_at <= now())), '[]'::json));
  elsif p_type = 'competition' then
    return (select json_build_object('type', 'competition', 'title', c.title, 'kind', c.kind, 'brief', c.brief, 'category', c.category,
                                     'phase', competition_phase(c), 'voting_closes_at', c.voting_closes_at,
                                     'results', case when c.closed_at is not null then c.results->'entries' end)
            from competitions c where c.id::text = p_id and c.cancelled_at is null);
  end if;
  return null;
end $$;
revoke all on function public.assistant_page_context(text, text) from public, anon, authenticated;

-- The public catalog the Guide chooses suggestions from: visible works and artists with their public
-- totals. It never reads plans, private collections, other members' activity or contact details.
create or replace function public.assistant_catalog() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'artworks', coalesce((select json_agg(json_build_object('id', a.id, 'title', a.title, 'artist_id', a.artist_id, 'category', a.category,
                                 'style', a.style, 'medium', a.medium, 'year', a.year, 'sample', a.owner_id is null,
                                 'availability', case when a.owner_id is null then null else a.availability end,
                                 'description', left(a.description, 240), 'popularity', coalesce(s.popularity, 0), 'trending', coalesce(s.trending, 0),
                                 'created_at', a.created_at))
                          from artworks a left join artwork_scores() s on s.artwork_id = a.id
                          where not a.hidden and (a.release_at is null or a.release_at <= now())), '[]'::json),
    'artists', coalesce((select json_agg(json_build_object('id', ar.id, 'name', ar.name, 'country', ar.country, 'city', ar.city,
                                 'sample', ar.owner_id is null, 'bio', left(ar.bio, 200),
                                 'followers', (select count(*) from counted_follows f where f.artist_id = ar.id)))
                         from artists ar), '[]'::json))
$$;
revoke all on function public.assistant_catalog() from public, anon, authenticated;

-- Starts a request: signed-in members only; the artist mode only for artists; the plan's daily
-- allowance and an overall daily cap. Returns the grounding context.
create or replace function public.begin_assistant_request(p_mode text, p_page_type text default null, p_page_id text default null) returns json
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  me public.profiles;
  ar public.artists;
  daily integer;
  req uuid;
  since timestamptz := now() - interval '30 days';
begin
  if uid is null then
    raise exception 'Sign in to use the Guide' using errcode = '42501';
  end if;
  if p_mode not in ('visitor', 'artist', 'collector') then
    raise exception 'Unknown mode' using errcode = '22023';
  end if;
  select * into me from profiles where id = uid;
  select * into ar from artists where owner_id = uid;
  if p_mode = 'artist' and ar.id is null then
    raise exception 'The artist mode is for artists: publish a work first' using errcode = '42501';
  end if;
  daily := (current_plan(uid)).assistant_daily;
  if (select count(*) from assistant_requests where user_id = uid and status <> 'failed' and created_at >= date_trunc('day', now())) >= daily then
    raise exception 'You’ve used today’s % messages. They reset at midnight UTC.', daily using errcode = 'P0001';
  end if;
  if (select count(*) from assistant_requests where status <> 'failed' and created_at > now() - interval '1 day') >= 2000 then
    raise exception 'The Guide is busy today. Please try again tomorrow.' using errcode = 'P0001';
  end if;
  insert into assistant_requests (user_id, mode) values (uid, p_mode) returning id into req;
  return json_build_object(
    'request_id', req,
    'mode', p_mode,
    'member', json_build_object('role', me.role, 'country', me.country, 'is_artist', ar.id is not null),
    'page', case when p_page_type is not null then assistant_page_context(p_page_type, p_page_id) end,
    'catalog', assistant_catalog(),
    'personal', case when me.assistant_personalize then json_build_object(
        'interests', me.assistant_interests,
        'follows', coalesce((select json_agg(artist_id order by created_at desc) from (select artist_id, created_at from follows where user_id = uid order by created_at desc limit 50) f), '[]'::json),
        'saved', coalesce((select json_agg(artwork_id order by created_at desc) from (select artwork_id, created_at from reactions where user_id = uid and kind = 'super' order by created_at desc limit 50) r), '[]'::json),
        'liked', coalesce((select json_agg(artwork_id order by created_at desc) from (select artwork_id, created_at from reactions where user_id = uid and kind = 'like' order by created_at desc limit 50) r), '[]'::json))
      else json_build_object('interests', '', 'follows', '[]'::json, 'saved', '[]'::json, 'liked', '[]'::json) end,
    'collections', case when p_mode = 'collector' then coalesce((select json_agg(json_build_object('name', c.name, 'private', c.is_private,
                          'items', coalesce((select json_agg(i.artwork_id) from collection_items i where i.collection_id = c.id), '[]'::json)) order by c.updated_at desc)
                       from collections c where c.owner_id = uid), '[]'::json) end,
    'studio', case when p_mode = 'artist' then json_build_object(
        'artist', json_build_object('id', ar.id, 'name', ar.name, 'country', ar.country, 'city', ar.city, 'bio', ar.bio, 'statement', ar.statement,
                                    'website', ar.website is not null, 'portrait', ar.avatar_path is not null),
        'works', coalesce((select json_agg(json_build_object('id', a.id, 'title', a.title, 'category', a.category, 'style', a.style, 'medium', a.medium,
                                 'has_description', coalesce(a.description, '') <> '', 'has_dimensions', a.dimensions is not null,
                                 'availability', a.availability, 'hidden', a.hidden) order by a.created_at desc)
                          from (select * from artworks where owner_id = uid order by created_at desc limit 40) a), '[]'::json),
        'last_30_days', artist_summary(ar.id, since, now()),
        'previous_30_days', artist_summary(ar.id, since - interval '30 days', since),
        'followers_total', (select count(*) from counted_follows where artist_id = ar.id)) end
  );
end $$;

create or replace function public.finish_assistant_request(p_id uuid, p_ok boolean) returns void
language sql security definer set search_path = public as $$
  update assistant_requests set status = case when p_ok then 'done' else 'failed' end
   where id = p_id and user_id = auth.uid() and status = 'pending'
$$;

-- ——— 4. What people do with suggestions (counts only) ———
create table if not exists public.assistant_events (
  id bigint generated always as identity primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('open', 'artwork_click', 'artist_visit', 'follow', 'collection_add', 'search')),
  target text check (char_length(coalesce(target, '')) <= 100),
  created_at timestamptz not null default now()
);
create index if not exists assistant_events_time_idx on public.assistant_events (created_at);
alter table public.assistant_events enable row level security;
revoke all on public.assistant_events from anon, authenticated;

create or replace function public.record_assistant_event(p_kind text, p_target text default null) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    return;
  end if;
  if (select count(*) from assistant_events where user_id = auth.uid() and created_at > now() - interval '1 hour') >= 300 then
    return;
  end if;
  insert into assistant_events (user_id, kind, target) values (auth.uid(), p_kind, left(p_target, 100));
end $$;

create or replace function public.admin_assistant_metrics(p_days integer default 30) returns json
language plpgsql stable security definer set search_path = public as $$
declare since timestamptz := now() - make_interval(days => least(greatest(coalesce(p_days, 30), 1), 365));
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  return json_build_object(
    'days', least(greatest(coalesce(p_days, 30), 1), 365),
    'messages', (select count(*) from assistant_requests where created_at >= since and status = 'done'),
    'failed', (select count(*) from assistant_requests where created_at >= since and status = 'failed'),
    'members', (select count(distinct user_id) from assistant_requests where created_at >= since),
    'returning', (select count(*) from (select user_id from assistant_requests where created_at >= since
                                        group by user_id having count(distinct created_at::date) >= 2) r),
    'by_mode', coalesce((select json_object_agg(mode, n) from (select mode, count(*) as n from assistant_requests where created_at >= since group by mode) m), '{}'::json),
    'events', coalesce((select json_object_agg(kind, n) from (select kind, count(*) as n from assistant_events where created_at >= since group by kind) e), '{}'::json));
end $$;

create or replace function public.prune_assistant_data() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer; m integer;
begin
  delete from assistant_events where created_at < now() - interval '400 days';
  get diagnostics n = row_count;
  delete from assistant_requests where created_at < now() - interval '400 days';
  get diagnostics m = row_count;
  return n + m;
end $$;
revoke all on function public.prune_assistant_data() from public, anon, authenticated;

-- ——— Grants ———
do $$
declare f text;
begin
  foreach f in array array[
    'assistant_preferences()', 'set_assistant_preferences(boolean, text)', 'reset_assistant_personalization()', 'assistant_usage()',
    'begin_assistant_request(text, text, text)', 'finish_assistant_request(uuid, boolean)', 'record_assistant_event(text, text)',
    'admin_assistant_metrics(integer)'
  ] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('abremi-prune-assistant', '17 4 * * *', 'select public.prune_assistant_data();');
  end if;
exception when others then
  raise notice 'Schedule not set up (%). Old assistant counts need pg_cron to be pruned.', sqlerrm;
end $$;

-- ═════ 0014_teasers_badges.sql ═════
-- Abremi: the two low-risk items from the Phase 6 security review.
--
--   1. Drop teasers. Until a drop is released, its teaser image is no longer handed out (it was only
--      blurred in the browser, so the real image could be opened). The artist's app stores a 3×3
--      palette sampled from the image, and the drop page paints a soft veil from those nine colours.
--      The artist still sees their own teaser; everyone sees it once the drop is released.
--   2. Plan badges. Artists can hide their Pro or Elite badge; it is shown by default.

-- ——— 1. Drop teasers ———
alter table public.drops add column if not exists teaser_palette text
  check (teaser_palette is null or teaser_palette ~ '^(#[0-9a-f]{6},){8}#[0-9a-f]{6}$');

drop function if exists public.create_drop(text, text, timestamptz, text[], text);
create or replace function public.create_drop(p_title text, p_description text, p_release_at timestamptz, p_artworks text[], p_teaser text default null, p_teaser_palette text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  ar public.artists;
  d public.drops;
  max_upcoming integer;
begin
  select * into ar from artists where owner_id = uid;
  if uid is null or ar.id is null then
    raise exception 'Publish a work first' using errcode = '42501';
  end if;
  if p_release_at < now() + interval '10 minutes' or p_release_at > now() + interval '60 days' then
    raise exception 'Release between 10 minutes and 60 days from now' using errcode = '22023';
  end if;
  if coalesce(cardinality(p_artworks), 0) not between 1 and 12 then
    raise exception 'A drop has 1 to 12 works' using errcode = '22023';
  end if;
  if (select count(*) from artworks where id = any (p_artworks) and owner_id = uid and not hidden
        and (drop_id is null or drop_id in (select id from drops where released_at is not null or cancelled_at is not null))) <> cardinality(p_artworks) then
    raise exception 'A drop can include only your own works that aren’t in another upcoming drop' using errcode = '42501';
  end if;
  if p_teaser is not null and not (p_teaser = any (p_artworks)) then
    raise exception 'The preview must be one of the drop’s works' using errcode = '22023';
  end if;
  max_upcoming := (current_plan(uid)).max_upcoming_drops;
  if (select count(*) from drops where owner_id = uid and released_at is null and cancelled_at is null) >= max_upcoming then
    raise exception 'Your plan allows % upcoming drop% at a time', max_upcoming, case when max_upcoming = 1 then '' else 's' end using errcode = 'P0001';
  end if;
  insert into drops (artist_id, owner_id, title, description, release_at, teaser_artwork, teaser_palette)
  values (ar.id, uid, btrim(p_title), btrim(coalesce(p_description, '')), p_release_at, coalesce(p_teaser, p_artworks[1]), lower(nullif(btrim(coalesce(p_teaser_palette, '')), '')))
  returning * into d;
  update artworks set drop_id = d.id, release_at = d.release_at where id = any (p_artworks);
  insert into notifications (user_id, kind, title, link)
  select f.user_id, 'drop_announced', ar.name || ' announced a drop: “' || d.title || '”', 'drop/' || d.id
  from counted_follows f where f.artist_id = ar.id;
  return d.id;
end $$;

create or replace function public.drops_overview() returns json
language plpgsql security definer set search_path = public as $$
begin
  perform release_due_drops();
  return coalesce((select json_agg(x order by x.sort, x.release_at) from (
    select d.id, d.title, d.description, d.release_at, d.artist_id, ar.name as artist_name,
           case when d.cancelled_at is not null then 'cancelled' when d.release_at > now() then 'upcoming' else 'released' end as phase,
           case when d.release_at <= now() or d.owner_id = auth.uid() then (select w.thumb_path from artworks w where w.id = d.teaser_artwork) end as teaser_thumb,
           d.teaser_palette,
           (select count(*) from artworks w where w.drop_id = d.id)::int as works,
           exists (select 1 from drop_subscriptions s where s.drop_id = d.id and s.user_id = auth.uid()) as subscribed,
           d.owner_id = auth.uid() as mine,
           case when d.release_at > now() then 0 else 1 end as sort
    from drops d join artists ar on ar.id = d.artist_id
    where d.cancelled_at is null and (d.release_at > now() or d.release_at > now() - interval '14 days')
  ) x), '[]'::json);
end $$;

create or replace function public.drop_detail(p_id uuid) returns json
language plpgsql security definer set search_path = public as $$
begin
  perform release_due_drops();
  return (select json_build_object(
    'id', d.id, 'title', d.title, 'description', d.description, 'release_at', d.release_at,
    'artist_id', d.artist_id, 'artist_name', ar.name,
    'phase', case when d.cancelled_at is not null then 'cancelled' when d.release_at > now() then 'upcoming' else 'released' end,
    'teaser_thumb', case when d.release_at <= now() or d.owner_id = auth.uid() then (select w.thumb_path from artworks w where w.id = d.teaser_artwork) end,
    'teaser_palette', d.teaser_palette,
    'works', case when d.release_at <= now() or d.owner_id = auth.uid() or d.cancelled_at is not null
                  then coalesce((select json_agg(w.id order by w.created_at) from artworks w where w.drop_id = d.id and not w.hidden), '[]'::json)
                  else '[]'::json end,
    'work_count', (select count(*) from artworks w where w.drop_id = d.id),
    'subscribed', exists (select 1 from drop_subscriptions s where s.drop_id = d.id and s.user_id = auth.uid()),
    'mine', d.owner_id = auth.uid())
  from drops d join artists ar on ar.id = d.artist_id where d.id = p_id);
end $$;

-- ——— 2. Plan badges ———
alter table public.profiles add column if not exists show_plan_badge boolean not null default true;

create or replace function public.set_plan_badge(p_show boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  update profiles set show_plan_badge = coalesce(p_show, true) where id = auth.uid();
end $$;

create or replace function public.plan_badges() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_object_agg(ar.id, (current_plan(ar.owner_id)).badge), '{}'::json)
  from artists ar
  join subscriptions s on s.user_id = ar.owner_id
  join profiles p on p.id = ar.owner_id
  where (current_plan(ar.owner_id)).badge is not null and p.show_plan_badge
$$;

create or replace function public.my_plan() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'plan', row_to_json(p),
    'status', s.status, 'source', s.source, 'ends_at', s.current_period_end,
    'manage', s.source = 'billing' and s.billing_customer is not null,
    'show_badge', (select show_plan_badge from profiles where id = auth.uid()))
  from current_plan(auth.uid()) p
  left join subscriptions s on s.user_id = auth.uid() and s.plan = p.code
  where auth.uid() is not null
$$;

-- ——— Grants ———
do $$
declare f text;
begin
  foreach f in array array['create_drop(text, text, timestamptz, text[], text, text)', 'set_plan_badge(boolean)', 'my_plan()'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['drops_overview()', 'drop_detail(uuid)', 'plan_badges()'] loop
    execute format('revoke all on function public.%s from public', f);
    execute format('grant execute on function public.%s to anon, authenticated', f);
  end loop;
end $$;

-- ═════ 0015_discovery_loop.sql ═════
-- Abremi Phase 8: the discovery-to-ownership loop.
--
--   1. Offers: a purchase inquiry can carry an offer (amount and currency). Same rules as every
--      inquiry (accounts 3+ days old, daily limits, blocks, never sample artists, never your own
--      work, only works that are available or on request). Nothing is charged: the artist replies.
--   2. Waitlist: "Notify me" for works that aren't available. Private to the member.
--   3. Alerts: when a work becomes available or changes price, everyone who treasured it or joined
--      its waitlist is told once; when an artist announces a drop, members who treasured their work
--      (and don't already follow them) are told too.
--   4. Collector interests: mediums, regions and a price limit, used for the member's own Discover
--      deck and the Guide. Private; never used for rankings.

-- ——— 1. Offers ———
alter table public.inquiries add column if not exists offer_amount numeric(12, 2) check (offer_amount is null or offer_amount > 0);
alter table public.inquiries add column if not exists offer_currency text check (offer_currency is null or offer_currency ~ '^[A-Z]{3}$');

create or replace function public.send_offer(p_artwork text, p_amount numeric, p_currency text, p_message text) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  cur text := upper(btrim(coalesce(p_currency, 'USD')));
  q uuid;
  w public.artworks;
begin
  if p_amount is null or p_amount <= 0 or p_amount > 10000000 then
    raise exception 'Enter an offer between 1 and 10,000,000' using errcode = '22023';
  end if;
  if cur !~ '^[A-Z]{3}$' then
    raise exception 'Use a three-letter currency code, like USD' using errcode = '22023';
  end if;
  select * into w from artworks where id = p_artwork;
  -- send_inquiry applies every inquiry rule (and checks the work is available or on request).
  q := send_inquiry(p_artwork, null, 'purchase', p_message);
  update inquiries set offer_amount = round(p_amount, 2), offer_currency = cur where id = q;
  update notifications set title = (select name from profiles where id = auth.uid()) || ' made an offer of ' || cur || ' '
                                   || to_char(round(p_amount, 2), 'FM999,999,990.00') || ' for “' || w.title || '”'
   where link = 'inquiry/' || q and kind = 'inquiry';
  return q;
end $$;

-- The inquiry lists show the offer.
create or replace function public.inquiry_offer(p_id uuid) returns json
language sql stable security definer set search_path = public as $$
  select json_build_object('amount', offer_amount, 'currency', offer_currency)
  from inquiries where id = p_id and offer_amount is not null and auth.uid() in (artist_user, sender_id)
$$;

-- ——— 2. Waitlist ———
create table if not exists public.artwork_watches (
  user_id uuid not null references public.profiles (id) on delete cascade,
  artwork_id text not null references public.artworks (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, artwork_id)
);
alter table public.artwork_watches enable row level security;
drop policy if exists "read own watches" on public.artwork_watches;
create policy "read own watches" on public.artwork_watches for select using (user_id = auth.uid());
revoke all on public.artwork_watches from anon, authenticated;
grant select on public.artwork_watches to authenticated;

create or replace function public.watch_artwork(p_id text, p_on boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if p_on then
    if (select count(*) from artwork_watches where user_id = auth.uid()) >= 200 then
      raise exception 'You can follow 200 works at a time' using errcode = 'P0001';
    end if;
    insert into artwork_watches (user_id, artwork_id)
    select auth.uid(), id from artworks where id = p_id and owner_id is not null and owner_id <> auth.uid() and not hidden
    on conflict do nothing;
    if not found and not exists (select 1 from artwork_watches where user_id = auth.uid() and artwork_id = p_id) then
      raise exception 'You can’t follow this work' using errcode = '22023';
    end if;
  else
    delete from artwork_watches where user_id = auth.uid() and artwork_id = p_id;
  end if;
end $$;

create or replace function public.my_watches() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_agg(artwork_id order by created_at desc), '[]'::json) from artwork_watches where user_id = auth.uid()
$$;

-- ——— 3. Alerts ———
create or replace function public.alert_artwork_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  -- Read fields by name, so undoing older migrations (which drop columns) never breaks updates.
  n jsonb := to_jsonb(new);
  o jsonb := to_jsonb(old);
  became_available boolean := coalesce(n->>'availability', 'available') in ('available', 'on_request')
                              and coalesce(o->>'availability', 'available') not in ('available', 'on_request');
  new_price boolean := (n->>'price') is distinct from (o->>'price') and coalesce(n->>'availability', 'available') in ('available', 'on_request');
begin
  if new.owner_id is null or coalesce((n->>'hidden')::boolean, false) or coalesce((n->>'release_at')::timestamptz > now(), false)
     or not (became_available or new_price) then
    return new;
  end if;
  insert into notifications (user_id, kind, title, link)
  select distinct u, 'artwork_alert',
         case when became_available then '“' || new.title || '” is now available' else '“' || new.title || '” has a new price' end,
         'art/' || new.id
  from (select user_id as u from reactions where artwork_id = new.id and kind = 'super'
        union select user_id from artwork_watches where artwork_id = new.id) x
  where u <> new.owner_id;
  return new;
end $$;
revoke all on function public.alert_artwork_change() from public, anon, authenticated;
drop trigger if exists abremi_alert_artwork_change on public.artworks;
-- No column list, so older migrations can still be undone; the function checks what changed.
create trigger abremi_alert_artwork_change after update on public.artworks
  for each row execute function public.alert_artwork_change();

create or replace function public.alert_drop_to_treasurers() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into notifications (user_id, kind, title, link)
  select distinct r.user_id, 'drop_announced',
         (select name from artists where id = new.artist_id) || ', whose work you treasured, announced a drop: “' || new.title || '”',
         'drop/' || new.id
  from reactions r join artworks w on w.id = r.artwork_id
  where w.artist_id = new.artist_id and r.kind = 'super' and r.user_id <> new.owner_id
    and not exists (select 1 from follows f where f.user_id = r.user_id and f.artist_id = new.artist_id);
  return new;
end $$;
revoke all on function public.alert_drop_to_treasurers() from public, anon, authenticated;
drop trigger if exists abremi_alert_drop_to_treasurers on public.drops;
create trigger abremi_alert_drop_to_treasurers after insert on public.drops
  for each row execute function public.alert_drop_to_treasurers();

-- ——— 4. Collector interests ———
alter table public.profiles add column if not exists discovery_interests jsonb not null default '{}'::jsonb
  check (jsonb_typeof(discovery_interests) = 'object' and pg_column_size(discovery_interests) < 2000);

create or replace function public.set_discovery_interests(p_mediums text[], p_regions text[], p_price_max integer) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if coalesce(cardinality(p_mediums), 0) > 9 or coalesce(cardinality(p_regions), 0) > 12 then
    raise exception 'Choose fewer interests' using errcode = '22023';
  end if;
  if p_price_max is not null and p_price_max not between 1 and 10000000 then
    raise exception 'Choose a price limit between 1 and 10,000,000' using errcode = '22023';
  end if;
  update profiles set discovery_interests = jsonb_build_object(
      'mediums', coalesce((select jsonb_agg(m) from unnest(p_mediums) m where m ~ '^[a-z]{2,20}$'), '[]'::jsonb),
      'regions', coalesce((select jsonb_agg(r) from unnest(p_regions) r where r ~ '^[A-Z]{2}$'), '[]'::jsonb),
      'price_max', p_price_max,
      'updated_at', now())
   where id = auth.uid();
end $$;

-- The member's own interests (and whether they allow personalization, for the Guide).
create or replace function public.my_discovery_interests() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object('interests', discovery_interests, 'personalize', assistant_personalize) from profiles where id = auth.uid()
$$;

-- ——— Grants ———
do $$
declare f text;
begin
  foreach f in array array['send_offer(text, numeric, text, text)', 'inquiry_offer(uuid)', 'watch_artwork(text, boolean)', 'my_watches()',
                           'set_discovery_interests(text[], text[], integer)', 'my_discovery_interests()'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- ═════ 0016_index.sql ═════
-- The Abremi Index: a weekly public chart of real member artists and works.
--
-- Each Monday the past 7 days are frozen into a citable chart: overall, per medium and per artist
-- country. A work's score is its admirations (+1 × role weight) and treasures (+2 × role weight)
-- from that week, counted the same way as the rankings (your own activity and excluded bursts never
-- count). An artist's score is the sum of their works' scores. Sample works and artists are never
-- included, and plans are never read (tests/db.test.js checks this).

create table if not exists public.index_weeks (
  week date primary key,                 -- the Monday the week ended (the chart covers the 7 days before)
  published_at timestamptz not null default now()
);
create table if not exists public.index_entries (
  week date not null references public.index_weeks (week) on delete cascade,
  chart text not null check (chart ~ '^(overall|medium:[a-z]{2,20}|country:[A-Z]{2})$'),
  kind text not null check (kind in ('artwork', 'artist')),
  rank integer not null check (rank between 1 and 100),
  target text not null,
  score integer not null,
  primary key (week, chart, kind, rank)
);
create index if not exists index_entries_target_idx on public.index_entries (target, week);
alter table public.index_weeks enable row level security;
alter table public.index_entries enable row level security;
drop policy if exists "the index is public" on public.index_weeks;
create policy "the index is public" on public.index_weeks for select using (true);
drop policy if exists "the index is public" on public.index_entries;
create policy "the index is public" on public.index_entries for select using (true);
revoke all on public.index_weeks, public.index_entries from anon, authenticated;
grant select on public.index_weeks, public.index_entries to anon, authenticated;

-- Freezes the chart for the week ending on p_week (a Monday). Safe to run again: it replaces it.
create or replace function public.compute_index(p_week date) returns integer
language plpgsql security definer set search_path = public as $$
declare
  t_to timestamptz := p_week::timestamptz;
  t_from timestamptz := p_week::timestamptz - interval '7 days';
  n integer;
begin
  delete from index_weeks where week = p_week;
  insert into index_weeks (week) values (p_week);
  create temporary table if not exists _index_works (artwork_id text, artist_id text, category text, country text, score integer) on commit drop;
  truncate _index_works;
  insert into _index_works
  select w.id, w.artist_id, w.category, ar.country,
         sum(case r.kind when 'like' then role_weight(r.role) when 'super' then 2 * role_weight(r.role) else 0 end)::int
  from counted_reactions r
  join artworks w on w.id = r.artwork_id
  join artists ar on ar.id = w.artist_id
  where r.kind in ('like', 'super') and r.created_at >= t_from and r.created_at < t_to
    and w.owner_id is not null and ar.owner_id is not null and not w.hidden and (w.release_at is null or w.release_at <= t_to)
  group by w.id, w.artist_id, w.category, ar.country
  having sum(case r.kind when 'like' then role_weight(r.role) when 'super' then 2 * role_weight(r.role) else 0 end) > 0;

  -- Works: overall, by medium, by artist country. Ties broken by id, so the chart is stable.
  insert into index_entries (week, chart, kind, rank, target, score)
  select p_week, chart, 'artwork', rk, artwork_id, score from (
    select c.chart, x.artwork_id, x.score, row_number() over (partition by c.chart order by x.score desc, x.artwork_id) as rk
    from _index_works x
    cross join lateral (values ('overall'), ('medium:' || x.category), ('country:' || x.country)) c(chart)
    where c.chart ~ '^(overall|medium:[a-z]{2,20}|country:[A-Z]{2})$'
  ) s where rk <= 100;
  -- Artists: the sum of their works' scores.
  insert into index_entries (week, chart, kind, rank, target, score)
  select p_week, chart, 'artist', rk, artist_id, score from (
    select c.chart, a.artist_id, a.score, row_number() over (partition by c.chart order by a.score desc, a.artist_id) as rk
    from (select artist_id, country, sum(score)::int as score, (array_agg(category order by score desc))[1] as category
          from _index_works group by artist_id, country) a
    cross join lateral (values ('overall'), ('medium:' || a.category), ('country:' || a.country)) c(chart)
    where c.chart ~ '^(overall|medium:[a-z]{2,20}|country:[A-Z]{2})$'
  ) s where rk <= 100;
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function public.compute_index(date) from public, anon, authenticated;

-- One week's chart (the latest by default), with the list of weeks and charts available.
create or replace function public.index_week(p_week date default null, p_chart text default 'overall') returns json
language sql stable security definer set search_path = public as $$
  with wk as (select coalesce(p_week, (select max(week) from index_weeks)) as week)
  select json_build_object(
    'week', (select week from wk),
    'covers_from', (select week - 7 from wk),
    'chart', p_chart,
    'weeks', coalesce((select json_agg(week order by week desc) from (select week from index_weeks order by week desc limit 52) w), '[]'::json),
    'charts', coalesce((select json_agg(distinct chart) from index_entries where week = (select week from wk)), '[]'::json),
    'artworks', coalesce((select json_agg(json_build_object('rank', e.rank, 'id', e.target, 'title', w.title, 'artist_id', w.artist_id, 'artist', ar.name, 'score', e.score) order by e.rank)
                          from index_entries e join artworks w on w.id = e.target join artists ar on ar.id = w.artist_id
                          where e.week = (select week from wk) and e.chart = p_chart and e.kind = 'artwork' and not w.hidden), '[]'::json),
    'artists', coalesce((select json_agg(json_build_object('rank', e.rank, 'id', e.target, 'name', ar.name, 'country', ar.country, 'score', e.score) order by e.rank)
                         from index_entries e join artists ar on ar.id = e.target
                         where e.week = (select week from wk) and e.chart = p_chart and e.kind = 'artist'), '[]'::json))
$$;

-- An artist's best place in the latest Index (for the badge), or null.
create or replace function public.artist_index_badge(p_artist text) returns json
language sql stable security definer set search_path = public as $$
  select json_build_object('week', e.week, 'covers_from', e.week - 7, 'chart', e.chart, 'rank', e.rank, 'name', ar.name)
  from index_entries e join artists ar on ar.id = e.target
  where e.kind = 'artist' and e.target = p_artist and e.week = (select max(week) from index_weeks)
  order by e.rank, case when e.chart = 'overall' then 0 when e.chart like 'medium:%' then 1 else 2 end
  limit 1
$$;

-- Moderators can publish the current week early (for the first Index, or after fixing a burst).
create or replace function public.admin_publish_index() returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  n := compute_index(date_trunc('week', now())::date);
  perform log_audit('index.published', 'index', date_trunc('week', now())::date::text, jsonb_build_object('entries', n));
  return n;
end $$;

do $$
declare f text;
begin
  foreach f in array array['index_week(date, text)', 'artist_index_badge(text)'] loop
    execute format('revoke all on function public.%s from public', f);
    execute format('grant execute on function public.%s to anon, authenticated', f);
  end loop;
  revoke all on function public.admin_publish_index() from public, anon;
  grant execute on function public.admin_publish_index() to authenticated;
end $$;

-- Every Monday at 00:17 UTC; and once now, so the first Index exists.
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('abremi-weekly-index', '17 0 * * 1', 'select public.compute_index(date_trunc(''week'', now())::date);');
  end if;
exception when others then
  raise notice 'Schedule not set up (%). The weekly Index needs pg_cron, or a moderator can publish it.', sqlerrm;
end $$;
select public.compute_index(date_trunc('week', now())::date);

-- ═════ 0017_checkout.sql ═════
-- Abremi: real checkout (switched off until reviewed), the commission model and editions.
--
--   * Buyers pay through Stripe Checkout; artists are paid by Stripe Connect Express (Stripe verifies
--     them, holds the funds and pays them out). Abremi keeps a 20% commission and never holds
--     artists' money. Taxes are not calculated here (handled with the owner's accountant).
--   * The database decides what can be bought (orders are created by begin_purchase(), as the
--     buyer); only the signed Stripe webhook, with the service role, can mark an order paid.
--   * Editions: prints made and shipped by the artist, one numbered print per order.
--   * After payment: the artist ships with tracking, the buyer confirms delivery, and within 14 days
--     of delivery the buyer can report a problem; moderators decide (refunds are made in Stripe).
--   * Verified sales appear on the Artist Passport.
-- Switched on only when app_settings.sales_enabled is true AND SALES_ENABLED=true in Vercel.

alter table public.app_settings add column if not exists sales_enabled boolean not null default false;
create or replace function public.app_flags() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object('invite_required', invite_required, 'payments_enabled', payments_enabled, 'sales_enabled', sales_enabled) from app_settings
$$;

-- ——— Editions ———
alter table public.artworks add column if not exists edition_size integer check (edition_size is null or edition_size between 2 and 500);
alter table public.artworks add column if not exists editions_sold integer not null default 0 check (editions_sold >= 0);

create or replace function public.set_edition(p_artwork text, p_size integer) returns void
language plpgsql security definer set search_path = public as $$
declare w public.artworks;
begin
  select * into w from artworks where id = p_artwork and owner_id = auth.uid();
  if w.id is null then
    raise exception 'Not your artwork' using errcode = '42501';
  end if;
  if p_size is not null and (p_size not between 2 and 500 or p_size < w.editions_sold) then
    raise exception 'An edition has 2 to 500 prints, and no fewer than already sold' using errcode = '22023';
  end if;
  if p_size is null and w.editions_sold > 0 then
    raise exception 'Prints of this edition have been sold' using errcode = '22023';
  end if;
  update artworks set edition_size = p_size where id = w.id;
end $$;

-- ——— Payout accounts (Stripe Connect Express) ———
create table if not exists public.payout_accounts (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  stripe_account text not null unique check (stripe_account ~ '^acct_[A-Za-z0-9]+$'),
  charges_enabled boolean not null default false,
  payouts_enabled boolean not null default false,
  details_submitted boolean not null default false,
  updated_at timestamptz not null default now()
);
alter table public.payout_accounts enable row level security;
drop policy if exists "read own payout account" on public.payout_accounts;
create policy "read own payout account" on public.payout_accounts for select using (user_id = auth.uid());
revoke all on public.payout_accounts from anon, authenticated;

create or replace function public.my_payout_status() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object('connected', p.user_id is not null, 'charges_enabled', coalesce(p.charges_enabled, false),
                           'payouts_enabled', coalesce(p.payouts_enabled, false), 'details_submitted', coalesce(p.details_submitted, false))
  from (select auth.uid() as uid) me left join payout_accounts p on p.user_id = me.uid
  where auth.uid() is not null
$$;

-- Artists who can be paid (public: just ids, so the app can show "Buy").
create or replace function public.artists_accepting_payments() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_agg(ar.id), '[]'::json) from artists ar join payout_accounts p on p.user_id = ar.owner_id
  where p.charges_enabled and (select sales_enabled from app_settings)
$$;

-- Service role only: the server function records the account and its status.
create or replace function public.set_payout_account(p_user uuid, p_account text, p_charges boolean, p_payouts boolean, p_details boolean) returns void
language sql security definer set search_path = public as $$
  insert into payout_accounts (user_id, stripe_account, charges_enabled, payouts_enabled, details_submitted, updated_at)
  values (p_user, p_account, coalesce(p_charges, false), coalesce(p_payouts, false), coalesce(p_details, false), now())
  on conflict (user_id) do update set stripe_account = excluded.stripe_account, charges_enabled = excluded.charges_enabled,
    payouts_enabled = excluded.payouts_enabled, details_submitted = excluded.details_submitted, updated_at = now()
$$;
create or replace function public.update_payout_status(p_account text, p_charges boolean, p_payouts boolean, p_details boolean) returns void
language sql security definer set search_path = public as $$
  update payout_accounts set charges_enabled = coalesce(p_charges, false), payouts_enabled = coalesce(p_payouts, false),
    details_submitted = coalesce(p_details, false), updated_at = now() where stripe_account = p_account
$$;
create or replace function public.payout_account_for(p_user uuid) returns text
language sql stable security definer set search_path = public as $$
  select stripe_account from payout_accounts where user_id = p_user
$$;

-- ——— Orders ———
create table if not exists public.orders (
  id uuid primary key default gen_random_uuid(),
  artwork_id text references public.artworks (id) on delete set null,
  title text not null,
  artist_id text not null references public.artists (id) on delete cascade,
  artist_user uuid not null references public.profiles (id) on delete cascade,
  buyer_id uuid not null references public.profiles (id) on delete cascade,
  amount_cents integer not null check (amount_cents > 0),
  fee_cents integer not null check (fee_cents >= 0),
  currency text not null default 'usd' check (currency ~ '^[a-z]{3}$'),
  edition_number integer,
  status text not null default 'pending' check (status in ('pending', 'paid', 'shipped', 'delivered', 'disputed', 'refunded', 'cancelled')),
  checkout_session text unique,
  payment_intent text,
  shipping jsonb,
  carrier text check (char_length(coalesce(carrier, '')) <= 60),
  tracking text check (char_length(coalesce(tracking, '')) <= 100),
  dispute_reason text check (char_length(coalesce(dispute_reason, '')) <= 1000),
  dispute_resolution text check (char_length(coalesce(dispute_resolution, '')) <= 1000),
  created_at timestamptz not null default now(),
  paid_at timestamptz, shipped_at timestamptz, delivered_at timestamptz, updated_at timestamptz not null default now(),
  check (artist_user <> buyer_id)
);
create index if not exists orders_buyer_idx on public.orders (buyer_id, created_at desc);
create index if not exists orders_artist_idx on public.orders (artist_user, created_at desc);
alter table public.orders enable row level security;
drop policy if exists "the two people read an order" on public.orders;
create policy "the two people read an order" on public.orders for select using (auth.uid() in (buyer_id, artist_user));
revoke all on public.orders from anon, authenticated;
grant select on public.orders to authenticated;

-- Starts a purchase as the buyer: the database checks everything and creates a pending order.
create or replace function public.begin_purchase(p_artwork text) returns json
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  w public.artworks;
  ar public.artists;
  o public.orders;
  open_orders integer;
begin
  if not (select sales_enabled from app_settings) then
    raise exception 'Buying isn’t switched on yet' using errcode = '42501';
  end if;
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if (select created_at from profiles where id = uid) > now() - interval '3 days' then
    raise exception 'New accounts can buy after 3 days' using errcode = '42501';
  end if;
  update orders set status = 'cancelled', updated_at = now() where status = 'pending' and created_at < now() - interval '1 hour';
  select * into w from artworks where id = p_artwork;
  if w.id is null or w.hidden or (w.release_at is not null and w.release_at > now()) or w.owner_id is null then
    raise exception 'Artwork not found' using errcode = 'P0002';
  end if;
  if w.owner_id = uid then
    raise exception 'That’s your own work' using errcode = '22023';
  end if;
  if coalesce(w.availability, 'available') <> 'available' or coalesce(w.price, 0) <= 0 then
    raise exception 'This work isn’t for sale at a listed price' using errcode = '22023';
  end if;
  select * into ar from artists where id = w.artist_id;
  if not exists (select 1 from payout_accounts p where p.user_id = w.owner_id and p.charges_enabled) then
    raise exception 'This artist can’t take payments yet. Ask them about it instead.' using errcode = '22023';
  end if;
  if is_blocked_between(uid, w.owner_id) then
    raise exception 'You can’t buy from this member' using errcode = '42501';
  end if;
  if (select count(*) from orders where buyer_id = uid and status = 'pending') >= 5 then
    raise exception 'Finish or cancel your other checkouts first' using errcode = 'P0001';
  end if;
  select count(*) into open_orders from orders where artwork_id = w.id and status in ('pending', 'paid', 'shipped', 'delivered', 'disputed');
  if w.edition_size is null and open_orders > 0 then
    raise exception 'Someone is already buying this work' using errcode = 'P0001';
  end if;
  if w.edition_size is not null and open_orders >= w.edition_size then
    raise exception 'This edition is sold out' using errcode = 'P0001';
  end if;
  insert into orders (artwork_id, title, artist_id, artist_user, buyer_id, amount_cents, fee_cents)
  values (w.id, w.title || case when w.edition_size is not null then ' (print, edition of ' || w.edition_size || ')' else '' end,
          ar.id, w.owner_id, uid, w.price * 100, round(w.price * 100 * 0.20))
  returning * into o;
  return json_build_object('order_id', o.id, 'title', o.title, 'amount_cents', o.amount_cents, 'fee_cents', o.fee_cents, 'currency', o.currency);
end $$;

-- Service role only: where the money goes, and recording the Checkout session.
create or replace function public.order_payout_target(p_order uuid) returns text
language sql stable security definer set search_path = public as $$
  select p.stripe_account from orders o join payout_accounts p on p.user_id = o.artist_user where o.id = p_order and o.status = 'pending' and p.charges_enabled
$$;
create or replace function public.attach_checkout_session(p_order uuid, p_session text) returns void
language sql security definer set search_path = public as $$
  update orders set checkout_session = p_session, updated_at = now() where id = p_order and status = 'pending'
$$;

-- Service role only (the signed webhook): the payment succeeded. Applied once; the amount must match.
create or replace function public.complete_order(p_session text, p_payment_intent text, p_amount integer, p_shipping jsonb) returns text
language plpgsql security definer set search_path = public as $$
declare o public.orders; w public.artworks; n integer;
begin
  select * into o from orders where checkout_session = p_session for update;
  if o.id is null then return 'unknown session'; end if;
  if o.status <> 'pending' then return 'already ' || o.status; end if;
  if p_amount is distinct from o.amount_cents then
    raise exception 'Amount mismatch for order %', o.id using errcode = '22023';
  end if;
  select * into w from artworks where id = o.artwork_id for update;
  if w.edition_size is not null then
    n := w.editions_sold + 1;
    update artworks set editions_sold = n, availability = case when n >= w.edition_size then 'sold' else availability end where id = w.id;
  elsif w.id is not null then
    update artworks set availability = 'sold' where id = w.id;
  end if;
  update orders set status = 'paid', payment_intent = p_payment_intent, shipping = p_shipping, edition_number = n, paid_at = now(), updated_at = now()
   where id = o.id;
  insert into notifications (user_id, kind, title, link) values
    (o.artist_user, 'sale', 'You sold “' || o.title || '”. Ship it and add tracking in Orders.', 'orders'),
    (o.buyer_id, 'purchase', 'Your purchase of “' || o.title || '” is confirmed. The artist will ship it.', 'orders');
  return 'paid';
end $$;

create or replace function public.refund_order(p_payment_intent text) returns text
language plpgsql security definer set search_path = public as $$
declare o public.orders;
begin
  update orders set status = 'refunded', updated_at = now() where payment_intent = p_payment_intent and status <> 'refunded' returning * into o;
  if o.id is null then return 'unknown or already refunded'; end if;
  insert into notifications (user_id, kind, title, link) values
    (o.buyer_id, 'purchase', '“' || o.title || '” was refunded.', 'orders'), (o.artist_user, 'sale', '“' || o.title || '” was refunded to the buyer.', 'orders');
  return 'refunded';
end $$;

-- Both people's orders. Shipping addresses are shown to the artist (to ship) and the buyer only.
create or replace function public.my_orders() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'sales', coalesce((select json_agg(json_build_object('id', o.id, 'artwork_id', o.artwork_id, 'title', o.title, 'amount_cents', o.amount_cents, 'fee_cents', o.fee_cents,
              'currency', o.currency, 'edition_number', o.edition_number, 'status', o.status, 'shipping', o.shipping, 'carrier', o.carrier, 'tracking', o.tracking,
              'buyer', (select name from profiles where id = o.buyer_id), 'paid_at', o.paid_at, 'shipped_at', o.shipped_at, 'delivered_at', o.delivered_at,
              'dispute_reason', o.dispute_reason, 'dispute_resolution', o.dispute_resolution) order by o.created_at desc)
              from orders o where o.artist_user = auth.uid() and o.status not in ('pending', 'cancelled')), '[]'::json),
    'purchases', coalesce((select json_agg(json_build_object('id', o.id, 'artwork_id', o.artwork_id, 'title', o.title, 'amount_cents', o.amount_cents,
              'currency', o.currency, 'edition_number', o.edition_number, 'status', o.status, 'carrier', o.carrier, 'tracking', o.tracking,
              'artist', (select name from artists where id = o.artist_id), 'paid_at', o.paid_at, 'shipped_at', o.shipped_at, 'delivered_at', o.delivered_at,
              'dispute_reason', o.dispute_reason, 'dispute_resolution', o.dispute_resolution,
              'can_dispute', o.status in ('paid', 'shipped') or (o.status = 'delivered' and o.delivered_at > now() - interval '14 days')) order by o.created_at desc)
              from orders o where o.buyer_id = auth.uid() and o.status not in ('pending', 'cancelled')), '[]'::json))
  where auth.uid() is not null
$$;

create or replace function public.mark_shipped(p_order uuid, p_carrier text, p_tracking text) returns void
language plpgsql security definer set search_path = public as $$
declare o public.orders;
begin
  if char_length(btrim(coalesce(p_carrier, ''))) < 2 or char_length(btrim(coalesce(p_tracking, ''))) < 4 then
    raise exception 'Add the carrier and tracking number' using errcode = '22023';
  end if;
  update orders set status = 'shipped', carrier = btrim(p_carrier), tracking = btrim(p_tracking), shipped_at = now(), updated_at = now()
   where id = p_order and artist_user = auth.uid() and status = 'paid' returning * into o;
  if o.id is null then raise exception 'That order can’t be marked shipped' using errcode = 'P0001'; end if;
  insert into notifications (user_id, kind, title, link) values (o.buyer_id, 'purchase', '“' || o.title || '” has shipped (' || o.carrier || ' ' || o.tracking || ')', 'orders');
end $$;

create or replace function public.confirm_delivery(p_order uuid) returns void
language plpgsql security definer set search_path = public as $$
declare o public.orders;
begin
  update orders set status = 'delivered', delivered_at = now(), updated_at = now()
   where id = p_order and buyer_id = auth.uid() and status = 'shipped' returning * into o;
  if o.id is null then raise exception 'That order can’t be marked delivered' using errcode = 'P0001'; end if;
  insert into notifications (user_id, kind, title, link) values (o.artist_user, 'sale', 'The buyer received “' || o.title || '”', 'orders');
end $$;

-- The buyer reports a problem: before delivery, or within 14 days after it. Moderators decide.
create or replace function public.open_dispute(p_order uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare o public.orders;
begin
  if char_length(btrim(coalesce(p_reason, ''))) < 10 then
    raise exception 'Describe the problem (at least 10 characters)' using errcode = '22023';
  end if;
  update orders set status = 'disputed', dispute_reason = btrim(p_reason), updated_at = now()
   where id = p_order and buyer_id = auth.uid()
     and (status in ('paid', 'shipped') or (status = 'delivered' and delivered_at > now() - interval '14 days'))
  returning * into o;
  if o.id is null then raise exception 'Problems can be reported until 14 days after delivery' using errcode = 'P0001'; end if;
  insert into notifications (user_id, kind, title, link) values (o.artist_user, 'sale', 'The buyer reported a problem with “' || o.title || '”. A moderator will look at it.', 'orders');
  insert into notifications (user_id, kind, title, link) select user_id, 'dispute', 'A buyer reported a problem with an order', 'admin' from admins;
end $$;

create or replace function public.admin_disputes() returns json
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin() then raise exception 'Admins only' using errcode = '42501'; end if;
  return coalesce((select json_agg(json_build_object('id', o.id, 'title', o.title, 'amount_cents', o.amount_cents, 'currency', o.currency,
            'artist', (select name from artists where id = o.artist_id), 'buyer', (select name from profiles where id = o.buyer_id),
            'reason', o.dispute_reason, 'paid_at', o.paid_at, 'shipped_at', o.shipped_at, 'delivered_at', o.delivered_at,
            'carrier', o.carrier, 'tracking', o.tracking, 'payment_intent', o.payment_intent) order by o.updated_at)
          from orders o where o.status = 'disputed'), '[]'::json);
end $$;

-- A moderator's decision. A refund itself is made in the Stripe dashboard (the webhook then records it).
create or replace function public.resolve_dispute(p_order uuid, p_refund boolean, p_note text) returns void
language plpgsql security definer set search_path = public as $$
declare o public.orders;
begin
  if not is_admin() then raise exception 'Admins only' using errcode = '42501'; end if;
  update orders set dispute_resolution = nullif(btrim(coalesce(p_note, '')), ''), updated_at = now(),
         status = case when p_refund then 'disputed' when delivered_at is not null then 'delivered' when shipped_at is not null then 'shipped' else 'paid' end
   where id = p_order and status = 'disputed' returning * into o;
  if o.id is null then raise exception 'That order isn’t disputed' using errcode = 'P0001'; end if;
  perform log_audit(case when p_refund then 'order.refund_approved' else 'order.dispute_declined' end, 'order', o.id::text, jsonb_build_object('note', p_note, 'title', o.title));
  insert into notifications (user_id, kind, title, link) values
    (o.buyer_id, 'purchase', case when p_refund then 'Your problem with “' || o.title || '” was upheld: a refund is on its way.' else 'A moderator reviewed your problem with “' || o.title || '”.' end
                             || coalesce(' ' || o.dispute_resolution, ''), 'orders'),
    (o.artist_user, 'sale', 'A moderator decided on the problem with “' || o.title || '”.' || coalesce(' ' || o.dispute_resolution, ''), 'orders');
end $$;

-- ——— Verified sales on the Passport ———
create or replace function public.artist_passport(p_artist text) returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'achievements', coalesce((select json_agg(json_build_object('label', d.label, 'criteria', d.criteria, 'at', m.awarded_at) order by m.awarded_at)
                              from member_achievements m join achievement_definitions d on d.code = m.code and d.audience = 'artist'
                              where m.user_id = ar.owner_id), '[]'::json),
    'competitions', coalesce((select json_agg(json_build_object('id', c.id, 'title', c.title, 'kind', c.kind, 'closed_at', c.closed_at,
                                               'place', (r->>'place')::int, 'votes', (r->>'votes')::int, 'artwork', r->>'artwork') order by c.closed_at desc)
                              from competitions c, jsonb_array_elements(c.results->'entries') r
                              join competition_entries e on e.id = (r->>'entry')::uuid
                              where e.user_id = ar.owner_id and c.closed_at is not null), '[]'::json),
    'exhibitions', coalesce((select json_agg(json_build_object('kind', e.kind, 'title', e.title, 'venue', e.venue, 'city', e.city, 'country', e.country,
                                              'start_date', e.start_date, 'end_date', e.end_date, 'link', e.link) order by e.start_date desc)
                             from exhibitions e where e.artist_id = ar.id and e.status = 'verified'), '[]'::json),
    'verified_sales', (select count(*) from orders o where o.artist_id = ar.id and o.status in ('paid', 'shipped', 'delivered')),
    'milestones', json_build_object(
      'joined', ar.created_at,
      'first_work', (select min(created_at) from artworks where artist_id = ar.id and (release_at is null or release_at <= now())),
      'first_drop', (select min(released_at) from drops where artist_id = ar.id),
      'first_inquiry', (select min(created_at) from inquiries where artist_id = ar.id),
      'first_sale', (select min(paid_at) from orders where artist_id = ar.id and status in ('paid', 'shipped', 'delivered')))
  )
  from artists ar where ar.id = p_artist and ar.owner_id is not null
$$;

-- ——— Grants ———
do $$
declare f text;
begin
  foreach f in array array['set_edition(text, integer)', 'my_payout_status()', 'begin_purchase(text)', 'my_orders()', 'mark_shipped(uuid, text, text)',
                           'confirm_delivery(uuid)', 'open_dispute(uuid, text)', 'admin_disputes()', 'resolve_dispute(uuid, boolean, text)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['set_payout_account(uuid, text, boolean, boolean, boolean)', 'update_payout_status(text, boolean, boolean, boolean)',
                           'payout_account_for(uuid)', 'order_payout_target(uuid)', 'attach_checkout_session(uuid, text)',
                           'complete_order(text, text, integer, jsonb)', 'refund_order(text)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to service_role', f);
  end loop;
  foreach f in array array['artists_accepting_payments()', 'app_flags()', 'artist_passport(text)'] loop
    execute format('revoke all on function public.%s from public', f);
    execute format('grant execute on function public.%s to anon, authenticated', f);
  end loop;
end $$;

-- ═════ 0018_seasons.sql ═════
-- 0018: Seasons, Leagues and Streaks.
--   Seasons: the member boards (Top Discoverers, Collectors, Critics) counted within one calendar
--   month (UTC). On the 1st, last month's top 10 of each board is frozen into season_results and
--   becomes a permanent achievement, e.g. "Top 10 Discoverer · November 2026".
--   Leagues: the same boards filtered by country (as before) and now by medium.
--   Streaks: a daily Art Battle streak (at least one vote a UTC day; one missed day a week is
--   forgiven), with achievements at 7, 30 and 100 days.
-- Same rules as before: members who opted out stay hidden, your own work never counts, and plans
-- are never read.

-- ——— 1. The boards for any window, country and medium ———
-- A season counts the reactions and reviews made within it. Discovery credit for a like made in the
-- season comes from the weight that arrived after it, up to the season's end, so a past season's
-- standings don't keep moving. Internal: only member_leaderboards() and close_season() call it.
create or replace function public.season_boards(p_from timestamptz, p_to timestamptz, p_country text, p_medium text)
returns table (board text, user_id uuid, name text, country text, score integer, detail integer, rnk bigint, pos bigint)
language sql stable security definer set search_path = public as $$
  with
  base as (
    select r.user_id, r.artwork_id, r.kind, r.role, r.created_at
    from counted_reactions r join artworks a on a.id = r.artwork_id
    where (p_medium is null or a.category = p_medium) and (p_to is null or r.created_at < p_to)
  ),
  inwin as (select * from base where p_from is null or created_at >= p_from),
  contrib as (
    select user_id, role,
           sum(case kind when 'like' then role_weight(role) when 'super' then 2 * role_weight(role) else 0 end)::int as pts
    from inwin group by 1, 2
  ),
  review_pts as (
    select v.user_id, sum(2 * v.rating)::int as pts, count(*)::int as n
    from counted_reviews v join artworks a on a.id = v.artwork_id
    where (p_medium is null or a.category = p_medium)
      and (p_from is null or v.created_at >= p_from) and (p_to is null or v.created_at < p_to)
    group by 1
  ),
  ordered as (
    select user_id, created_at, role_weight(role) as w,
           coalesce(sum(role_weight(role)) over (partition by artwork_id order by created_at, user_id
             rows between unbounded preceding and 1 preceding), 0) as before_w,
           sum(role_weight(role)) over (partition by artwork_id) as total_w
    from base where kind in ('like', 'super')
  ),
  discovery as (
    select user_id, count(*)::int as n, sum(ln(1 + (total_w - before_w - w)) / (1 + before_w)) as raw
    from ordered where p_from is null or created_at >= p_from group by 1
  ),
  eligible as (
    select p.id, p.name, p.country, p.role
    from profiles p
    where (p.public_leaderboards or p.id = auth.uid())
      and (p_country is null or p.country = p_country)
  ),
  boards as (
    select 'collectors' as board, e.id, e.name, e.country, c.pts as score, c.pts as detail
    from eligible e join contrib c on c.user_id = e.id and c.role = 'collector'
    where e.role = 'collector' and c.pts > 0
    union all
    select 'critics', e.id, e.name, e.country,
           coalesce(c.pts, 0) + coalesce(rp.pts, 0), coalesce(rp.n, 0)
    from eligible e
    left join contrib c on c.user_id = e.id and c.role = 'critic'
    left join review_pts rp on rp.user_id = e.id
    where e.role = 'critic' and coalesce(c.pts, 0) + coalesce(rp.pts, 0) > 0
    union all
    select 'discoverers', e.id, e.name, e.country, round(100 * (1 - exp(-d.raw / 8)))::int, d.n
    from eligible e join discovery d on d.user_id = e.id
    where d.n >= 3
  )
  select b.board, b.id, b.name, b.country, b.score, b.detail,
         rank() over (partition by b.board order by b.score desc),
         row_number() over (partition by b.board order by b.score desc, b.name)
  from boards b
$$;
revoke all on function public.season_boards(timestamptz, timestamptz, text, text) from public, anon, authenticated;

-- ——— 2. member_leaderboards() gains a season (any day in the month) and a medium ———
drop function if exists public.member_leaderboards(text, integer);
create or replace function public.member_leaderboards(p_country text default null, p_limit integer default 50,
                                                      p_season date default null, p_medium text default null)
returns json
language sql stable security definer set search_path = public as $$
  with
  win as (
    select case when p_season is null then null else date_trunc('month', p_season::timestamp) at time zone 'utc' end as f
  ),
  ranked as (
    select s.* from win, season_boards(win.f, win.f + interval '1 month', p_country, nullif(p_medium, '')) s
  ),
  lim as (select greatest(1, least(coalesce(p_limit, 50), 100)) as n)
  select json_build_object(
    'collectors', coalesce((select json_agg(json_build_object('rank', rnk, 'name', name, 'country', country, 'score', score, 'detail', detail, 'me', coalesce(user_id = auth.uid(), false)) order by pos)
                            from ranked, lim where board = 'collectors' and rnk <= lim.n), '[]'::json),
    'critics', coalesce((select json_agg(json_build_object('rank', rnk, 'name', name, 'country', country, 'score', score, 'detail', detail, 'me', coalesce(user_id = auth.uid(), false)) order by pos)
                         from ranked, lim where board = 'critics' and rnk <= lim.n), '[]'::json),
    'discoverers', coalesce((select json_agg(json_build_object('rank', rnk, 'name', name, 'country', country, 'score', score, 'detail', detail, 'me', coalesce(user_id = auth.uid(), false)) order by pos)
                             from ranked, lim where board = 'discoverers' and rnk <= lim.n), '[]'::json),
    'me', coalesce((select json_object_agg(board, json_build_object('rank', rnk, 'score', score, 'detail', detail))
                    from ranked where user_id = auth.uid()), '{}'::json),
    'members', (select count(*)::int from profiles where public_leaderboards)
  )
$$;
revoke all on function public.member_leaderboards(text, integer, date, text) from public;
grant execute on function public.member_leaderboards(text, integer, date, text) to anon, authenticated;

-- ——— 3. Season archive: last month's top 10, frozen once, as permanent achievements ———
create table if not exists public.season_results (
  season date not null,
  board text not null check (board in ('discoverers', 'collectors', 'critics')),
  user_id uuid not null references public.profiles (id) on delete cascade,
  rank integer not null,
  score integer not null,
  frozen_at timestamptz not null default now(),
  primary key (season, board, user_id)
);
alter table public.season_results enable row level security;
drop policy if exists "read own season results" on public.season_results;
create policy "read own season results" on public.season_results for select using (user_id = auth.uid());
revoke all on public.season_results from anon, authenticated;
grant select on public.season_results to authenticated;

-- Freezes a finished month (worldwide, all media, public members only). Runs once per season;
-- calling it again changes nothing. Returns how many places were awarded.
create or replace function public.close_season(p_season date) returns integer
language plpgsql security definer set search_path = public as $$
declare
  m date := date_trunc('month', p_season)::date;
  f timestamptz := m::timestamp at time zone 'utc';
  month_name text := to_char(m, 'FMMonth YYYY');
  n integer;
begin
  if m >= date_trunc('month', now() at time zone 'utc')::date then
    raise exception 'That season hasn’t finished yet';
  end if;
  if exists (select 1 from season_results where season = m) then return 0; end if;
  insert into season_results (season, board, user_id, rank, score)
  select m, s.board, s.user_id, s.rnk, s.score
  from season_boards(f, f + interval '1 month', null, null) s
  join profiles p on p.id = s.user_id and p.public_leaderboards
  where s.rnk <= 10;
  get diagnostics n = row_count;
  insert into achievement_definitions (code, audience, label, criteria, sort)
  select 'season_' || to_char(m, 'YYYY_MM') || '_' || b.board, 'member',
         'Top 10 ' || b.title || ' · ' || month_name,
         'Finished in the top 10 ' || b.title || 's of ' || month_name || '.',
         1000 + b.ord
  from (values ('discoverers', 'Discoverer', 1), ('collectors', 'Collector', 2), ('critics', 'Critic', 3)) b(board, title, ord)
  where exists (select 1 from season_results r where r.season = m and r.board = b.board)
  on conflict (code) do nothing;
  insert into member_achievements (user_id, code, evidence)
  select r.user_id, 'season_' || to_char(m, 'YYYY_MM') || '_' || r.board,
         jsonb_build_object('season', m, 'board', r.board, 'rank', r.rank, 'score', r.score)
  from season_results r where r.season = m
  on conflict (user_id, code) do nothing;
  insert into notifications (user_id, kind, title, link)
  select r.user_id, 'season',
         'You finished No. ' || r.rank || ' among Top ' || initcap(r.board) || ' in ' || month_name, '#profile'
  from season_results r where r.season = m;
  return n;
end $$;
revoke all on function public.close_season(date) from public, anon, authenticated;

-- ——— 4. Art Battle streaks ———
-- At least one vote a UTC day keeps the streak; a single missed day is forgiven once every 7 days
-- (two missed days in a row, or a second miss within the week, end it). Today still counts as open.
-- Same rules as src/core/streak.js. Internal.
create or replace function public.battle_streak(p_user uuid) returns json
language plpgsql stable security definer set search_path = public as $$
declare
  today date := (now() at time zone 'utc')::date;
  days date[];
  d date;
  run integer := 0;
  best integer := 0;
  forgiven date;
begin
  days := array(select distinct (created_at at time zone 'utc')::date from battle_votes where user_id = p_user order by 1);
  if cardinality(days) = 0 then
    return json_build_object('current', 0, 'best', 0, 'today', false, 'grace_used', false);
  end if;
  for d in select g::date from generate_series(days[1], today, interval '1 day') g loop
    if d = any(days) then
      run := run + 1;
      best := greatest(best, run);
    elsif d = today then
      null;
    elsif run > 0 and (forgiven is null or d - forgiven >= 7) then
      forgiven := d;
    else
      run := 0;
      forgiven := null;
    end if;
  end loop;
  return json_build_object('current', run, 'best', best, 'today', today = any(days),
                           'grace_used', forgiven is not null and today - forgiven < 7);
end $$;
revoke all on function public.battle_streak(uuid) from public, anon, authenticated;

create or replace function public.my_battle_streak() returns json
language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  return battle_streak(auth.uid());
end $$;
revoke all on function public.my_battle_streak() from public, anon;
grant execute on function public.my_battle_streak() to authenticated;

insert into public.achievement_definitions (code, audience, label, criteria, sort) values
  ('streak_7', 'member', 'Art Battle Streak · 7 days', 'Voted in the Art Battle 7 days running (one missed day a week is forgiven).', 70),
  ('streak_30', 'member', 'Art Battle Streak · 30 days', 'Voted in the Art Battle 30 days running (one missed day a week is forgiven).', 71),
  ('streak_100', 'member', 'Art Battle Streak · 100 days', 'Voted in the Art Battle 100 days running (one missed day a week is forgiven).', 72)
on conflict (code) do update set audience = excluded.audience, label = excluded.label, criteria = excluded.criteria, sort = excluded.sort;

-- Awards streak milestones as votes arrive (only on a member's first vote of the day).
create or replace function public.award_battle_streak() returns trigger
language plpgsql security definer set search_path = public as $$
declare best integer;
begin
  if exists (select 1 from battle_votes v where v.user_id = new.user_id and v.id <> new.id
               and (v.created_at at time zone 'utc')::date = (new.created_at at time zone 'utc')::date) then
    return null;
  end if;
  best := (battle_streak(new.user_id)->>'best')::int;
  insert into member_achievements (user_id, code, evidence)
  select new.user_id, m.code, jsonb_build_object('days', best)
  from (values (7, 'streak_7'), (30, 'streak_30'), (100, 'streak_100')) m(n, code)
  where best >= m.n
  on conflict (user_id, code) do nothing;
  return null;
end $$;
revoke all on function public.award_battle_streak() from public, anon, authenticated;
drop trigger if exists battle_streak_awards on public.battle_votes;
create trigger battle_streak_awards after insert on public.battle_votes
  for each row execute function public.award_battle_streak();

-- ——— 5. Schedule: freeze last month on the 1st at 00:23 UTC ———
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('abremi-season-close', '23 0 1 * *',
      'select public.close_season((date_trunc(''month'', now() at time zone ''utc'') - interval ''1 month'')::date);');
  end if;
exception when others then
  raise notice 'Schedule not set up (%). Seasons need pg_cron to be frozen each month.', sqlerrm;
end $$;

-- ═════ 0019_founding_artists.sql ═════
-- 0019: Founding artists. Moderators pick member artists to feature in a clearly labelled
-- "Founding artists" section and badge. Editorial only: no ranking, score, chart or Index reads
-- this table (tests/db.test.js checks), and it can't be bought.

create table if not exists public.founding_artists (
  artist_id text primary key references public.artists (id) on delete cascade,
  added_at timestamptz not null default now(),
  added_by uuid references public.profiles (id) on delete set null
);
alter table public.founding_artists enable row level security;
drop policy if exists "founding artists are public" on public.founding_artists;
create policy "founding artists are public" on public.founding_artists for select using (true);
revoke all on public.founding_artists from anon, authenticated;
grant select on public.founding_artists to anon, authenticated;

-- The featured artists, earliest first: member artists with at least one published, visible work.
create or replace function public.founding_artists_list() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_agg(json_build_object('artist_id', f.artist_id, 'since', f.added_at) order by f.added_at, f.artist_id), '[]'::json)
  from founding_artists f join artists ar on ar.id = f.artist_id
  where ar.owner_id is not null
    and exists (select 1 from artworks w where w.artist_id = ar.id and not w.hidden and (w.release_at is null or w.release_at <= now()))
$$;
revoke all on function public.founding_artists_list() from public;
grant execute on function public.founding_artists_list() to anon, authenticated;

-- Moderators add or remove a founding artist (member artists only). Logged in the audit trail.
create or replace function public.admin_set_founding(p_artist text, p_on boolean) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  if not exists (select 1 from artists where id = p_artist and owner_id is not null) then
    raise exception 'Only member artists can be founding artists';
  end if;
  if p_on then
    insert into founding_artists (artist_id, added_by) values (p_artist, auth.uid()) on conflict (artist_id) do nothing;
  else
    delete from founding_artists where artist_id = p_artist;
  end if;
  perform log_audit(case when p_on then 'artist.founding_added' else 'artist.founding_removed' end, 'artist', p_artist, '{}'::jsonb);
  return p_on;
end $$;
revoke all on function public.admin_set_founding(text, boolean) from public, anon;
grant execute on function public.admin_set_founding(text, boolean) to authenticated;

-- ═════ 0020_verified_certificates.sql ═════
-- 0020: Verified artists and certificates of authenticity.
--   Verified: a moderator confirms an artist's identity (or that the family runs the studio with the
--   artist's permission). A ✓ appears next to the name. Editorial only: rankings never read it.
--   Certificates: every paid sale gets a unique code. Buyer and artist can open a printable
--   certificate, and anyone can check a code at #certificate/CODE (artwork, artist, date, status;
--   never the buyer).

-- ——— 1. Verified artists ———
create table if not exists public.artist_verifications (
  artist_id text primary key references public.artists (id) on delete cascade,
  managed_by_family boolean not null default false,
  verified_at timestamptz not null default now(),
  verified_by uuid references public.profiles (id) on delete set null
);
alter table public.artist_verifications enable row level security;
drop policy if exists "verifications are public" on public.artist_verifications;
create policy "verifications are public" on public.artist_verifications for select using (true);
revoke all on public.artist_verifications from anon, authenticated;
grant select on public.artist_verifications to anon, authenticated;

create or replace function public.verified_artists() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_agg(json_build_object('artist_id', v.artist_id, 'managed', v.managed_by_family, 'since', v.verified_at) order by v.verified_at), '[]'::json)
  from artist_verifications v join artists ar on ar.id = v.artist_id where ar.owner_id is not null
$$;
revoke all on function public.verified_artists() from public;
grant execute on function public.verified_artists() to anon, authenticated;

create or replace function public.admin_set_verified(p_artist text, p_on boolean, p_managed boolean default false) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  if not exists (select 1 from artists where id = p_artist and owner_id is not null) then
    raise exception 'Only member artists can be verified';
  end if;
  if p_on then
    insert into artist_verifications (artist_id, managed_by_family, verified_by) values (p_artist, coalesce(p_managed, false), auth.uid())
    on conflict (artist_id) do update set managed_by_family = excluded.managed_by_family, verified_by = excluded.verified_by, verified_at = now();
  else
    delete from artist_verifications where artist_id = p_artist;
  end if;
  perform log_audit(case when p_on then 'artist.verified' else 'artist.unverified' end, 'artist', p_artist,
                    jsonb_build_object('managed_by_family', coalesce(p_managed, false)));
  return p_on;
end $$;
revoke all on function public.admin_set_verified(text, boolean, boolean) from public, anon;
grant execute on function public.admin_set_verified(text, boolean, boolean) to authenticated;

-- ——— 2. Certificates of authenticity ———
alter table public.orders add column if not exists certificate_code text unique;

create or replace function public.issue_certificate_code() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.certificate_code is null and new.status in ('paid', 'shipped', 'delivered', 'disputed', 'refunded') then
    new.certificate_code := 'ABR-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 4)) || '-'
      || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 4)) || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 4));
  end if;
  return new;
end $$;
revoke all on function public.issue_certificate_code() from public, anon, authenticated;
drop trigger if exists orders_certificate on public.orders;
create trigger orders_certificate before insert or update of status on public.orders
  for each row execute function public.issue_certificate_code();
update public.orders set status = status where certificate_code is null and status in ('paid', 'shipped', 'delivered', 'disputed', 'refunded');

-- Anyone can check a certificate: the artwork, artist, date and whether it still stands. Never the buyer.
create or replace function public.verify_certificate(p_code text) returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'code', o.certificate_code, 'artwork_id', o.artwork_id, 'title', o.title,
    'artist_id', o.artist_id, 'artist', ar.name, 'country', ar.country,
    'verified', exists (select 1 from artist_verifications v where v.artist_id = o.artist_id),
    'year', w.year, 'medium', w.medium, 'dimensions', w.dimensions, 'category', w.category,
    'edition_number', o.edition_number, 'edition_size', w.edition_size,
    'issued_at', o.paid_at,
    'valid', o.status in ('paid', 'shipped', 'delivered'),
    'status', case when o.status = 'refunded' then 'void' when o.status = 'disputed' then 'under_review' else 'valid' end)
  from orders o join artists ar on ar.id = o.artist_id left join artworks w on w.id = o.artwork_id
  where o.certificate_code = upper(btrim(coalesce(p_code, ''))) and o.certificate_code is not null
$$;
revoke all on function public.verify_certificate(text) from public;
grant execute on function public.verify_certificate(text) to anon, authenticated;

-- my_orders() now includes each order's certificate code.
create or replace function public.my_orders() returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'sales', coalesce((select json_agg(json_build_object('id', o.id, 'artwork_id', o.artwork_id, 'title', o.title, 'amount_cents', o.amount_cents, 'fee_cents', o.fee_cents,
              'currency', o.currency, 'edition_number', o.edition_number, 'status', o.status, 'shipping', o.shipping, 'carrier', o.carrier, 'tracking', o.tracking,
              'buyer', (select name from profiles where id = o.buyer_id), 'paid_at', o.paid_at, 'shipped_at', o.shipped_at, 'delivered_at', o.delivered_at,
              'dispute_reason', o.dispute_reason, 'dispute_resolution', o.dispute_resolution, 'certificate', o.certificate_code) order by o.created_at desc)
              from orders o where o.artist_user = auth.uid() and o.status not in ('pending', 'cancelled')), '[]'::json),
    'purchases', coalesce((select json_agg(json_build_object('id', o.id, 'artwork_id', o.artwork_id, 'title', o.title, 'amount_cents', o.amount_cents,
              'currency', o.currency, 'edition_number', o.edition_number, 'status', o.status, 'carrier', o.carrier, 'tracking', o.tracking,
              'artist', (select name from artists where id = o.artist_id), 'paid_at', o.paid_at, 'shipped_at', o.shipped_at, 'delivered_at', o.delivered_at,
              'dispute_reason', o.dispute_reason, 'dispute_resolution', o.dispute_resolution,
              'certificate', o.certificate_code,
              'can_dispute', o.status in ('paid', 'shipped') or (o.status = 'delivered' and o.delivered_at > now() - interval '14 days')) order by o.created_at desc)
              from orders o where o.buyer_id = auth.uid() and o.status not in ('pending', 'cancelled')), '[]'::json))
  where auth.uid() is not null
$$;

-- ═════ 0021_active_since.sql ═════
-- 0021: "Active since": an artist can give the year their career began (shown as "Active since
-- 1994"). Artists who don't are shown as "On Abremi since <year they joined>". Display only:
-- nothing in the rankings reads it (the "new artist" signals keep using the join date).

alter table public.artists add column if not exists active_since integer;
do $$ begin
  alter table public.artists add constraint artists_active_since_valid check (active_since is null or active_since between 1900 and 2100);
exception when duplicate_object then null;
end $$;

-- Set (or clear, with null) your own artist's year. Not in the future.
create or replace function public.set_active_since(p_year integer) returns integer
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if p_year is not null and (p_year < 1900 or p_year > extract(year from now())::int) then
    raise exception 'Enter a year between 1900 and this year' using errcode = '22023';
  end if;
  perform ensure_member_artist(uid);
  update artists set active_since = p_year, updated_at = now() where owner_id = uid;
  return p_year;
end $$;
revoke all on function public.set_active_since(integer) from public, anon;
grant execute on function public.set_active_since(integer) to authenticated;

-- Everyone can read the years (member artists only).
create or replace function public.artists_active_since() returns json
language sql stable security definer set search_path = public as $$
  select coalesce(json_agg(json_build_object('artist_id', id, 'year', active_since)), '[]'::json)
  from artists where owner_id is not null and active_since is not null
$$;
revoke all on function public.artists_active_since() from public;
grant execute on function public.artists_active_since() to anon, authenticated;

